let selectedConversionHtmlModule = "summary";
const CONVERSION_JOURNEY_SETTINGS_KEY = "tb-conversion-journey-settings-v1";
const DEFAULT_CONVERSION_JOURNEY_SETTINGS = Object.freeze({
  density: "standard",
  showGuide: true,
  showBranches: true,
  showScript: true,
  openDetails: false
});
let conversionJourneySettingsOpen = false;
let conversionJourneySettings = readConversionJourneySettings();
let materialRenderLimit = 12;
let productRenderLimit = 8;
let collectionFilters = { stage: "mobile" };
const COLLECTION_STAGE_DEFAULTS = {
  mobile: "仓库 1（抖音小红书可发）",
  official: "仓库 2（微信公众号可发）",
  used: "仓库 3（已发送）"
};
const COLLECTION_STAGE_SETTINGS_KEY = "teambuilding-collection-stage-settings-v1";

function normalizeConversionJourneySettings(value) {
  const input = value && typeof value === "object" ? value : {};
  return {
    density: ["compact", "standard", "detailed"].includes(input.density) ? input.density : DEFAULT_CONVERSION_JOURNEY_SETTINGS.density,
    showGuide: input.showGuide !== false,
    showBranches: input.showBranches !== false,
    showScript: input.showScript !== false,
    openDetails: input.openDetails === true
  };
}

function readConversionJourneySettings() {
  try {
    return normalizeConversionJourneySettings(JSON.parse(localStorage.getItem(CONVERSION_JOURNEY_SETTINGS_KEY) || "{}"));
  } catch {
    return { ...DEFAULT_CONVERSION_JOURNEY_SETTINGS };
  }
}

function saveConversionJourneySettings() {
  try { localStorage.setItem(CONVERSION_JOURNEY_SETTINGS_KEY, JSON.stringify(conversionJourneySettings)); } catch { /* private mode */ }
}

function readCollectionStageSettings() {
  try {
    const value = JSON.parse(window.localStorage.getItem(COLLECTION_STAGE_SETTINGS_KEY) || "{}");
    return value && typeof value === "object" ? value : {};
  } catch {
    return {};
  }
}

function collectionStageSettings(stage) {
  const settings = readCollectionStageSettings();
  const item = settings?.[stage];
  return item && typeof item === "object" ? item : {};
}

function collectionStageLabel(stage) {
  const configured = String(collectionStageSettings(stage).label || "").trim();
  return configured || COLLECTION_STAGE_DEFAULTS[stage] || "仓库";
}

function saveCollectionStageSetting(stage, patch) {
  const settings = readCollectionStageSettings();
  settings[stage] = { ...collectionStageSettings(stage), ...patch };
  window.localStorage.setItem(COLLECTION_STAGE_SETTINGS_KEY, JSON.stringify(settings));
}

function resetCollectionStageSetting(stage) {
  const settings = readCollectionStageSettings();
  delete settings[stage];
  window.localStorage.setItem(COLLECTION_STAGE_SETTINGS_KEY, JSON.stringify(settings));
}
