// retried for a bounded period, but it must eventually leave a durable
// checkpoint instead of recursively scheduling timers forever.
const GPT_PRODUCTION_READINESS_RECOVERY_BUDGET_MS = 20 * 60_000;
const GPT_PRODUCTION_READINESS_RECOVERY_MAX_ATTEMPTS = 8;
const GPT_WINDOW_RECOVERY_BUDGET_MS = 20 * 60_000;
const GPT_WINDOW_RECOVERY_MAX_ATTEMPTS = 8;
const gptTemporaryCacheMaintenanceTimers = new Map();
const gptAccountRefreshPromises = new Map();
// A maintenance call can outlive the readiness probe that started it. Keep a
// synchronous per-account guard as well as the promise map so a new worker
// cannot start in the small gap between invoking the native refresh and
// registering its promise. Otherwise the refresh aborts that worker's upload.
const gptWindowRefreshInFlight = new Set();
const gptConversationRecoveryPromises = new Map();
const gptWindowRetryTimers = new Map();
const gptWindowRetryRecoveryStates = new Map();
// One lock covers refresh, renderer recreation, and checkpoint reconciliation
// for an account.  Previously each watchdog owned a different counter, so a
// single incident could issue 128 real reloads while reporting only 9 tries.
const gptWindowRecoveryLocks = new Map();
let gptGlobalRecoveryRestartAt = 0;
const gptProductionRetryTimers = new Map();
const gptProductionRetryStates = new Map();
const gptWindowCheckpointRestorePromises = new Map();
const gptWindowStuckBoundaryProbeAt = new Map();
const gptWindowStuckBoundaryProbePromises = new Map();
const gptWindowAutoRefreshAt = new Map();
const gptWindowAutoRefreshHistory = new Map();
let gptAutoMaterialCatalogPromise = null;
const gptAutoMaterialReservations = new Map();
let gptRuntimeSyncTimer = null;
let pendingGptRuntimeSnapshot = null;
let gptRuntimeSyncInFlight = Promise.resolve();

async function withGptWindowRecoveryLock(accountId, reason, callback) {
  const key = String(accountId || activeGptAccountId || "").trim();
  if (!key || typeof callback !== "function") return { ok: false, skipped: "invalid-recovery-lock" };
  const existing = gptWindowRecoveryLocks.get(key);
  if (existing) return { ok: false, skipped: "recovery-in-flight", accountId: key, recoveryRequestId: existing.requestId };
  const lock = {
    accountId: key,
    requestId: `recovery-${key}-${Date.now()}`,
    reason: String(reason || "automatic-recovery").slice(0, 120),
    startedAt: Date.now()
  };
  gptWindowRecoveryLocks.set(key, lock);
  try {
    return await callback(lock);
  } finally {
    if (gptWindowRecoveryLocks.get(key) === lock) gptWindowRecoveryLocks.delete(key);
  }
}

function shouldAutoRefreshGptWindowForRecovery(reason = "") {
  return /网页\/桥接临时失败|当前网页检查点待完成|GPT_INSPECTION_UNAVAILABLE|GPT_PAGE_NOT_READY|GPT_PAGE_LOAD_TIMEOUT|EXTENSION_NOT_READY|COMPOSER_NOT_READY|LOCAL_BRIDGE_FETCH_FAILED|无法确认当前 GPT 对话状态|先刷新当前 GPT 窗口|Failed to fetch|fetch failed|本地工作台连接失败|扩展尚未就绪|正在准备 GPT 网页|页面仍在加载|等待 GPT 输入框/i.test(String(reason || ""));
}

async function refreshGptWindowForAutomaticRecovery(accountId = activeGptAccountId, reason = "automatic-readiness-recovery", options = {}) {
  const key = String(accountId || activeGptAccountId);
  if (!gptWindowAutoStartAllowed(key)) return { ok: false, skipped: "user-hold", accountId: key };
  const activeRecoveryLock = gptWindowRecoveryLocks.get(key);
  if (activeRecoveryLock && String(options.recoveryRequestId || "") !== activeRecoveryLock.requestId) {
    return { ok: false, skipped: "recovery-in-flight", accountId: key };
  }
  const controlledRecovery = options.controlledRecovery === true
    && options.safeToRecover === true;
  // A busy ChatGPT renderer can take several seconds to answer a read-only
  // status probe while it is generating images or copy. Never turn that
  // transient probe timeout into a reload of the same account's live task;
  // the task bridge owns recovery at this boundary and a reload here would
  // emit ERR_ABORTED (-3), lose the in-flight page response, and look like a
  // dead Continue/Retry button.
  const activeWorker = gptWindowWorkerState(key);
  const activeRuntime = readGptWindowRuntime(key);
  const activeQueueTask = Array.isArray(activeWorker.queue)
    ? activeWorker.queue[Number(activeWorker.queueIndex)]
    : null;
  const freshRootBootstrapActive = (activeQueueTask?._freshConversationBootstrap === true
    || activeQueueTask?.freshConversationBootstrap === true
    || activeQueueTask?.workflowVariant === "fresh-session-fixed-template"
    || activeQueueTask?.sessionPolicy === "fresh-session")
    && !isUnownedSubmittedFreshGptTask(activeQueueTask, activeRuntime);
  // Once the old /c URL has been proved invalid, the current worker owns a
  // root-page bootstrap. A stale heartbeat callback must not recreate that
  // view back to the dead URL while attachments are being prepared.
  if (freshRootBootstrapActive && activeWorker.autoRunning === true) {
    return { ok: true, skipped: "fresh-root-bootstrap-active", accountId: key };
  }
  const recoveryRequestId = String(options.requestId || "").trim();
  const activeTaskRequestId = String(
    activeWorker.currentTaskId
      || activeQueueTask?.requestId
      || activeRuntime.currentTaskId
      || ""
  ).trim();
  // The heartbeat-loss path has already sent the native stop command and
  // settled the task promise before it asks for a page refresh.  The account
  // worker is still technically alive until its outer loop returns, so the
  // normal "active worker means never reload" guard would incorrectly skip
  // the only refresh that can clear a stale composer/bridge boundary.  Allow
  // that one exact request to refresh; all unrelated active tasks remain
  // protected from an accidental reload.
  const settledHeartbeatRecovery = options.allowActiveTaskRecovery === true
    && Boolean(recoveryRequestId)
    && recoveryRequestId === activeTaskRequestId;
  // The worker promise is the ownership source. A heartbeat timeout has
  // already moved the task back to its durable checkpoint, but the runner is
  // still alive while it probes the page. Reloading here aborts that runner
  // and creates the refresh-without-execution loop this recovery path is
  // meant to prevent.
  // A "controlled" recovery only means the caller owns the recovery lock; it
  // does not mean it may refresh through a newly reattached live worker. Old
  // retry timers can wake after that worker has already resumed the same
  // request (including just after sending `1`). Protect the live worker unless
  // this is the one heartbeat path that explicitly settled its native request.
  const workerOwnsTask = !settledHeartbeatRecovery && (Boolean(activeWorker.autoRunning)
    || (activeWorker.autoRunning && (
      String(activeWorker.currentTaskId || "").trim()
      || activeQueueTask?._status === "running"
    )));
  // The durable runtime mirror can be ahead of the renderer after an app
  // restart, or can be in retry-wait after a bridge promise has already
  // settled. Treat every non-terminal checkpoint with an owner as live even
  // before the UI worker has reattached; otherwise automatic readiness
  // maintenance reloads the exact page that is about to resume and produces
  // another ERR_ABORTED/ERR_FAILED loop. The one exact heartbeat recovery
  // request above remains allowed after the task was explicitly settled.
  // A retained checkpoint in retry-wait/failed/probing is not a live browser
  // operation. When its worker has already settled, treating that checkpoint
  // as an active task prevents the only safe renderer recreation and leaves
  // the account in an endless bridge-wait loop. Running remains protected;
  // recoverable waiting states may use the bounded refresh/recreate policy.
  const runtimeOwnsTask = !settledHeartbeatRecovery && !controlledRecovery
    && String(activeRuntime.currentTaskId || "").trim()
    && !["idle", "completed", "waiting-quota", "retry-wait", "failed", "probing"].includes(String(activeRuntime.status || ""))
    && activeRuntime.pausedByUser !== true
    && activeRuntime.stoppedByUser !== true;
  if (workerOwnsTask || runtimeOwnsTask) {
    return { ok: true, skipped: "active-task", accountId: key };
  }
  const now = Date.now();
  const lastRefreshAt = Number(gptWindowAutoRefreshAt.get(key) || 0);
  if (lastRefreshAt && now - lastRefreshAt < GPT_AUTOMATIC_RECOVERY_REFRESH_COOLDOWN_MS) {
    return { ok: true, skipped: "cooldown", accountId: key, retryAt: lastRefreshAt + GPT_AUTOMATIC_RECOVERY_REFRESH_COOLDOWN_MS };
  }
  const persistedRefreshHistory = Array.isArray(activeRuntime.automaticRefreshHistory)
    ? activeRuntime.automaticRefreshHistory
    : [];
  const inMemoryRefreshHistory = gptWindowAutoRefreshHistory.get(key);
  const storedRefreshHistory = Array.isArray(inMemoryRefreshHistory)
    ? inMemoryRefreshHistory
    : persistedRefreshHistory;
  const refreshHistory = (Array.isArray(storedRefreshHistory) ? storedRefreshHistory : [])
    .filter((timestamp) => now - Number(timestamp || 0) < GPT_AUTOMATIC_RECOVERY_REFRESH_WINDOW_MS);
  gptWindowAutoRefreshHistory.set(key, refreshHistory);
  if (refreshHistory.length >= GPT_AUTOMATIC_RECOVERY_MAX_REFRESHES) {
    const retryAt = Math.min(...refreshHistory) + GPT_AUTOMATIC_RECOVERY_REFRESH_WINDOW_MS;
    writeGptWindowRuntime(key, {
      status: "retry-wait",
      currentStage: "网页识别暂时不可用，已停止重复刷新，等待就绪探测",
      nextRetryAt: retryAt,
      lastError: "自动刷新已达到 10 分钟内 2 次上限；保留当前检查点，网页就绪后直接续接",
      automaticRefreshHistory: refreshHistory
    });
    showWorkbenchAssistantBubble(`${gptAccounts.find((item) => item.id === key)?.name || "当前账号窗口"} 已停止重复刷新（10 分钟内最多 2 次），保留当前素材并等待网页就绪后自动继续。`, { duration: 0, tone: "warning" });
    return { ok: true, skipped: "refresh-limit", refreshLimit: true, accountId: key, retryAt };
  }
  if (!window.gptWorkbench?.maintenance && !window.gptWorkbench?.reload) {
    return { ok: false, accountId: key, error: "桌面 GPT 刷新入口不可用" };
  }
  gptWindowAutoRefreshAt.set(key, now);
  gptWindowAutoRefreshHistory.set(key, [...refreshHistory, now]);
  writeGptWindowRuntime(key, {
    status: "retry-wait",
    currentStage: "自动刷新 GPT 窗口，准备恢复",
    nextRetryAt: null,
    lastError: "",
    automaticRefreshHistory: [...refreshHistory, now]
  });
  showWorkbenchAssistantBubble(`${gptAccounts.find((item) => item.id === key)?.name || "当前账号窗口"}检测到网页状态异常，正在自动刷新并从当前检查点恢复。`, { duration: 3600, tone: "warning" });
  try {
    const result = window.gptWorkbench.maintenance
      ? await refreshGptAfterProduction(key, reason)
      : await window.gptWorkbench.reload(key);
    if (result?.deferred === true || result?.reason === "active-task") {
      return { ...result, ok: true, skipped: "active-task", accountId: key };
    }
    if (!result?.ok) throw new Error(result?.detail || result?.error || "GPT 网页刷新失败");
    writeGptWindowRuntime(key, {
      status: "retry-wait",
      currentStage: "GPT 窗口已刷新，等待网页就绪",
      lastError: ""
    });
    return { ...result, ok: true, accountId: key };
  } catch (error) {
    const message = String(error?.message || error || "GPT 网页刷新失败");
    if (window.gptWorkbench?.recreate) {
       const recreated = await window.gptWorkbench.recreate({
         accountId: key,
         reason: `${reason}-renderer-recreate`,
         forceRecovery: true,
         controlledRecovery: true,
         allowActiveTaskRecovery: controlledRecovery,
         recoveryRequestId: recoveryRequestId || activeTaskRequestId,
         knownConversationUrl: String(options.knownConversationUrl || "")
       }).catch(() => null);
      if (recreated?.ok) {
        writeGptWindowRuntime(key, {
          status: "retry-wait",
          currentStage: "GPT 窗口已重建，等待网页就绪",
          lastError: ""
        });
        return { ...recreated, ok: true, accountId: key, recreated: true };
      }
    }
    writeGptWindowRuntime(key, { status: "retry-wait", currentStage: "自动刷新失败，稍后重试", lastError: message });
    return { ok: false, accountId: key, error: message };
  }
}

function knownGptConversationUrl(accountId, runtime = {}) {
  const key = String(accountId || "");
  const account = gptAccounts.find((item) => item.id === key);
  // The queue task is the authoritative owner of the conversation during
  // automatic recovery.  A renderer can retain an older URL in runtime after
  // a failed embedded-view recreation; preferring that stale runtime URL
  // would reconnect the account to the wrong chat and make a valid checkpoint
  // look like a missing plan/image boundary.
  const state = typeof gptWindowWorkerState === "function"
    ? gptWindowWorkerState(key)
    : null;
  const currentTaskId = String(runtime.currentTaskId || "").trim();
  const queuedTask = (state?.queue || []).find((task) => (
    String(task?.requestId || "").trim() === currentTaskId
  )) || state?.queue?.[state?.queueIndex];
  const queuedTaskFreshSession = queuedTask?._freshConversationBootstrap === true
    || queuedTask?.freshConversationBootstrap === true
    || queuedTask?.workflowVariant === "fresh-session-fixed-template"
    || queuedTask?.sessionPolicy === "fresh-session";
  if (queuedTaskFreshSession) {
    const queuedTaskSubmitted = queuedTask?._submittedToGpt === true
      || queuedTask?.submittedToGpt === true;
    const queuedTaskOwnerConfirmed = queuedTask?._conversationLogOwnerConfirmed === true
      || queuedTask?.conversationOwnerConfirmed === true;
    // A submitted fresh-session task without explicit owner evidence must not
    // borrow another task's conversation. That is the exact stale-/c/ failure
    // this recovery path is designed to prevent.
    if (queuedTaskSubmitted && !queuedTaskOwnerConfirmed) return "";
    // A stale heartbeat can be stopping an unsent future task while an older
    // submitted task still owns the live `/c/...` conversation. Prefer that
    // submitted owner for renderer recovery; otherwise native recovery treats
    // the page as a fresh root and navigates away from the real checkpoint.
    const submittedOwner = (state?.queue || []).find((task) => (
      task
      && task !== queuedTask
      && task._submittedToGpt === true
      && !["completed", "archived", "skipped"].includes(String(task._status || ""))
      && /\/c\//i.test(String(
        task.conversationUrl || task.chatUrl || task.browserConversationUrl || ""
      ))
    ));
    const submittedOwnerUrl = String(
      submittedOwner?.conversationUrl
        || submittedOwner?.chatUrl
        || submittedOwner?.browserConversationUrl
        || ""
    ).trim();
    if (submittedOwnerUrl) return submittedOwnerUrl.split(/[?#]/)[0];
    return "";
  }
  const taskCandidate = String(
    queuedTask?.conversationUrl
      || queuedTask?.chatUrl
      || queuedTask?.browserConversationUrl
      || ""
  ).trim();
  if (/\/c\//i.test(taskCandidate)) return taskCandidate.split(/[?#]/)[0];
  const candidate = String(
    runtime.conversationUrl
      || runtime.browserConversationUrl
      || account?.lastConversationUrl
      || account?.lastBrowserUrl
      || ""
  ).trim();
  return /\/c\//i.test(candidate) ? candidate.split(/[?#]/)[0] : "";
}

function isUnownedSubmittedFreshGptTask(task, runtime = {}) {
  if (!task || task.taskType !== "material") return false;
  const freshSession = task._freshConversationBootstrap === true
    || task.freshConversationBootstrap === true
    || task.workflowVariant === "fresh-session-fixed-template"
    || task.sessionPolicy === "fresh-session"
    || runtime.workflowVariant === "fresh-session-fixed-template"
    || runtime.sessionPolicy === "fresh-session";
  const submitted = task._submittedToGpt === true || task.submittedToGpt === true;
  const ownerConfirmed = task._conversationLogOwnerConfirmed === true
    || task.conversationOwnerConfirmed === true;
  return freshSession && submitted && !ownerConfirmed;
}

async function recreateGptWindowForAutomaticRecovery(accountId, reason, options = {}) {
  const key = String(accountId || activeGptAccountId);
  const runtime = readGptWindowRuntime(key);
  if (!gptWindowAutoStartAllowed(key)) return { ok: false, skipped: "user-hold", accountId: key };
  if (options.safeToRecover !== true) return { ok: false, skipped: "unsafe-live-stage", accountId: key };
  const requestId = String(options.requestId || runtime.currentTaskId || "").trim();
  // End the stale renderer-side promise before releasing the embedded view.
  // This is automatic recovery, not a user stop, so the worker checkpoint is
  // kept queued and the next worker owns the same request ID.
  if (requestId && window.gptWorkbench?.stopCurrentTask) {
    await window.gptWorkbench.stopCurrentTask(key, requestId, {
      userInitiated: false,
      reason: "automatic-browser-recreate"
    }).catch(() => {});
  }
  const state = gptWindowWorkerState(key);
  const activeTask = (state?.queue || []).find((task) => (
    String(task?.requestId || "").trim() === requestId
  )) || state?.queue?.[state?.queueIndex];
  const freshSession = activeTask?._freshConversationBootstrap === true
    || activeTask?.freshConversationBootstrap === true
    || activeTask?.workflowVariant === "fresh-session-fixed-template"
    || activeTask?.sessionPolicy === "fresh-session"
    || runtime.workflowVariant === "fresh-session-fixed-template"
    || runtime.sessionPolicy === "fresh-session";
  const taskOwnerConfirmed = activeTask?._conversationLogOwnerConfirmed === true
    || activeTask?.conversationOwnerConfirmed === true;
  const freshRoot = freshSession && !taskOwnerConfirmed;
  const url = freshRoot ? "" : knownGptConversationUrl(key, runtime);
  writeGptWindowRuntime(key, {
    status: "probing",
    currentTaskId: requestId,
    currentStage: "重建原 GPT 对话窗口",
    nextRetryAt: null,
    lastError: "",
    recoveryAction: "recreate-browser",
    recoveryStartedAt: Date.now(),
    conversationUrl: url
  });
  const recreated = await window.gptWorkbench?.recreate?.({
    accountId: key,
    reason: String(reason || "automatic-browser-recreate"),
    forceRecovery: true,
    controlledRecovery: true,
    allowActiveTaskRecovery: true,
    recoveryRequestId: requestId,
    knownConversationUrl: url,
    freshRoot,
    invalidConversationUrl: freshRoot ? String(activeTask?._staleConversationUrl || "") : ""
  }).catch((error) => ({ ok: false, error: error?.message || String(error) }));
  if (!recreated?.ok) {
    writeGptWindowRuntime(key, {
      status: "retry-wait",
      currentTaskId: requestId,
      currentStage: "浏览器重建失败，保留当前检查点",
      lastError: String(recreated?.error || "浏览器窗口重建失败")
    });
  }
  return { ...recreated, accountId: key, knownConversationUrl: url };
}

async function maybeRestartGptWorkbenchAfterRecovery(detail = "") {
  const eligible = [];
  const unavailable = [];
  const userHeld = [];
  const quotaWaiting = [];
  const now = Date.now();
  for (const account of gptAccounts.filter((item) => !item.hidden && !item.disabled)) {
    const key = String(account.id);
    const settings = gptWindowSettings(key);
    if (normalizeGptProductionMode(settings.mode) !== "single") continue;
    if (!gptWindowAutoStartAllowed(key)) {
      userHeld.push(key);
      continue;
    }
    const workWindow = getGptContinuousWorkWindow(new Date(), settings);
    if (!workWindow.allowed) continue;
    const runtime = readGptWindowRuntime(key);
    if (runtime.status === "waiting-quota" || runtime.status === "login-required") {
      quotaWaiting.push(key);
      continue;
    }
    eligible.push(key);
    const stage = String(runtime.currentStage || "");
    const activeGeneration = /生图|生成图片|等待图片|生成中|response/i.test(stage)
      && !["retry-wait", "failed", "probing"].includes(String(runtime.status || ""));
    const lastProgressAt = Date.parse(String(runtime.lastProgressAt || "")) || Number(runtime.lastProgressAt || 0);
    const stale = runtime.status === "retry-wait"
      || runtime.status === "failed"
      || runtime.status === "probing"
      || Boolean(runtime.windowRecoveryExhaustedAt);
    if (!activeGeneration && stale && (!lastProgressAt || now - lastProgressAt >= (window.GptWindowWorkerState?.NO_PROGRESS_RECOVERY_LINE_MS || 10 * 60_000))) {
      unavailable.push(key);
    }
  }
  const shouldRestart = window.GptWindowWorkerState?.shouldRestartAllWindows?.({
    eligibleWindows: eligible,
    unavailableWindows: unavailable,
    userHeldWindows: userHeld,
    quotaWaitingWindows: quotaWaiting,
    now,
    lastRestartAt: gptGlobalRecoveryRestartAt
  }) === true;
  if (!shouldRestart || !window.gptWorkbench?.restartApp) return { ok: false, skipped: "not-all-windows-unavailable", eligible, unavailable };
  gptGlobalRecoveryRestartAt = now;
  const message = `所有启用的自动窗口均无进展，已保存检查点并有序重启工作台：${String(detail || "网页桥接恢复耗尽").slice(0, 160)}`;
  for (const key of unavailable) {
    writeGptWindowRuntime(key, {
      status: "probing",
      currentStage: "保存检查点后重启工作台",
      lastError: message,
      recoveryAction: "restart-workbench",
      recoveryStartedAt: now
    });
  }
  logGptReadinessRecoveryEvent(
    unavailable[0] || eligible[0] || "account-1",
    "gpt-global-recovery-restart",
    { status: "restart-workbench", startedAt: now, endedAt: now, attempts: 1 },
    `${message}；账号=${eligible.join(",")}`,
    "window-reconnect"
  );
  showWorkbenchAssistantBubble(message, { duration: 0, tone: "warning" });
  const result = await window.gptWorkbench.restartApp({ source: "gpt-global-recovery", interactive: false }).catch((error) => ({ ok: false, error: error?.message || String(error) }));
  return { ...result, eligible, unavailable };
}

function scheduleGptWindowRetry(accountId = activeGptAccountId, delayMs = 15_000, reason = "网页尚未就绪", recoveryOptions = {}) {
  const key = String(accountId || activeGptAccountId);
  if (gptWindowRetryTimers.has(key)) return;
  const runtime = readGptWindowRuntime(key);
  if (!gptWindowAutoStartAllowed(key)) return;
  // Startup staggering is a launch gate, not a web-recovery failure. A
  // persisted recovery task can survive an app restart while the lane is
  // intentionally waiting for its 5–10 minute launch slot. Do not re-enter
  // the recovery scheduler from that boundary: it previously replayed the
  // same exhausted recovery task and inflated attempts into the hundreds.
  if (runtime.status === "waiting-startup-stagger"
    || String(runtime.currentStage || "").startsWith("启动错峰：")) {
    gptWindowRetryRecoveryStates.delete(key);
    writeGptWindowRuntime(key, {
      windowRecoveryStartedAt: null,
      windowRecoveryDeadlineAt: null,
      windowRecoveryAttempts: 0,
      windowRecoveryTaskId: null,
      windowRecoveryExhaustedAt: null,
      nextRetryAt: runtime.nextRetryAt || null
    });
    scheduleGptStartupStaggerWake(Math.max(1_000, Number(runtime.nextRetryAt || 0) - Date.now()));
    return { ok: true, skipped: "startup-stagger-boundary", accountId: key };
  }
  // The timer is removed when its callback starts. Keep a separate in-flight
  // marker so another watchdog cannot schedule a second recovery while this
  // account is still probing/reconciling the same conversation.
  const previousRecovery = gptWindowRetryRecoveryStates.get(key);
  if (previousRecovery?.inFlight === true) {
    return { ok: true, skipped: "recovery-in-flight", accountId: key };
  }
  const now = Date.now();
  const workerState = gptWindowWorkerState(key);
  const queue = Array.isArray(workerState.queue) ? workerState.queue : [];
  const isTerminalRecoveryTask = (task) => ["completed", "archived", "skipped"]
    .includes(String(task?._status || "").trim().toLowerCase());
  const queueIndex = Math.max(0, Number(workerState.queueIndex || 0));
  const queuedTask = queue[queueIndex] || null;
  const nextActiveQueueTask = !isTerminalRecoveryTask(queuedTask)
    ? queuedTask
    : queue.slice(queueIndex + 1).find((task) => !isTerminalRecoveryTask(task)) || null;
  const runtimeTask = queue.find((task) => (
    String(task?.requestId || "").trim() === String(runtime.currentTaskId || "").trim()
      && !isTerminalRecoveryTask(task)
  )) || null;
  const failedTask = !isTerminalRecoveryTask(workerState.lastFailedTask)
    ? workerState.lastFailedTask
    : null;
  // The queue is the ownership source after a successful archive. The
  // runtime mirror can retain the completed request for a short time while
  // the next material is being attached; choosing runtime.currentTaskId
  // first schedules a stale refresh/recovery callback against the just-
  // archived conversation and produces false "recovery exhausted" events.
  const activeTask = nextActiveQueueTask || failedTask || runtimeTask;
  const currentTaskId = String(activeTask?.requestId || "").trim();
  if (!activeTask || !currentTaskId || isTerminalRecoveryTask(activeTask)) {
    gptWindowRetryRecoveryStates.delete(key);
    if (runtime.windowRecoveryTaskId) {
      writeGptWindowRuntime(key, {
        windowRecoveryStartedAt: null,
        windowRecoveryDeadlineAt: null,
        windowRecoveryAttempts: 0,
        windowRecoveryTaskId: null,
        windowRecoveryExhaustedAt: null
      });
    }
    return { ok: true, skipped: "no-active-task", accountId: key };
  }
  // Keep the window recovery budget on the request checkpoint as well as in
  // the renderer runtime.  A successful browser recreation clears the
  // presentation-level retry fields; without a request-owned copy, the next
  // probe could silently open a fresh 15-minute budget forever for the same
  // stuck work.
  const recoveryTask = activeTask;
  const persistedRecoveryTaskId = String(runtime.windowRecoveryTaskId || "").trim();
  const sameTaskRecovery = Boolean(currentTaskId && persistedRecoveryTaskId && currentTaskId === persistedRecoveryTaskId);
  // Recovery budget belongs to one account + one request, never to the whole
  // window. A quarantined/finished request must not make the next material
  // inherit its exhausted attempt counter after restart.
  const previousExhaustedAt = Math.max(
    sameTaskRecovery ? Number(runtime.windowRecoveryExhaustedAt || 0) : 0,
    Number(recoveryTask?._windowRecoveryExhaustedAt || 0)
  );
  const previous = sameTaskRecovery ? (gptWindowRetryRecoveryStates.get(key) || {}) : {};
  const persistedStartedAt = sameTaskRecovery
    ? Math.max(Number(runtime.windowRecoveryStartedAt || 0), Number(recoveryTask?._windowRecoveryStartedAt || 0))
    : Number(recoveryTask?._windowRecoveryStartedAt || 0);
  const persistedDeadlineAt = sameTaskRecovery
    ? Math.max(Number(runtime.windowRecoveryDeadlineAt || 0), Number(recoveryTask?._windowRecoveryDeadlineAt || 0))
    : Number(recoveryTask?._windowRecoveryDeadlineAt || 0);
  const persistedAttempts = Math.max(
    sameTaskRecovery ? Number(runtime.windowRecoveryAttempts || 0) : 0,
    Number(recoveryTask?._windowRecoveryAttempts || 0)
  );
  const persistedRecoveryActive = Boolean(
    persistedStartedAt > 0
      || persistedDeadlineAt > 0
      || persistedAttempts > 0
      || previousExhaustedAt > 0
  );
  const recoveryState = {
    startedAt: Number(previous.startedAt || (persistedRecoveryActive ? persistedStartedAt : 0) || now),
    deadlineAt: Number(previous.deadlineAt || (persistedRecoveryActive ? persistedDeadlineAt : 0) || (now + GPT_WINDOW_RECOVERY_BUDGET_MS)),
    attempts: Math.max(
      recoveryOptions.preserveAttempt === true
        ? 1
        : Number(previous.attempts || 0) + 1,
      recoveryOptions.preserveAttempt === true
        ? Math.max(Number(previous.attempts || 0), persistedAttempts)
        : (persistedRecoveryActive ? persistedAttempts + 1 : 1),
      previousExhaustedAt > 0 ? GPT_WINDOW_RECOVERY_MAX_ATTEMPTS + 1 : 1
    ),
    status: "waiting",
    reason: String(reason || "网页尚未就绪"),
    taskId: currentTaskId
  };
  if (recoveryTask && currentTaskId) {
    recoveryTask._windowRecoveryStartedAt = recoveryState.startedAt;
    recoveryTask._windowRecoveryDeadlineAt = recoveryState.deadlineAt;
    recoveryTask._windowRecoveryAttempts = recoveryState.attempts;
  }
  const exhaust = (detail) => {
    gptWindowRetryRecoveryStates.delete(key);
    const endedAt = Date.now();
    if (recoveryTask) {
      recoveryTask._windowRecoveryExhaustedAt = endedAt;
      recoveryTask._windowRecoveryAttempts = Math.max(
        Number(recoveryTask._windowRecoveryAttempts || 0),
        Number(recoveryState.attempts || 0)
      );
      persistGptWindowWorkerState(key, workerState);
    }
    const message = String(detail || "网页/桥接在有限恢复预算内仍未就绪");
    // If every eligible automatic lane has reached the same bounded failure,
    // restart the workbench once after checkpoints are already durable. Do not
    // quarantine each lane independently and leave the whole factory idle.
    maybeRestartGptWorkbenchAfterRecovery(message).catch(() => {});
    // A window-level timeout must consume the same per-work recovery budget as
    // the worker. Otherwise the cooldown below can reopen retry-wait forever.
    const deferred = deferIndependentGptTaskAfterAutomaticRecovery(
      key,
      `${message}；当前作品已保存检查点并隔离`,
      { quarantine: true, requestId: recoveryState.taskId }
    );
    if (deferred.action === "quarantine" || deferred.action === "defer") {
      logGptReadinessRecoveryEvent(key, "window-recovery-exhausted", {
        ...recoveryState,
        endedAt,
        status: "timeout"
      }, message, "window-reconnect");
      scheduleContinuousGptProduction(1_500);
      return {
        ok: false,
        exhausted: true,
        deferred: true,
        accountId: key,
        error: message
      };
    }
    // The task may already have been removed from the in-memory queue after a
    // renderer restart.  Do not write it back to retry-wait in that case: the
    // durable recovery budget is exhausted, so the lane must be released and
    // the continuous scheduler may refill it with a fresh material task.
    scheduleContinuousGptProduction(1_500);
    writeGptWindowRuntime(key, {
      status: "probing",
      currentStage: "网页/桥接恢复已到时限，保留检查点",
      nextRetryAt: null,
      lastError: message,
      windowRecoveryStartedAt: recoveryState.startedAt,
      windowRecoveryDeadlineAt: recoveryState.deadlineAt,
      windowRecoveryAttempts: recoveryState.attempts,
      windowRecoveryTaskId: currentTaskId || null,
      windowRecoveryExhaustedAt: endedAt
    });
    logGptReadinessRecoveryEvent(key, "window-recovery-exhausted", {
      ...recoveryState,
      endedAt,
      status: "timeout"
    }, message, "window-reconnect");
    showWorkbenchAssistantBubble(`${gptAccounts.find((item) => item.id === key)?.name || key} 的网页/桥接恢复已到时限；已保留当前检查点，隔离本窗口，不影响其他账号。`, { duration: 0, tone: "warning" });
    return { ok: false, exhausted: true, accountId: key, error: message };
  };
  if (now >= recoveryState.deadlineAt || recoveryState.attempts > GPT_WINDOW_RECOVERY_MAX_ATTEMPTS) {
    return exhaust("网页/桥接在有限恢复预算内仍未就绪");
  }
  gptWindowRetryRecoveryStates.set(key, recoveryState);
  if (recoveryTask) persistGptWindowWorkerState(key, workerState);
  const workWindow = getGptContinuousWorkWindow(new Date(), gptWindowSettings(key));
  if (!workWindow.allowed) {
    const nextStartAt = workWindow.nextStartAt?.getTime() || null;
    writeGptWindowRuntime(key, { status: "waiting-schedule", nextProbeAt: nextStartAt, currentStage: "等待工作时段" });
    gptWindowRetryRecoveryStates.delete(key);
    scheduleGptWindowScheduleWake(key, nextStartAt);
    return;
  }
  const delay = Math.max(5_000, Math.min(20 * 60_000, Number(delayMs) || 15_000));
  writeGptWindowRuntime(key, {
    status: "retry-wait",
    currentStage: reason,
    nextRetryAt: now + delay,
    lastError: String(reason || "网页尚未就绪"),
      windowRecoveryStartedAt: recoveryState.startedAt,
      windowRecoveryDeadlineAt: recoveryState.deadlineAt,
      windowRecoveryAttempts: recoveryState.attempts,
      windowRecoveryTaskId: currentTaskId || null,
      windowRecoveryExhaustedAt: null
  });
  logGptReadinessRecoveryEvent(key, "window-recovery-scheduled", recoveryState, reason, "window-reconnect");
  showWorkbenchAssistantBubble(`${gptAccounts.find((item) => item.id === key)?.name || "当前账号窗口"}${reason}，${Math.ceil(delay / 1000)} 秒后自动重试，不需要手动点“重试”。`, { duration: 0, tone: "warning" });
  const timer = setTimeout(async () => {
    gptWindowRetryTimers.delete(key);
    const activeRecovery = gptWindowRetryRecoveryStates.get(key);
    if (activeRecovery?.inFlight === true && activeRecovery !== recoveryState) return;
    recoveryState.inFlight = true;
    gptWindowRetryRecoveryStates.set(key, recoveryState);
    // Recursive retries must release this marker before scheduling the next
    // bounded attempt; otherwise the concurrency guard would suppress it.
    const scheduleNextRecovery = (nextDelayMs, nextReason, nextOptions = {}) => {
      recoveryState.inFlight = false;
      return scheduleGptWindowRetry(key, nextDelayMs, nextReason, nextOptions);
    };
    if (!gptWindowAutoStartAllowed(key)) {
      gptWindowRetryRecoveryStates.delete(key);
      return;
    }
    const runtimeBeforeRefresh = readGptWindowRuntime(key);
    const workerStateBeforeRefresh = gptWindowWorkerState(key);
    const taskBeforeRefresh = workerStateBeforeRefresh?.queue?.[Math.max(0, Number(workerStateBeforeRefresh.queueIndex || 0))] || null;
    const currentTaskIdBeforeRefresh = String(
      (!isTerminalRecoveryTask(taskBeforeRefresh) && taskBeforeRefresh?.requestId)
        || (!isTerminalRecoveryTask(workerStateBeforeRefresh?.lastFailedTask)
          && workerStateBeforeRefresh?.lastFailedTask?.requestId)
        || ""
    ).trim();
    // A completion/queue-advance can happen while this timer is sleeping.
    // Never refresh or recreate the old conversation after that transition.
    // The next task owns its own recovery budget and will be scheduled by the
    // normal continuous worker loop.
    if (!currentTaskIdBeforeRefresh || currentTaskIdBeforeRefresh !== recoveryState.taskId) {
      gptWindowRetryRecoveryStates.delete(key);
      const runtimeOwnsReleasedRecovery = String(runtimeBeforeRefresh.currentTaskId || "").trim() === recoveryState.taskId
        || String(runtimeBeforeRefresh.windowRecoveryTaskId || "").trim() === recoveryState.taskId;
      // A timer can wake after the worker has already isolated/removed its
      // task. In that case the old code cancelled only the in-memory timer and
      // left the durable mirror at retry-wait with no currentTaskId, making the
      // lane look permanently busy while no recovery could run. Clear only an
      // unowned stale recovery mirror; never touch a newer task's state.
      if (!currentTaskIdBeforeRefresh && !runtimeBeforeRefresh.currentTaskId && !runtimeBeforeRefresh.windowRecoveryTaskId) {
        const hasPendingTask = window.GptWindowWorkerState?.hasPending?.(workerStateBeforeRefresh) === true;
        writeGptWindowRuntime(key, {
          status: hasPendingTask ? "probing" : "idle",
          currentTaskId: "",
          currentStage: hasPendingTask ? "旧恢复回调已取消，继续队列" : "等待素材",
          currentPercent: 0,
          nextRetryAt: null,
          lastError: "",
          windowRecoveryStartedAt: null,
          windowRecoveryDeadlineAt: null,
          windowRecoveryAttempts: 0,
          windowRecoveryTaskId: null,
          windowRecoveryExhaustedAt: null
        });
        scheduleContinuousGptProduction(1_500);
      } else if (runtimeOwnsReleasedRecovery) {
        writeGptWindowRuntime(key, {
          windowRecoveryStartedAt: null,
          windowRecoveryDeadlineAt: null,
          windowRecoveryAttempts: 0,
          windowRecoveryTaskId: null,
          windowRecoveryExhaustedAt: null
        });
      }
      logGptReadinessRecoveryEvent(
        key,
        "window-recovery-cancelled-task-advanced",
        { taskId: recoveryState.taskId, currentTaskId: currentTaskIdBeforeRefresh, endedAt: Date.now() },
        "当前作品已完成或队列已进入下一套，取消旧恢复回调",
        "window-reconnect"
      );
      return;
    }
    const taskStageBeforeRefresh = [
      taskBeforeRefresh?._stage,
      taskBeforeRefresh?.retryFromStage,
      taskBeforeRefresh?.workflow?.stage,
      taskBeforeRefresh?.workflow?.currentStage
    ].filter(Boolean).join(" ");
    if (window.GptWindowWorkerState?.shouldWaitForActiveGenerationRecovery?.({
      currentStage: runtimeBeforeRefresh.currentStage,
      taskStage: taskStageBeforeRefresh,
      status: runtimeBeforeRefresh.status,
      lastProgressAt: runtimeBeforeRefresh.lastProgressAt,
      now: Date.now()
    }) === true) {
      // The page is still producing the current batch. A bridge probe failure
      // is not evidence that the GPT response stopped; refreshing here would
      // abort the live response and create the exact refresh-without-progress
      // loop this recovery chain is meant to prevent.
      scheduleNextRecovery(30_000, "当前生图仍在进行，等待原对话完成", { preserveAttempt: true });
      return;
    }
    const liveInspectionBeforeRefresh = await boundedGptBrowserCall(
      window.gptWorkbench?.inspectStatus?.(key),
      GPT_INSPECT_CALL_TIMEOUT_MS
    ).catch(() => null);
    const liveStatusBeforeRefresh = await boundedGptBrowserCall(
      window.gptWorkbench?.status?.(key),
      GPT_INSPECT_CALL_TIMEOUT_MS
    ).catch(() => null);
    const livePageIsFreshRoot = /^https:\/\/(?:chatgpt\.com|www\.chatgpt\.com)\/?$/i.test(
      String(liveStatusBeforeRefresh?.url || "").trim()
    ) && liveStatusBeforeRefresh?.chatConversation !== true;
    if (livePageIsFreshRoot
      && isUnownedSubmittedFreshGptTask(recoveryTask, runtimeBeforeRefresh)) {
      const isolated = deferIndependentGptTaskAfterAutomaticRecovery(
        key,
        "新模式任务已提交但没有确认对应 GPT 对话；当前窗口在根页，已隔离以避免串线或重复生成",
        { quarantine: true, requestId: recoveryState.taskId }
      );
      if (isolated.action === "quarantine" || isolated.action === "defer") {
        gptWindowRetryRecoveryStates.delete(key);
        scheduleContinuousGptProduction(1_500);
        return;
      }
    }
    const readableWorkflowStage = new Set([
      "plan-ready",
      "waiting-images",
      "images-ready",
      "waiting-copy",
      "completed-copy-pending-package",
      "archived"
    ]).has(String(liveInspectionBeforeRefresh?.stage || ""));
    if (readableWorkflowStage
      && liveInspectionBeforeRefresh?.authenticationRequired !== true
      && liveInspectionBeforeRefresh?.composerReady !== false) {
      // The bridge is alive and the original conversation exposes a concrete
      // workflow boundary. Recreating this view only discards lazy image DOM
      // evidence and starts another repair loop. A concrete stage is a
      // successful recovery result, so close both the renderer and request
      // recovery budgets before handing control back to the normal worker.
      // Keeping the old timer alive used to abort an images-ready task before
      // it could execute request-copy, leaving a full batch in wait-images.
      gptWindowRetryRecoveryStates.delete(key);
      if (recoveryTask) {
        delete recoveryTask._windowRecoveryStartedAt;
        delete recoveryTask._windowRecoveryDeadlineAt;
        delete recoveryTask._windowRecoveryAttempts;
        delete recoveryTask._windowRecoveryExhaustedAt;
        persistGptWindowWorkerState(key, workerStateBeforeRefresh);
      }
      writeGptWindowRuntime(key, {
        status: "probing",
        currentStage: `原对话阶段可读取：${String(liveInspectionBeforeRefresh.stage)}`,
        nextRetryAt: null,
        lastError: "",
        windowRecoveryStartedAt: null,
        windowRecoveryDeadlineAt: null,
        windowRecoveryAttempts: recoveryState.attempts || 0,
        windowRecoveryTaskId: null,
        windowRecoveryExhaustedAt: null
      });
      logGptReadinessRecoveryEvent(
        key,
        "window-recovered-readable-stage",
        { ...recoveryState, endedAt: Date.now(), status: "completed" },
        `原对话阶段可读取：${String(liveInspectionBeforeRefresh.stage)}`,
        "window-reconnect"
      );
      runIndependentGptWindow(key, { force: true, automaticResume: true }).catch(() => {});
      return;
    }
    if (shouldAutoRefreshGptWindowForRecovery(reason)) {
      const refreshed = await withGptWindowRecoveryLock(key, reason, async (lock) => {
        const currentRuntime = readGptWindowRuntime(key);
        const currentWorkerState = gptWindowWorkerState(key);
        const currentTask = currentWorkerState?.queue?.[Math.max(0, Number(currentWorkerState.queueIndex || 0))] || null;
        const currentTaskStage = [
          currentTask?._stage,
          currentTask?.retryFromStage,
          currentTask?.workflow?.stage,
          currentTask?.workflow?.currentStage
        ].filter(Boolean).join(" ");
        const activeGenerationStage = /生图|生成图片|等待图片|生成中|response|image/i.test(
          `${String(currentRuntime.currentStage || "")} ${currentTaskStage}`
        );
        const safeToRecover = !activeGenerationStage;
        return refreshGptWindowForAutomaticRecovery(key, reason, {
          controlledRecovery: true,
          safeToRecover,
          requestId: currentRuntime.currentTaskId,
          knownConversationUrl: knownGptConversationUrl(key, currentRuntime),
          recoveryRequestId: lock.requestId
        });
      });
      if (refreshed?.skipped === "refresh-limit") {
        const recreated = await withGptWindowRecoveryLock(key, "refresh-limit-browser-recreate", (lock) => (
          recreateGptWindowForAutomaticRecovery(key, "refresh-limit-browser-recreate", {
            safeToRecover: true,
            requestId: readGptWindowRuntime(key).currentTaskId,
            recoveryRequestId: lock.requestId
          })
        ));
        if (recreated?.ok) {
          scheduleNextRecovery(5_000, "浏览器窗口已重建，重新读取原对话");
        } else if (Date.now() >= recoveryState.deadlineAt) {
          exhaust("同一对话刷新已达到 10 分钟内 2 次上限，浏览器重建仍未确认");
        } else {
          scheduleNextRecovery(20_000, "浏览器重建未确认，等待有限重试");
        }
        return;
      }
      if (!refreshed.ok) {
        if (Date.now() >= recoveryState.deadlineAt) exhaust("网页/桥接刷新失败，有限恢复预算已到期");
        else scheduleNextRecovery(20_000, "网页/桥接临时失败");
        return;
      }
      const readiness = await waitForGptProductionReadiness(key, 12_000).catch(() => null);
      if (readiness?.authenticationRequired) {
        writeGptWindowRuntime(key, { status: "login-required", currentStage: "等待登录", nextRetryAt: Date.now() + 60_000, lastError: "GPT 账号需要登录" });
        showWorkbenchAssistantBubble(`${gptAccounts.find((item) => item.id === key)?.name || "当前账号窗口"}需要登录 GPT；完成登录后系统会继续检查，不需要重新启动生产。`, { duration: 0, tone: "warning" });
        scheduleNextRecovery(60_000, "等待登录");
        return;
      }
      if (!readiness?.productionReady) {
        const readinessError = Array.isArray(readiness?.notReadyReasons) && readiness.notReadyReasons.length
          ? readiness.notReadyReasons.join("；")
          : readiness
            ? "GPT 页面、输入框或生产扩展尚未就绪"
            : "GPT 网页状态读取超时";
        writeGptWindowRuntime(key, {
          status: "retry-wait",
          currentStage: "等待网页/桥接就绪",
          nextRetryAt: Date.now() + 20_000,
          lastError: readinessError
        });
        if (Date.now() >= recoveryState.deadlineAt) exhaust(readinessError);
        else scheduleNextRecovery(20_000, "网页/桥接临时失败");
        return;
      }
    }
    reconcileGptWindow(key, { force: true }).then((result) => {
      const afterRuntime = readGptWindowRuntime(key);
      const afterState = gptWindowWorkerState(key);
      const workerStarted = gptWindowWorkerPromises.has(key) || afterState.autoRunning === true;
      const hasPending = window.GptWindowWorkerState?.hasPending?.(afterState) === true;
      const status = String(afterRuntime.status || "");
      const handedOffToAnotherBoundary = [
        "waiting-schedule",
        "waiting-startup-stagger",
        "waiting-prerequisite",
        "waiting-quota",
        "login-required",
        "stopped"
      ].includes(status);
      if (result?.ok === false || (!workerStarted && hasPending && !handedOffToAnotherBoundary
        && !["idle", "completed"].includes(status))) {
        const message = String(result?.error || afterRuntime.lastError || "自动恢复检查失败");
        if (Date.now() >= recoveryState.deadlineAt) exhaust(message);
        else scheduleNextRecovery(20_000, "网页/桥接临时失败");
        return;
      }
      const finished = {
        ...gptWindowRetryRecoveryStates.get(key),
        endedAt: Date.now(),
        status: handedOffToAnotherBoundary ? "handoff" : "completed"
      };
      gptWindowRetryRecoveryStates.delete(key);
      writeGptWindowRuntime(key, {
        ...(handedOffToAnotherBoundary ? {} : { nextRetryAt: null, lastError: "" }),
        windowRecoveryStartedAt: null,
        windowRecoveryDeadlineAt: null,
        windowRecoveryAttempts: finished.attempts || 0,
        windowRecoveryTaskId: null,
        windowRecoveryExhaustedAt: null
      });
      logGptReadinessRecoveryEvent(
        key,
        handedOffToAnotherBoundary ? "window-recovery-handoff" : "window-recovered",
        finished,
        handedOffToAnotherBoundary
          ? `恢复已交给${status}边界，不重复启动恢复循环`
          : "网页/桥接恢复完成",
        "window-reconnect"
      );
    }).catch((error) => {
      const message = String(error?.message || error || "自动恢复检查失败");
      if (Date.now() >= recoveryState.deadlineAt) exhaust(message);
      else {
        writeGptWindowRuntime(key, {
          status: "retry-wait",
          currentStage: "自动恢复检查失败，等待下一次探测",
          nextRetryAt: Date.now() + 20_000,
          lastError: message
        });
        scheduleNextRecovery(20_000, "网页/桥接临时失败");
      }
    });
  }, delay);
  gptWindowRetryTimers.set(key, timer);
}

// A stale quota snapshot must not prevent us from first reconciling a live
// conversation. This timer performs that read-only admission check without
// uploading or sending a new task; the normal quota reminder remains the
// source of truth for when a fresh production attempt may start.
function scheduleGptQuotaConversationReconciliation(accountId = activeGptAccountId, delayMs = 15_000) {
  const key = String(accountId || activeGptAccountId);
  if (gptWindowQuotaReconcileTimers.has(key) || !gptWindowAutoStartAllowed(key)) return;
  const delay = Math.max(5_000, Math.min(60_000, Number(delayMs) || 15_000));
  const timer = setTimeout(async () => {
    gptWindowQuotaReconcileTimers.delete(key);
    if (!gptWindowAutoStartAllowed(key)) return;
    const result = await runIndependentGptWindow(key, { force: false, reconcileOnly: true }).catch((error) => ({
      ok: false,
      errorCode: String(error?.code || "GPT_INSPECTION_UNAVAILABLE"),
      error: error?.message || String(error)
    }));
    if (!gptWindowAutoStartAllowed(key)) return;
    const state = gptWindowWorkerState(key);
    const blocked = String(state.lastFailedTask?._errorCode || "") === "archive-recovery-failed"
      || String(state.lastFailedTask?._errorCode || "") === "conversation-owner-mismatch";
    if (blocked) return;
    const account = gptAccounts.find((item) => item.id === key);
    const quotaState = readGptCycleState(account?.quotaGroup || key);
    if (Number(quotaState.nextProbeAt || 0) > Date.now()) {
      scheduleGptQuotaConversationReconciliation(key, Math.min(15_000, Number(quotaState.nextProbeAt) - Date.now()));
    } else if (result?.ok !== false) {
      scheduleContinuousGptProduction(0);
    }
  }, delay);
  gptWindowQuotaReconcileTimers.set(key, timer);
}

function loadGptWindowRuntime() {
  try {
    const parsed = JSON.parse(localStorage.getItem(GPT_WINDOW_RUNTIME_STORAGE_KEY) || "{}");
    return parsed && typeof parsed === "object" ? parsed : {};
  } catch { return {}; }
}

function defaultGptWindowRuntime(accountId) {
  return {
    accountId: String(accountId || "account-1"),
    status: "idle",
    pausedByUser: false,
    stoppedByUser: false,
    currentTaskId: "",
    currentStage: "",
    currentPercent: 0,
    uploadedAttachments: 0,
    expectedAttachments: 0,
    expectedImages: 0,
    generatedImages: 0,
    // Per-account serial production cursor.  This is deliberately stored per
    // browser window so the cat never shows browser 1's "第几套" on browser 2.
    completedSets: 0,
    lastCompletedRequestId: "",
    currentSetNumber: 0,
    currentSetStartedAt: null,
    workflowStartedAt: "",
    workflowDeadlineAt: "",
    workflowElapsedMs: 0,
    workflowRemainingMs: 0,
    workflowTotalElapsedMs: 0,
    conversationUrl: "",
    recoveryCount: 0,
    lastRecoveryAt: "",
    recoveryAction: "",
    stageStartedAt: "",
    lastProgressAt: "",
    // A runtime mirror must expose the same finite-wait evidence as the
    // detailed conversation log. Keep these aliases durable so patrol/report
    // code does not have to reconstruct a deadline from a stale UI label.
    elapsedMs: 0,
    deadlineAt: "",
    nextActionAt: null,
    attempt: 0,
    reason: "",
    waitLimitMs: 0,
    stageElapsedMs: 0,
    stepAttempt: 0,
    stepStatus: "",
    stepRemainingMs: 0,
    nextProbeAt: null,
    updatedAt: Date.now()
  };
}

function normalizeGptWindowRuntimeEntry(accountId, runtime = {}) {
  const key = String(accountId || runtime.accountId || "account-1");
  const merged = { ...defaultGptWindowRuntime(key), ...(runtime || {}), accountId: key };
  const stage = String(merged.currentStage || "");
  const hasCurrentTask = Boolean(String(merged.currentTaskId || "").trim());
  const isWaitingWithoutTask = !hasCurrentTask && (
    (merged.status === "idle" && /等待素材|等待启动|手动模式|账号已停用/.test(stage))
    || (merged.status === "probing" && /等待 GPT 网页就绪|当前作品已隔离，继续队列/.test(stage))
  );
  if (isWaitingWithoutTask) {
    // A previous task can leave counts behind when the queue is emptied by
    // reconciliation or a safe page recovery. They are current-work fields,
    // not durable completion totals, so never show them without an owner task.
    Object.assign(merged, {
      currentPercent: 0,
      uploadedAttachments: 0,
      expectedAttachments: 0,
      expectedImages: 0,
      generatedImages: 0,
      nextRetryAt: null
    });
  }
  return merged;
}

function readGptWindowRuntime(accountId = activeGptAccountId) {
  const key = String(accountId || "account-1");
  return normalizeGptWindowRuntimeEntry(key, gptWindowRuntime[key] || {});
}

function writeGptWindowRuntime(accountId, patch = {}) {
  const key = String(accountId || activeGptAccountId || "account-1");
  const nextPatch = { ...patch };
  const previousRuntime = readGptWindowRuntime(key);
  // A late completion from an older worker must not clear a newer request's
  // runtime mirror. Without an explicit completion identity, the UI could
  // show "作品已闭环" while the same account was already uploading the next
  // material. Callers that close a task provide `completedTaskId`; if it no
  // longer owns the window, keep the newer task untouched.
  const completedTaskId = String(nextPatch.completedTaskId || "").trim();
  const clearingCurrentTask = Object.prototype.hasOwnProperty.call(nextPatch, "currentTaskId")
    && !String(nextPatch.currentTaskId || "").trim();
  if (completedTaskId
    && clearingCurrentTask
    && String(previousRuntime.currentTaskId || "").trim()
    && String(previousRuntime.currentTaskId || "").trim() !== completedTaskId
    && ["idle", "completed"].includes(String(nextPatch.status || ""))) {
    return previousRuntime;
  }
  delete nextPatch.completedTaskId;
  const stageOrStatusChanged = ["status", "currentStage"].some((field) => (
    Object.prototype.hasOwnProperty.call(nextPatch, field)
    && String(nextPatch[field] || "") !== String(previousRuntime[field] || "")
  ));
  const progressFields = [
    "currentTaskId",
    "currentPercent",
    "uploadedAttachments",
    "expectedAttachments",
    "expectedImages",
    "generatedImages",
    "completedSets",
    "workflowDeadlineAt",
    "deadlineAt",
    "nextRetryAt",
    "nextProbeAt"
  ];
  const normalizedProgressValue = (value) => value == null ? "" : String(value);
  // A status poll is not progress by itself. The old presence-only check
  // treated the same current stage/count/deadline payload as new progress on
  // every poll, which kept lastProgressAt moving forever and hid real stalls.
  const progressTouched = progressFields.some((field) => (
    Object.prototype.hasOwnProperty.call(nextPatch, field)
      && normalizedProgressValue(nextPatch[field]) !== normalizedProgressValue(previousRuntime[field])
  ));
  const nowIso = new Date().toISOString();
  if (Object.prototype.hasOwnProperty.call(nextPatch, "recoveryAction")
    && String(nextPatch.recoveryAction || "")
    && String(nextPatch.recoveryAction || "") !== String(previousRuntime.recoveryAction || "")) {
    nextPatch.recoveryCount = Math.max(0, Number(previousRuntime.recoveryCount || 0)) + 1;
    nextPatch.lastRecoveryAt = nowIso;
  }
  if (nextPatch.currentTaskId && !nextPatch.conversationUrl) {
    nextPatch.conversationUrl = knownGptConversationUrl(key, previousRuntime);
  }
  const workflowStartMs = Date.parse(String(nextPatch.workflowStartedAt || previousRuntime.workflowStartedAt || ""));
  if (Number.isFinite(workflowStartMs) && workflowStartMs > 0) {
    nextPatch.workflowTotalElapsedMs = Math.max(0, Date.now() - workflowStartMs);
  }
  if (stageOrStatusChanged) nextPatch.stageStartedAt = nowIso;
  if ((stageOrStatusChanged || progressTouched) && !String(nextPatch.lastProgressAt || "").trim()) {
    nextPatch.lastProgressAt = nowIso;
  }
  if ((stageOrStatusChanged || progressTouched)
    && !String(nextPatch.stageStartedAt || previousRuntime.stageStartedAt || "").trim()) {
    // Older checkpoints predate stageStartedAt. Reuse their most recent
    // progress timestamp as an explicit compatibility estimate instead of
    // leaving a wait stage without an auditable start time.
    nextPatch.stageStartedAt = String(previousRuntime.lastProgressAt || nextPatch.lastProgressAt || nowIso);
  }
  // Every recoverable wait exposes a concrete wake/deadline in the durable
  // runtime mirror. Detailed history remains in the checkpoint and log.
  const waitStatuses = ["retry-wait", "waiting-startup-stagger", "waiting-quota", "waiting-schedule", "login-required"];
  const waitStatus = String(nextPatch.status || "");
  // A later status mirror may only update the label/stage.  Do not erase the
  // already scheduled quota wake-up in that case; losing it makes a finite
  // quota wait look like an unbounded pause and prevents the UI from showing
  // when the automatic probe will run.
  if (waitStatus === "waiting-quota"
    && !Object.prototype.hasOwnProperty.call(nextPatch, "nextProbeAt")
    && Number(previousRuntime.nextProbeAt || 0) > 0) {
    nextPatch.nextProbeAt = Number(previousRuntime.nextProbeAt);
  }
  const waitUntil = Number(nextPatch.nextRetryAt || nextPatch.nextProbeAt || previousRuntime.nextProbeAt || 0);
  if (waitStatuses.includes(waitStatus) && Number.isFinite(waitUntil) && waitUntil > 0) {
    if (!String(nextPatch.stageStartedAt || previousRuntime.stageStartedAt || "").trim()) {
      nextPatch.stageStartedAt = nowIso;
    }
    nextPatch.deadlineAt = new Date(waitUntil).toISOString();
    nextPatch.nextActionAt = nextPatch.deadlineAt;
    nextPatch.waitLimitMs = Math.max(0, waitUntil - Date.now());
    nextPatch.stepRemainingMs = nextPatch.waitLimitMs;
    nextPatch.stepStatus = "waiting";
    nextPatch.reason = String(nextPatch.lastError || nextPatch.currentStage || "等待下一次自动处理");
    nextPatch.attempt = Math.max(0, Number(nextPatch.attempt ?? nextPatch.stepAttempt ?? previousRuntime.attempt ?? previousRuntime.stepAttempt ?? 0));
    nextPatch.stepAttempt = nextPatch.attempt;
    const stageStartMs = Date.parse(String(nextPatch.stageStartedAt || previousRuntime.stageStartedAt || ""));
    if (Number.isFinite(stageStartMs) && stageStartMs > 0) {
      nextPatch.stageElapsedMs = Math.max(0, Date.now() - stageStartMs);
      nextPatch.elapsedMs = nextPatch.stageElapsedMs;
    }
  }
  const activeWorkflowProgress = ["running", "probing"].includes(String(nextPatch.status || ""))
    && (Object.prototype.hasOwnProperty.call(nextPatch, "currentTaskId")
      && String(nextPatch.currentTaskId || "").trim()
      || /上传|确认|图片|文案|生产|下载|打包|归档/i.test(String(nextPatch.currentStage || "")))
    && nextPatch.lastError === ""
    && !Object.prototype.hasOwnProperty.call(nextPatch, "lastDeferredError");
  if (activeWorkflowProgress) nextPatch.lastDeferredError = "";
  gptWindowRuntime[key] = normalizeGptWindowRuntimeEntry(key, {
    ...previousRuntime,
    ...nextPatch,
    accountId: key,
    updatedAt: Date.now()
  });
  try { localStorage.setItem(GPT_WINDOW_RUNTIME_STORAGE_KEY, JSON.stringify(gptWindowRuntime)); } catch { /* private mode */ }
  scheduleGptControlSync();
  return gptWindowRuntime[key];
}

function markGptWindowSetStarted(accountId = activeGptAccountId) {
  const current = readGptWindowRuntime(accountId);
  const account = gptAccounts.find((item) => item.id === String(accountId));
  const cycle = readGptCycleState(account?.quotaGroup || accountId);
  const cycleStart = Math.min(
    ...[cycle.uploadCycleStartAt, cycle.generationCycleStartAt].map((value) => Number(value || 0)).filter(Boolean)
  ) || 0;
  const cycleChanged = cycleStart > 0 && Number(current.setCycleStartedAt || 0) < cycleStart;
  const completedSets = cycleChanged ? 0 : Number(current.completedSets || 0);
  const nextNumber = Math.max(1, completedSets + 1);
  return writeGptWindowRuntime(accountId, {
    completedSets,
    currentSetNumber: nextNumber,
    setCycleStartedAt: cycleStart || current.setCycleStartedAt || Date.now(),
    currentSetStartedAt: current.currentSetStartedAt || Date.now(),
    generatedImages: 0
  });
}

function markGptWindowSetCompleted(accountId = activeGptAccountId, requestId = "") {
  const current = readGptWindowRuntime(accountId);
  const completionKey = String(requestId || "").trim();
  if (completionKey && String(current.lastCompletedRequestId || "") === completionKey) return current;
  const differentActiveTask = Boolean(
    completionKey
      && String(current.currentTaskId || "").trim()
      && String(current.currentTaskId || "").trim() !== completionKey
  );
  return writeGptWindowRuntime(accountId, {
    completedSets: Math.max(0, Number(current.completedSets || 0)) + 1,
    currentSetNumber: Math.max(1, Number(current.currentSetNumber || Number(current.completedSets || 0) + 1)),
    ...(differentActiveTask ? {} : {
      currentSetStartedAt: null,
      workflowStartedAt: "",
      workflowDeadlineAt: "",
      workflowElapsedMs: 0,
      workflowRemainingMs: 0
    }),
    ...(completionKey ? { completedTaskId: completionKey } : {}),
    ...(completionKey ? { lastCompletedRequestId: completionKey } : {})
  });
}

function gptWindowIsUserStopped(accountId = activeGptAccountId) {
  const state = readGptWindowRuntime(accountId);
  return Boolean(state.stoppedByUser);
}

function gptWindowIsUserPaused(accountId = activeGptAccountId) {
  const state = readGptWindowRuntime(accountId);
  return Boolean(state.pausedByUser);
}

function gptWindowAutoStartAllowed(accountId = activeGptAccountId) {
  const key = String(accountId || activeGptAccountId || "account-1");
  const state = gptWindowWorkerState(key);
  const settings = gptWindowSettings(key);
  const runtime = readGptWindowRuntime(key);
  if (!independentGptWindowMode(settings.mode)) return false;
  return window.GptWindowWorkerState?.shouldAutoArm
    ? window.GptWindowWorkerState.shouldAutoArm(state, runtime, settings)
    : settings.continuousAutoStart !== false
      && !state.pausedByUser
      && !state.stoppedByUser
      && !runtime.pausedByUser
      && !runtime.stoppedByUser;
}

function normalizeNonAutomaticGptWindowRuntime(accountId = activeGptAccountId) {
  const key = String(accountId || activeGptAccountId || "account-1");
  const account = gptAccounts.find((item) => item.id === key);
  const settings = gptWindowSettings(key);
  const state = gptWindowWorkerState(key);
  const runtime = readGptWindowRuntime(key);
  const explicitUserHold = Boolean(
    state.pausedByUser
    || state.stoppedByUser
    || runtime.pausedByUser
    || runtime.stoppedByUser
  );
  if ((!explicitUserHold && account && !account.disabled && independentGptWindowMode(settings.mode))
    || gptWindowWorkerPromises.has(key)
    || state.autoRunning) return false;
  clearTimeout(gptWindowWorkerTimers.get(key));
  gptWindowWorkerTimers.delete(key);
  clearTimeout(gptWindowRetryTimers.get(key));
  gptWindowRetryTimers.delete(key);
  clearTimeout(gptWindowQuotaReconcileTimers.get(key));
  gptWindowQuotaReconcileTimers.delete(key);
  if (!explicitUserHold && ![
    "running",
    "retry-wait",
    "login-required"
  ].includes(String(runtime.status || ""))) return false;
  writeGptWindowRuntime(key, {
    status: "idle",
    currentStage: account?.disabled
      ? "账号已停用，不参与自动生产"
      : (explicitUserHold && (state.stoppedByUser || runtime.stoppedByUser)
        ? "已停止，不参与自动生产"
        : "手动模式，不参与自动生产"),
    nextRetryAt: null,
    lastError: explicitUserHold ? "" : runtime.lastError
  });
  return true;
}

// The production selector exposes four user-facing workflows, including a
// serial account-rotation workflow. Older builds stored several aliases;
// normalize them at the boundary so an upgrade cannot silently start a
// different queue.
