function isReadOnlyGptPreview() {
  const assigned = contentInstanceAccountIds();
  // Any browser-rendered content instance is a read-only mirror. Only the
  // Electron process that owns this instance's partitions may run GPT work;
  // this keeps opening A/B/C/D in a normal browser from creating a second
  // worker against the same account or checkpoint file.
  return !isGptRuntimeWriteAuthority() && Boolean(assigned?.size);
}

function gptPreviewOnlyActionResult(actionId = "") {
  if (!isReadOnlyGptPreview()) return null;
  return {
    ok: false,
    actionId: String(actionId || ""),
    reason: "preview-only",
    errorCode: "GPT_PREVIEW_ONLY",
    error: "当前实例网页预览只读，GPT 桥接未连接；当前动作未执行"
  };
}

function notifyGptPreviewBlocked(actionId = "", suppliedResult = null) {
  const result = suppliedResult || gptPreviewOnlyActionResult(actionId);
  if (!result) return null;
  showWorkbenchAssistantBubble(result.error, {
    sourceView: "gptProductionTestView",
    notificationKey: `gpt-preview-only:${actionId || "action"}`,
    tone: "warning",
    duration: 4200
  });
  return result;
}

function rejectGptPreviewWrite(actionId = "") {
  const result = gptPreviewOnlyActionResult(actionId);
  if (!result) return null;
  notifyGptPreviewBlocked(actionId, result);
  return result;
}

function blockGptPreviewEvent(event, actionId = "") {
  const result = rejectGptPreviewWrite(actionId);
  if (!result) return false;
  event?.preventDefault?.();
  event?.stopPropagation?.();
  return true;
}

function applyReadOnlyGptPreviewControls() {
  if (!isReadOnlyGptPreview()) return;

  const productionView = $("#gptProductionTestView");
  if (productionView) {
    productionView.dataset.gptPreviewOnly = "true";
    productionView.setAttribute("aria-description", `${contentInstanceDisplayLabel()}网页预览只读；仅展示当前实例状态，不执行 GPT 生产动作`);
  }

  // A browser page can be hydrated with stale local state before the
  // read-only runtime mirror arrives. Keep every action that could touch GPT,
  // the queue, or the account registry unavailable during that window too.
  document.querySelectorAll(GPT_PREVIEW_HIDDEN_SELECTORS.join(",")).forEach((element) => {
    element.hidden = true;
    if ("disabled" in element) element.disabled = true;
    element.setAttribute("aria-disabled", "true");
    element.dataset.gptPreviewBlocked = "true";
  });

  document.querySelectorAll(GPT_PREVIEW_DISABLED_SELECTORS.join(",")).forEach((element) => {
    if ("disabled" in element) element.disabled = true;
    element.setAttribute("aria-disabled", "true");
    element.dataset.gptPreviewBlocked = "true";
  });

  const hint = $("#gptTestSendHint");
  if (hint) hint.textContent = `${contentInstanceDisplayLabel()}网页预览只读：仅显示当前实例的素材、模板和生产检查点`;
  const materialCount = $("#gptTestMaterialCount");
  if (materialCount) materialCount.textContent = "只读预览";
  const templateCount = $("#gptTestTemplateName");
  if (templateCount) templateCount.textContent = "只读预览";
  const variantHint = $("#gptWorkflowVariantHint");
  if (variantHint) {
    const variant = $("#gptWorkflowVariant")?.value === "fresh-session-fixed-template"
      ? "新模式｜每套新对话 + 固定模板"
      : "旧模式｜复用原对话";
    variantHint.textContent = `${contentInstanceDisplayLabel()}网页预览只读：${variant}`;
    variantHint.hidden = false;
  }

  // Renderers replace the material/template/account panels with fresh DOM.
  // Observe only child-list changes so applying hidden/disabled attributes
  // cannot trigger this observer recursively.
  if (!applyReadOnlyGptPreviewControls.observer && typeof MutationObserver === "function" && document.body) {
    applyReadOnlyGptPreviewControls.observer = new MutationObserver(() => {
      if (applyReadOnlyGptPreviewControls.pending) return;
      applyReadOnlyGptPreviewControls.pending = true;
      window.setTimeout(() => {
        applyReadOnlyGptPreviewControls.pending = false;
        applyReadOnlyGptPreviewControls();
      }, 0);
    });
    applyReadOnlyGptPreviewControls.observer.observe(document.body, { childList: true, subtree: true });
  }
}

function gptPreviewActionForElement(element) {
  if (!element) return "gpt.preview-only";
  if (element.matches("#gptTestSendBtn, #gptManualNextBtn, #gptSemiAutoResumeBtn")) return "gpt.continue";
  if (element.matches("#gptPauseQueueBtn, #gptStopQueueBtn")) return "gpt.toggle-pause";
  if (element.matches("#gptRetryTaskBtn")) return "gpt.retry";
  if (element.matches("#gptReopenWindowBtn")) return "gpt.reopen-window";
  if (element.matches("#gptResetTaskBtn")) return "gpt.reset-current";
  if (element.matches("#gptSkipTaskBtn")) return "gpt.skip";
  if (element.matches("#gptBrowserBackBtn")) return "gpt.browser.back";
  if (element.matches("#gptBrowserForwardBtn")) return "gpt.browser.forward";
  if (element.matches("#gptBrowserReloadBtn")) return "gpt.browser.refresh";
  if (element.matches("#gptBrowserHomeBtn")) return "gpt.browser.home";
  if (element.matches("#gptBrowserAddressInput, #gptBrowserGoBtn")) return "gpt.browser.url";
  if (element.matches("[data-gpt-upload-post], [data-gpt-test-material-check], [data-gpt-test-category-check]")) return "gpt.material.upload";
  if (element.matches("[data-gpt-upload-template], [data-gpt-test-template-check]")) return "gpt.template.upload";
  if (element.matches("#gptSaveOnlineTemplateBtn, #gptOnlineTemplateForm, #gptOnlineTemplateName, #gptOnlineTemplateUrl, #gptOnlineTemplateAccount")) return "gpt.template.save";
  if (element.matches("#gptProductionMode, #gptWorkflowVariant, #gptModeQuickTabs, #gptModeWorkflowEditor, #gptAddModeWorkflowStepBtn, #gptModeInfoBtn, #gptAddModeBtn, #gptDeleteModeBtn")) return "gpt.mode.change";
  if (element.matches("[data-browser-toggle-disable], [data-browser-toggle], [data-browser-recovery], [data-browser-remove], [data-browser-delete-login], #gptAddAccountBtn, #gptBrowserManager")) return "gpt.account.manage";
  if (element.matches("#gptMoreRecovery, #gptRestoreMasterPromptBtn, #gptSaveMasterPromptBtn, #gptCopyMasterPromptBtn")) return "gpt.recover-current";
  return "gpt.preview-only";
}

function installReadOnlyGptPreviewGuards() {
  if (installReadOnlyGptPreviewGuards.installed) return;
  installReadOnlyGptPreviewGuards.installed = true;
  const selector = GPT_PREVIEW_EVENT_SELECTORS.join(",");
  const guard = (event) => {
    if (!isReadOnlyGptPreview()) return;
    const target = event.target?.closest?.(selector);
    // The account manager lives in settings rather than inside the production
    // view.  The selector already limits this to GPT controls, so keep the
    // guard global across the preview page and cover both surfaces.
    if (!target) return;
    // Keyboard navigation should remain harmless, but Enter/Space on a
    // disabled/hidden production control must not reach its delegated handler.
    if (event.type === "keydown" && !["Enter", " ", "Spacebar"].includes(event.key)) return;
    blockGptPreviewEvent(event, gptPreviewActionForElement(target));
  };
  ["click", "change", "input", "submit", "keydown"].forEach((eventName) => {
    document.addEventListener(eventName, guard, true);
  });
}

function scheduleGptRuntimeSync(snapshot, delayMs = 250) {
  if (!isGptRuntimeWriteAuthority()) return;
  if (snapshot) pendingGptRuntimeSnapshot = snapshot;
  clearTimeout(gptRuntimeSyncTimer);
  gptRuntimeSyncTimer = setTimeout(async () => {
    gptRuntimeSyncTimer = null;
    const current = pendingGptRuntimeSnapshot;
    pendingGptRuntimeSnapshot = null;
    if (!current) return;
    gptRuntimeSyncInFlight = gptRuntimeSyncInFlight
      .catch(() => {})
      .then(async () => {
    try {
      const result = await api("/api/gpt-production/runtime-state", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(current)
      });
      if (result?.state) {
        localStorage.setItem(GPT_QUEUE_META_STORAGE_KEY, JSON.stringify({
          updatedAt: result.state.updatedAt,
          revision: result.state.revision,
          hasQueue: Boolean(result.state.queue)
        }));
      }
    } catch {
      // Compatibility with an older still-running server: localStorage stays
      // complete and the next successful startup will reconcile it.
    }
      })
      .finally(() => {
        if (pendingGptRuntimeSnapshot) scheduleGptRuntimeSync(undefined, 0);
      });
  }, Math.max(0, Number(delayMs) || 0));
}

function localGptControlSnapshot() {
  return {
    armed: localStorage.getItem(GPT_CONTINUOUS_RUN_STORAGE_KEY) === "true",
    settings: { ...(gptAutoSettings || {}) },
    modeProfiles: { ...(gptModeProfiles || {}) },
    multiRun: gptMultiRunState && typeof gptMultiRunState === "object" ? { ...gptMultiRunState } : null,
    windowRuntime: filterContentInstanceRuntime(Object.fromEntries(Object.entries(gptWindowRuntime || {})
      .map(([accountId, runtime]) => [accountId, normalizeGptWindowRuntimeEntry(accountId, runtime)])))
  };
}

function scheduleGptControlSync(delayMs = 250) {
  // Some profile migrations run during module initialization. Defer the read
  // so all control variables are initialized before creating the snapshot.
  setTimeout(() => scheduleGptRuntimeSync(localGptRuntimeSnapshot(), delayMs), 0);
}

function applyGptRuntimeControl(control) {
  if (!control || typeof control !== "object") return;
  if (control.settings && typeof control.settings === "object") {
    localStorage.setItem(GPT_AUTO_SETTINGS_STORAGE_KEY, JSON.stringify(control.settings));
  }
  if (control.modeProfiles && typeof control.modeProfiles === "object") {
    localStorage.setItem(GPT_MODE_PROFILES_STORAGE_KEY, JSON.stringify(control.modeProfiles));
  }
  if (control.multiRun && typeof control.multiRun === "object") {
    localStorage.setItem(GPT_MULTI_RUN_STORAGE_KEY, JSON.stringify(control.multiRun));
  } else {
    localStorage.removeItem(GPT_MULTI_RUN_STORAGE_KEY);
  }
  if (control.windowRuntime && typeof control.windowRuntime === "object") {
    const normalizedRuntime = filterContentInstanceRuntime(Object.fromEntries(Object.entries(control.windowRuntime)
      .map(([accountId, runtime]) => [accountId, normalizeGptWindowRuntimeEntry(accountId, runtime)])));
    localStorage.setItem(GPT_WINDOW_RUNTIME_STORAGE_KEY, JSON.stringify(normalizedRuntime));
  }
  if (control.armed === true) localStorage.setItem(GPT_CONTINUOUS_RUN_STORAGE_KEY, "true");
  else localStorage.removeItem(GPT_CONTINUOUS_RUN_STORAGE_KEY);

  gptModeProfiles = loadGptModeProfiles();
  gptAutoSettings = loadGptAutoSettings();
  gptMultiRunState = control.multiRun && typeof control.multiRun === "object" ? control.multiRun : null;
  gptWindowRuntime = control.windowRuntime && typeof control.windowRuntime === "object"
    ? filterContentInstanceRuntime(Object.fromEntries(Object.entries(control.windowRuntime)
      .map(([accountId, runtime]) => [accountId, normalizeGptWindowRuntimeEntry(accountId, runtime)])))
    : {};
  const nativeMode = gptAccounts.find((account) => account.id === activeGptAccountId)?.productionMode;
  if (nativeMode) gptAutoSettings.mode = normalizeGptProductionMode(nativeMode);
}

function readOnlyGptWindowWorkerState(accountId = activeGptAccountId, worker = gptWindowWorkerState(accountId)) {
  const assigned = contentInstanceAccountIds();
  if (isGptRuntimeWriteAuthority()
    || !assigned?.size
    || !gptReadOnlyRuntimeState?.control?.windowRuntime) {
    return isReadOnlyGptPreview()
      ? { ...worker, autoRunning: false, autoPaused: false, queuePaused: false, armed: false, pausedByUser: false, stoppedByUser: false }
      : worker;
  }
  const key = String(accountId || activeGptAccountId || "account-1");
  const remote = gptReadOnlyRuntimeState.control.windowRuntime[key];
  const remoteQueue = gptReadOnlyRuntimeState.queue;
  const queueBelongsToAccount = String(remoteQueue?.activeAccountId || "") === key;
  if (!remote || typeof remote !== "object") {
    return {
      ...worker,
      queue: [],
      queueIndex: 0,
      lastFailedTask: null,
      lastFailedStage: "",
      lastFailedPercent: 0
    };
  }
  const runtime = normalizeGptWindowRuntimeEntry(key, remote);
  const status = String(runtime.status || "");
  return {
    ...worker,
    queue: queueBelongsToAccount && Array.isArray(remoteQueue.tasks) ? remoteQueue.tasks : [],
    queueIndex: queueBelongsToAccount ? Math.max(0, Number(remoteQueue.index || 0)) : 0,
    lastFailedTask: null,
    lastFailedStage: "",
    lastFailedPercent: 0,
    // The preview must not inherit a stale local worker promise/flag. Only a
    // server-confirmed running status may display the account as producing.
    autoRunning: status === "running",
    autoPaused: status === "paused" || Boolean(runtime.pausedByUser),
    queuePaused: status === "paused" || status === "stopped" || status === "retry-wait",
    armed: gptReadOnlyRuntimeState.control.armed === true,
    pausedByUser: Boolean(runtime.pausedByUser),
    stoppedByUser: Boolean(runtime.stoppedByUser),
    currentTaskId: runtime.currentTaskId || worker.currentTaskId
  };
}

function persistGptQueue() {
  const savedAt = new Date().toISOString();
  const activeQueueHasPending = gptTestQueue
    .slice(Math.max(0, Number(gptTestQueueIndex || 0)))
    .some((task) => task && !["completed", "skipped"].includes(String(task._status || "")));
  // The visible tab may be an idle account while another independent window
  // still owns pending work. Keep a compatibility mirror from that pending
  // window instead of deleting the global queue and making the dashboard say
  // there is nothing left to produce.
  const liveMirrorAccount = gptAccounts.find((account) => {
    const key = String(account?.id || "");
    const state = gptWindowWorkerStates.get(key);
    const runtime = readGptWindowRuntime(key);
    const recoverableRuntime = ["running", "probing", "retry-wait", "waiting-quota", "waiting-schedule"]
      .includes(String(runtime?.status || ""));
    return state
      && window.GptWindowWorkerState?.hasPending?.(state)
      && (gptWindowWorkerPromises.has(key) || recoverableRuntime);
  }) || null;
  const mirrorAccount = liveMirrorAccount
    || (activeQueueHasPending
      ? gptAccounts.find((account) => account?.id === activeGptAccountId) || null
      : gptAccounts.find((account) => {
          const state = gptWindowWorkerStates.get(String(account?.id || ""));
          return state && window.GptWindowWorkerState?.hasPending?.(state);
        }) || null);
  const mirrorState = mirrorAccount ? gptWindowWorkerStates.get(String(mirrorAccount.id)) : null;
  const mirrorUsesIndependentQueue = Boolean(liveMirrorAccount) || !activeQueueHasPending;
  const mirrorTasks = !mirrorUsesIndependentQueue
    ? serializedGptQueueTasks(gptTestQueue)
    : serializedGptQueueTasks(mirrorState?.queue || []);
  const mirrorIndex = !mirrorUsesIndependentQueue
    ? Math.max(0, Number(gptTestQueueIndex || 0))
    : Math.max(0, Number(mirrorState?.queueIndex || 0));
  const hasQueue = Boolean(mirrorTasks.length && mirrorIndex < mirrorTasks.length);
  // The top-level queue is a legacy compatibility mirror. Continuous mode now
  // owns one queue per browser window, so the old global flags must not report
  // "paused" while any independent window is genuinely producing. Keep the
  // mirror useful for older diagnostics without letting it override the
  // per-window worker state.
  const runningWindowIds = [];
  const recoveringWindowIds = [];
  for (const account of Array.isArray(gptAccounts) ? gptAccounts : []) {
    const key = String(account?.id || "");
    if (!key) continue;
    const state = gptWindowWorkerStates.get(key);
    if (gptWindowWorkerPromises.has(key) || state?.autoRunning) runningWindowIds.push(key);
    const runtime = readGptWindowRuntime(key);
    const recoverableRuntime = ["probing", "retry-wait", "waiting-quota", "waiting-schedule"].includes(String(runtime?.status || ""));
    if (!gptWindowWorkerPromises.has(key)
      && state
      && recoverableRuntime
      && window.GptWindowWorkerState?.hasPending?.(state)
      && gptWindowAutoStartAllowed(key)) {
      recoveringWindowIds.push(key);
    }
  }
  const hasIndependentWorker = runningWindowIds.length > 0;
  const activeWorkerState = gptWindowWorkerStates.get(String(activeGptAccountId || ""));
  const activeWorkerMode = gptAccounts.find((account) => account?.id === activeGptAccountId)?.mode
    || gptAutoSettings?.mode;
  const activeWorkerIsIndependent = independentGptWindowMode(activeWorkerMode);
  const mirrorPaused = hasIndependentWorker || recoveringWindowIds.length > 0
    ? false
    : activeWorkerIsIndependent && activeWorkerState
      ? Boolean(activeWorkerState.queuePaused || activeWorkerState.autoPaused)
      : Boolean(gptQueuePaused || gptAutoPaused);
  const mirrorRunning = hasIndependentWorker
    || recoveringWindowIds.length > 0
    || Boolean(gptAutoRunning);
  const queue = hasQueue ? {
    version: 2,
    savedAt,
    index: mirrorIndex,
    paused: mirrorPaused,
    running: mirrorRunning,
    mode: activeGptModeKey(mirrorAccount?.mode || gptAutoSettings?.mode),
    activeAccountId: String(mirrorAccount?.id || activeGptAccountId || ""),
    tasks: mirrorTasks
  } : null;
  if (queue) localStorage.setItem(GPT_QUEUE_STORAGE_KEY, JSON.stringify(queue));
  else localStorage.removeItem(GPT_QUEUE_STORAGE_KEY);
  localStorage.setItem(GPT_QUEUE_META_STORAGE_KEY, JSON.stringify({ savedAt, updatedAt: savedAt, hasQueue }));
  scheduleGptRuntimeSync({ version: 3, updatedAt: savedAt, queue, control: localGptControlSnapshot() });
}

function localGptRuntimeSnapshot() {
  let queue = null;
  let meta = {};
  try { queue = JSON.parse(localStorage.getItem(GPT_QUEUE_STORAGE_KEY) || "null"); } catch { queue = null; }
  try { meta = JSON.parse(localStorage.getItem(GPT_QUEUE_META_STORAGE_KEY) || "{}"); } catch { meta = {}; }
  const updatedAt = String(meta.updatedAt || meta.savedAt || queue?.savedAt || "1970-01-01T00:00:00.000Z");
  return { version: 3, revision: Number(meta.revision || 0), updatedAt, queue, control: localGptControlSnapshot() };
}

async function reconcileGptRuntimeState() {
  const local = localGptRuntimeSnapshot();
  let remote;
  try {
    const result = await api("/api/gpt-production/runtime-state");
    remote = result?.state;
  } catch {
    gptReadOnlyRuntimeState = null;
    return { source: "local", state: local };
  }
  const localTime = Date.parse(local.updatedAt) || 0;
  const remoteTime = Date.parse(String(remote?.updatedAt || "")) || 0;
  const remoteWins = Number(remote?.revision || 0) > 0
    && (!isGptRuntimeWriteAuthority()
      || remoteTime > localTime
      || (remoteTime === localTime && Number(remote.revision || 0) > Number(local.revision || 0)));
  if (remoteWins) {
    gptReadOnlyRuntimeState = isGptRuntimeWriteAuthority() ? null : remote;
    applyGptRuntimeControl(remote.control);
    if (remote.queue) {
      localStorage.setItem(GPT_QUEUE_STORAGE_KEY, JSON.stringify({ ...remote.queue, savedAt: remote.updatedAt }));
    } else {
      localStorage.removeItem(GPT_QUEUE_STORAGE_KEY);
    }
    localStorage.setItem(GPT_QUEUE_META_STORAGE_KEY, JSON.stringify({
      updatedAt: remote.updatedAt,
      revision: remote.revision,
      hasQueue: Boolean(remote.queue)
    }));
    return { source: "server", state: remote };
  }
  scheduleGptRuntimeSync(local, 0);
  return { source: "local", state: local };
}

function adoptGptRuntimeQueueIntoWindowWorkers(runtimeState) {
  const tasks = Array.isArray(runtimeState?.queue?.tasks) ? runtimeState.queue.tasks : [];
  if (!tasks.length) return 0;
  const legacyOwner = String(runtimeState?.queue?.activeAccountId || "").trim();
  const legacyKeys = new Set(tasks.map((task) => {
    const requestId = String(task?.requestId || "").trim();
    if (requestId) return `request:${requestId}`;
    const materialPath = normalizeGptAttachmentPath(task?.materialPath || "");
    return materialPath ? `material:${materialPath}` : "";
  }).filter(Boolean));
  // Older builds copied the global queue into every window worker.  When the
  // runtime mirror still carries that same batch, keep one copy at its
  // recorded owner and remove only the stale per-window duplicates. Explicit
  // account-owned tasks remain in their own worker; unrelated tasks remain
  // untouched because they cannot be identified as this legacy batch.
  if (legacyOwner && legacyKeys.size) {
    const workerIds = (Array.isArray(gptAccounts) ? gptAccounts : [])
      .map((account) => String(account?.id || "").trim())
      .filter(Boolean);
    for (const workerId of workerIds) {
      const state = gptWindowWorkerState(workerId);
      if (!Array.isArray(state?.queue) || !state.queue.length) continue;
      const currentTaskId = String(state.queue[state.queueIndex || 0]?.requestId || "");
      let changed = false;
      const nextQueue = state.queue.filter((task) => {
        const requestId = String(task?.requestId || "").trim();
        const materialPath = normalizeGptAttachmentPath(task?.materialPath || "");
        const legacyKey = requestId ? `request:${requestId}` : materialPath ? `material:${materialPath}` : "";
        const taskOwner = String(task?.accountId || task?.accountWindowId || task?.browserIdentityId || "").trim();
        if (!legacyKeys.has(legacyKey)) {
          if (taskOwner && taskOwner !== workerId) {
            changed = true;
            return false;
          }
          return true;
        }
        if (taskOwner && taskOwner !== workerId) {
          changed = true;
          return false;
        }
        if (!taskOwner && workerId !== legacyOwner) {
          changed = true;
          return false;
        }
        if (!taskOwner && workerId === legacyOwner) {
          Object.assign(task, {
            accountId: workerId,
            accountWindowId: workerId,
            browserIdentityId: workerId,
            quotaAccountId: String(task.quotaAccountId || workerId)
          });
          changed = true;
        }
        return true;
      });
      if (changed) {
        state.queue = nextQueue;
        const restoredIndex = currentTaskId
          ? state.queue.findIndex((task) => String(task?.requestId || "") === currentTaskId)
          : -1;
        state.queueIndex = restoredIndex >= 0
          ? restoredIndex
          : Math.max(0, Math.min(Number(state.queueIndex || 0), state.queue.length));
        persistGptWindowWorkerState(workerId, state);
      }
    }
    // Also stamp newly-created per-window tasks that were not part of the
    // old global mirror. They are already owned by their worker; they only
    // lacked the durable identity fields required by the runtime mirror.
    for (const workerId of workerIds) {
      persistGptWindowWorkerState(workerId, gptWindowWorkerState(workerId));
    }
  }
  let adopted = 0;
  for (const persistedTask of tasks) {
    const taskOwner = String(
      persistedTask?.accountId
      || persistedTask?.accountWindowId
      || persistedTask?.browserIdentityId
      || ""
    ).trim();
    // Before independent browser workers existed, the top-level queue had no
    // account identity. On restart, its activeAccountId is the only safe
    // ownership evidence available. Adopt those legacy tasks into that one
    // window; never distribute them to other accounts by guesswork.
    const accountId = String(persistedTask?.accountId || persistedTask?.browserIdentityId || taskOwner || legacyOwner).trim();
    if (!accountId || ["completed", "skipped"].includes(String(persistedTask?._status || ""))) continue;
    const account = gptAccounts.find((item) => String(item?.id || "") === accountId);
    if (!account || account.hidden || account.disabled) continue;
    const state = gptWindowWorkerState(accountId);
    if (state.pausedByUser || state.stoppedByUser) continue;
    const requestId = String(persistedTask.requestId || "");
    const materialPath = normalizeGptAttachmentPath(persistedTask.materialPath || "");
    const duplicate = state.queue.some((task) => (
      requestId && String(task?.requestId || "") === requestId
    ) || (
      materialPath && normalizeGptAttachmentPath(task?.materialPath || "") === materialPath
    ));
    if (duplicate) continue;
    const task = {
      ...persistedTask,
      accountId: String(persistedTask.accountId || accountId),
      accountWindowId: String(persistedTask.accountWindowId || accountId),
      browserIdentityId: String(persistedTask.browserIdentityId || accountId),
      quotaAccountId: String(persistedTask.quotaAccountId || accountId)
    };
    if (task._status === "failed" || task._status === "paused") {
      task.retryFromStage = String(task._stage || task.retryFromStage || "恢复中");
      task.retryFromPercent = Number(task._percent || task.retryFromPercent || 0);
      task._status = "queued";
      task._error = "";
      task._errorCode = "";
    }
    state.queue.push(task);
    state.queueIndex = Math.max(0, Math.min(Number(state.queueIndex || 0), state.queue.length - 1));
    state.lastFailedTask = null;
    state.queuePaused = false;
    state.autoPaused = false;
    state.armed = true;
    persistGptWindowWorkerState(accountId, state);
    adopted += 1;
  }
  return adopted;
}

// The extension can finish the real web workflow shortly after the renderer
// timed out or was refreshed.  In that case the durable conversation log is
// newer than the queue snapshot and the old UI keeps showing "paused/failed"
// until a manual refresh.  Reconcile only a fully evidenced package boundary:
// text saved + images downloaded (enough for the planned count) + archived.
// This never sends another prompt or uploads another attachment.
function gptMaterialIdentityMatches(left = "", right = "") {
  if (window.TBGptAccountRotation?.materialIdentityMatches) {
    return window.TBGptAccountRotation.materialIdentityMatches(left, right);
  }
  const variants = (value) => {
    const normalized = String(value || "").trim().replace(/\\/g, "/").toLowerCase();
    const basename = normalized.split("/").filter(Boolean).at(-1) || normalized;
    const stripped = basename
      .replace(/^当前会话(?:母版|恢复)\s*[×x·:：-]\s*/i, "")
      .replace(/^工作台(?:素材|任务)\s*[×x·:：-]\s*/i, "")
      .trim();
    return [...new Set([basename, stripped].filter((item) => item.length >= 8))];
  };
  const leftVariants = variants(left);
  const rightVariants = variants(right);
  return leftVariants.some((leftValue) => rightVariants.some((rightValue) => (
    leftValue === rightValue
    || leftValue.length >= 8 && rightValue.includes(leftValue)
    || rightValue.length >= 8 && leftValue.includes(rightValue)
  )));
}

function gptMaterialLogEntryMatchesTask(task, entry) {
  const taskValues = [
    task?.materialPath,
    task?.sourceMaterialPath,
    task?.materialName,
    task?.name
  ].map((value) => String(value || "").trim()).filter((value) => value.length >= 8);
  const entryValues = [entry?.materialName, entry?.materialPath, entry?.sourceMaterialPath]
    .map((value) => String(value || "").trim()).filter((value) => value.length >= 8);
  return taskValues.some((taskValue) => entryValues.some((entryValue) => (
    gptMaterialIdentityMatches(taskValue, entryValue)
  )));
}

// During renderer recovery the account profile may point at the last visible
// conversation, not the conversation that owns the queue task.  That is
// especially dangerous when the visible conversation is an already archived
// post: using the account-wide "latest URL" would hydrate its copy into the
// next material and then repeatedly send recovery prompts against the wrong
// boundary.  Resolve the URL from the task's own material/request evidence
// first.  This is read-only; the caller decides whether it is safe to navigate.
async function findDurableGptTaskConversationUrl(accountId = "", task = {}, options = {}) {
  const key = String(accountId || "").trim();
  if (!key || !task || task.taskType !== "material") return "";
  const currentUrl = canonicalGptConversationUrl(String(options.currentUrl || ""));
  const taskUrl = resolveGptTaskConversationUrl(task);
  const history = await apiWithTimeout("/api/gpt-production/history", undefined, 5_000).catch(() => null);
  const logResult = await apiWithTimeout(
    "/api/gpt-production/conversation-log?limit=500",
    undefined,
    5_000
  ).catch(() => null);
  const items = Array.isArray(history?.items) ? history.items : [];
  const entries = Array.isArray(logResult?.entries) ? logResult.entries : [];
  if (!items.length && !entries.length) return "";

  const requestId = String(task.requestId || "").trim();
  const materialEntries = entries.filter((entry) => {
    const entryAccount = String(entry?.account || entry?.accountId || "").trim();
    return (!entryAccount || entryAccount === key) && gptMaterialLogEntryMatchesTask(task, entry);
  });
  const accountByRequest = new Map();
  entries.forEach((entry) => {
    const entryRequestId = String(entry?.requestId || "").trim();
    const entryAccount = String(entry?.account || entry?.accountId || "").trim();
    if (!entryRequestId || !entryAccount) return;
    const accounts = accountByRequest.get(entryRequestId) || new Set();
    accounts.add(entryAccount);
    accountByRequest.set(entryRequestId, accounts);
  });

  const candidates = [];
  items.forEach((item) => {
    if (!item || !gptMaterialLogEntryMatchesTask(task, item)) return;
    const itemAccount = String(item.accountWindowId || item.accountId || "").trim();
    if (itemAccount && itemAccount !== key) return;
    const itemRequestId = String(item.requestId || "").trim();
    const requestAccounts = accountByRequest.get(itemRequestId);
    if (requestAccounts?.size && !requestAccounts.has(key)) return;
    const url = canonicalGptConversationUrl(String(item.conversationUrl || ""));
    if (!url) return;
    const matchingEntries = materialEntries.filter((entry) => {
      const entryRequestId = String(entry?.requestId || "").trim();
      const entryUrl = canonicalGptConversationUrl(String(entry?.conversationUrl || "").split("::material:")[0]);
      return entryUrl === url && (!itemRequestId || !entryRequestId || entryRequestId === itemRequestId);
    });
    const timestamp = Date.parse(String(item.updatedAt || item.timestamp || "")) || 0;
    let score = 0;
    if (itemRequestId && itemRequestId === requestId) score += 120;
    if (url === taskUrl) score += 35;
    if (url !== currentUrl) score += 90;
    if (matchingEntries.length) score += 80;
    if (matchingEntries.some((entry) => [
      "upload-sent", "plan-received", "confirm-sent", "images-detected",
      "copy-requested", "copy-received", "text-saved", "archived"
    ].includes(String(entry?.event || "")))) score += 35;
    if (!["作品归档完成", "completed", "archived", "skipped"].includes(String(item.stage || ""))) score += 20;
    candidates.push({ url, score, timestamp });
  });

  // Log-only evidence is useful after a checkpoint write was interrupted.
  // It is still material-scoped and account-scoped, so it cannot fall back to
  // an unrelated account's latest conversation.
  materialEntries.forEach((entry) => {
    const url = canonicalGptConversationUrl(String(entry?.conversationUrl || "").split("::material:")[0]);
    if (!url) return;
    const timestamp = Date.parse(String(entry?.timestamp || "")) || 0;
    let score = 80 + (url !== currentUrl ? 90 : 0);
    if (String(entry?.requestId || "").trim() === requestId) score += 120;
    if (url === taskUrl) score += 35;
    candidates.push({ url, score, timestamp });
  });
  candidates.sort((left, right) => right.score - left.score || right.timestamp - left.timestamp);
  return candidates[0]?.url || "";
}

async function hydrateGptWorkflowFromConversationLog(queue = [], accountId = "") {
  const targetQueue = Array.isArray(queue) ? queue : [];
  const key = String(accountId || "").trim();
  if (!targetQueue.length || !key) return 0;
  // Conversation-log reads can briefly queue behind the local 4327 worker
  // while a browser window is probing or packaging.  A short UI timeout made
  // restart reconciliation silently miss durable text/images/archive proof,
  // after which hydration could keep the old task at "等待文案" forever.
  const result = await apiWithTimeout("/api/gpt-production/conversation-log?limit=400", undefined, 15_000).catch(() => null);
  const entries = Array.isArray(result?.entries) ? result.entries : [];
  if (!entries.length) return 0;
  const identity = (value) => String(value || "").trim().toLowerCase();
  const imageIdentity = (value) => {
    const raw = String(value || "").trim();
    return raw.match(/[?&]id=([^&]+)/i)?.[1] || raw.split("?")[0];
  };
  const changedTasks = new Set();
  for (const task of targetQueue) {
    if (!task || task.taskType !== "material" || task._submittedToGpt !== true) continue;
    // Completion reconciliation runs immediately before this hydration pass.
    // Do not turn a durable completed/skipped task back into queued merely
    // because its historical image boundary is still present in the log.
    if (["completed", "skipped"].includes(String(task._status || ""))) continue;
    const taskName = identity(task.name || task.materialPath?.split(/[\\/]+/).pop());
    const requestIds = new Set();
    let cursor = task;
    for (let depth = 0; cursor && depth < 24; depth += 1) {
      const requestId = String(cursor.requestId || "").trim();
      if (!requestId || requestIds.has(requestId)) break;
      requestIds.add(requestId);
      const parentId = String(cursor.retryOf || "").trim();
      cursor = parentId ? targetQueue.find((candidate) => String(candidate?.requestId || "") === parentId) : null;
    }
    const related = entries.filter((entry) => {
      if (String(entry.account || entry.accountId || "").trim() !== key) return false;
      const requestIdMatch = requestIds.has(String(entry.requestId || "").trim());
      const materialMatch = gptMaterialLogEntryMatchesTask(task, entry)
        || taskName && taskName === identity(entry.materialName);
      // A request ID is not sufficient after a bad rebind: the same local task
      // can temporarily inherit an archived conversation's request metadata.
      // Keep request-ID matching only when the log entry also carries no
      // contradictory material identity.
      const hasEntryIdentity = [entry?.materialName, entry?.materialPath, entry?.sourceMaterialPath]
        .some((value) => String(value || "").trim().length >= 8);
      return materialMatch || requestIdMatch && !hasEntryIdentity;
    });
    // A renderer can be restarted after the live semantic detector has
    // adopted a complete batch but before the normal `images-detected` event
    // is flushed. Treat the durable boundary event as image evidence too;
    // otherwise the next inspection falls back to one lazy thumbnail and
    // incorrectly blocks the already-complete copy/archive stage.
    const imageEvents = related
      .filter((entry) => ["images-detected", "images-detection-decision", "live-image-boundary-adopted"].includes(String(entry?.event || "")))
      .sort((a, b) => Date.parse(String(a.timestamp || "")) - Date.parse(String(b.timestamp || "")));
    const imageEvent = imageEvents.at(-1);
    const imageUrls = [...new Map(
      (Array.isArray(imageEvent?.imageUrls) ? imageEvent.imageUrls : [])
        .map((url) => [imageIdentity(url), String(url || "").trim()])
        .filter(([id, url]) => id && url)
    ).values()];
    const downloadedEvents = related.filter((entry) => entry.event === "images-downloaded");
    const archivedEvents = related.filter((entry) => entry.event === "archived");
    const downloadedCount = downloadedEvents.reduce((max, entry) => Math.max(
      max,
      Number(entry?.meta?.count || 0),
      Array.isArray(entry?.downloadedFiles) ? entry.downloadedFiles.length : 0
    ), 0);
    const archivedCount = archivedEvents.reduce((max, entry) => Math.max(
      max,
      Number(entry?.meta?.imageCount || 0),
      Number(entry?.imageCount || 0)
    ), 0);
    const meta = imageEvent?.meta && typeof imageEvent.meta === "object" ? imageEvent.meta : {};
    const workflow = task.workflow && typeof task.workflow === "object" ? task.workflow : {};
    const observedImageCount = Math.max(
      Number(meta.detectedCount || 0),
      imageUrls.length,
      downloadedCount,
      archivedCount,
      Number(workflow.generatedImageActualCount || 0),
      Array.isArray(workflow.generatedImageUrls) ? workflow.generatedImageUrls.length : 0
    );
    const expectedImages = Math.max(
      0,
      Math.min(10, Number(meta.expectedImages || 0)),
      Math.min(10, Number(task.expectedImages || 0)),
      Math.min(10, Number(workflow.plannedImageCount || 0)),
      Math.min(10, observedImageCount)
    );
    // A durable detection-decision is still a valid post-confirmation
    // boundary when the batch is partial.  Requiring observed >= expected
    // here used to discard 8/10 evidence during restart hydration; the next
    // live inspection then saw "waiting-plan" and downgraded the task back to
    // upload/plan, which caused the same work to be requested repeatedly.
    const hasDurableImageBoundary = Boolean(imageEvent)
      && observedImageCount > 0
      && ["images-detected", "images-detection-decision", "live-image-boundary-adopted"].includes(
        String(imageEvent?.event || "")
      );
    if (!expectedImages || (!hasDurableImageBoundary && observedImageCount < expectedImages)) continue;
    const imageBatchComplete = observedImageCount >= expectedImages;
    const imageTimestamp = related.reduce((latest, entry) => {
      // `archived` carries the final count, but it is not an image-observation
      // event. Keeping it out of this timestamp is important because the copy
      // is normally received before the archive write; otherwise a restart can
      // incorrectly hide the valid copy evidence and fall back to "等待文案".
      if (!["images-detected", "images-downloaded"].includes(String(entry?.event || ""))) return latest;
      const timestamp = Date.parse(String(entry?.timestamp || ""));
      return Number.isFinite(timestamp) ? Math.max(latest, timestamp) : latest;
    }, 0);
    const copyRequested = imageBatchComplete && related.some((entry) =>
      ["copy-requested", "copy-recovery-sent"].includes(String(entry.event || ""))
      && (!imageTimestamp || Date.parse(String(entry.timestamp || "")) >= imageTimestamp)
    );
    const nextUrls = imageUrls.length >= (Array.isArray(workflow.generatedImageUrls) ? workflow.generatedImageUrls.length : 0)
      ? imageUrls
      : workflow.generatedImageUrls;
    task.workflow = {
      ...workflow,
      planSubmitted: true,
      planDone: true,
      imageSubmitted: true,
      plannedImageCount: Math.max(Number(workflow.plannedImageCount || 0), expectedImages),
      generatedImageUrls: nextUrls,
      generatedImageActualCount: Math.max(Number(workflow.generatedImageActualCount || 0), observedImageCount),
      ...(downloadedCount > 0 ? {
        downloadResult: {
          ...(workflow.downloadResult || {}),
          count: Math.max(Number(workflow.downloadResult?.count || 0), downloadedCount)
        }
      } : {}),
      recoveryBoundaryConfirmed: true,
      ...(imageBatchComplete ? {} : { imageBoundaryPartial: true }),
      ...(copyRequested ? { textSubmitted: true, expectPlatformCopy: true } : {})
    };
    task.expectedImages = Math.max(Number(task.expectedImages || 0), expectedImages);
    task._status = "queued";
    task._error = "";
    task._errorCode = "";
    task._stage = copyRequested ? "等待文案" : "等待图片";
    task._percent = copyRequested ? 65 : 48;
    task.retryFromStage = copyRequested ? "等待小红书文案" : "等待图片";
    task.retryFromPercent = task._percent;
    changedTasks.add(task);
  }
  if (changedTasks.size) {
    targetQueue.forEach((task) => {
      if (changedTasks.has(task)) task._conversationLogHydratedAt = new Date().toISOString();
    });
  }
  return changedTasks.size;
}

function isFalsePartialImageRecoveryAfterDurableArchive(taskEntries, archivedAt, options = {}) {
  const entries = Array.isArray(taskEntries) ? taskEntries : [];
  const archiveTime = Number(archivedAt || 0);
  if (!archiveTime) return false;
  const archivedEntries = entries
    .filter((entry) => entry?.event === "archived")
    .filter((entry) => (Date.parse(String(entry?.timestamp || "")) || 0) === archiveTime);
  if (!archivedEntries.length) return false;
  const expectedImages = Math.max(
    0,
    Number(options.expectedImageCount || 0),
    Number(options.plannedImageCount || 0)
  );
  const imageCount = Math.max(
    ...entries
      .filter((entry) => {
        const timestamp = Date.parse(String(entry?.timestamp || "")) || 0;
        return timestamp > 0 && timestamp <= archiveTime
          && ["images-downloaded", "archived"].includes(String(entry?.event || ""));
      })
      .map((entry) => Math.max(
        Number(entry?.meta?.count || 0),
        Number(entry?.meta?.imageCount || 0),
        Array.isArray(entry?.downloadedFiles) ? entry.downloadedFiles.length : 0
      )),
    0
  );
  const copyLength = Math.max(
    ...entries
      .filter((entry) => {
        const timestamp = Date.parse(String(entry?.timestamp || "")) || 0;
        return timestamp > 0 && timestamp <= archiveTime
          && ["text-saved", "archived"].includes(String(entry?.event || ""));
      })
      .map((entry) => Number(entry?.meta?.copyLength || entry?.meta?.copyTextLength || 0)),
    0
  );
  if (!imageCount || (expectedImages > 0 && imageCount < expectedImages) || copyLength < 300) return false;
  const postArchiveEvents = entries
    .filter((entry) => (Date.parse(String(entry?.timestamp || "")) || 0) > archiveTime)
    .map((entry) => String(entry?.event || "").trim())
    .filter(Boolean);
  if (!postArchiveEvents.length) return false;
  // A lazy thumbnail recount can emit a partial-recovery prompt after a
  // durable archive, without any new user submission or new image evidence.
  // That prompt is diagnostic noise, not a new production attempt.  Ignore
  // only this narrow event-only suffix; a real send, image detection,
  // download, copy, or archive event must still create a new boundary.
  const falseRecoveryOnlyEvents = new Set([
    "partial-image-recovery-sent",
    "partial-image-recovery-suppressed",
    "images-detection-decision"
  ]);
  return postArchiveEvents.every((event) => falseRecoveryOnlyEvents.has(event));
}

async function reconcileCompletedGptTasksFromConversationLog(queue = gptTestQueue, options = {}) {
  const targetQueue = Array.isArray(queue) ? queue : gptTestQueue;
  const legacyQueue = targetQueue === gptTestQueue && !options.workerState;
  if (legacyQueue && gptAutoRunning) return 0;
  if (!targetQueue.length) return 0;
  // Keep completed-from-log tasks in the candidate set as well.  The queue
  // may already be marked completed while its per-account runtime snapshot
  // still says failed/running (the exact stale-card symptom this repair is
  // meant to remove).
  const pending = targetQueue.filter((task) => task && (
    !["completed", "skipped"].includes(task._status) || task._completedFromLog
  ));
  if (!pending.length) return 0;
  // This is recovery truth, not a cosmetic dashboard request.  Allow the
  // local service enough time to finish a bounded tail read under production
  // load so a completed task cannot be mistaken for a live blocked task.
  const result = await apiWithTimeout("/api/gpt-production/conversation-log?limit=200", undefined, 15_000).catch(() => null);
  const entries = Array.isArray(result?.entries) ? result.entries : [];
  if (!entries.length) return 0;
  const entriesByRequestId = new Map();
  for (const entry of entries) {
    const requestId = String(entry?.requestId || "").trim();
    if (!requestId) continue;
    const bucket = entriesByRequestId.get(requestId) || [];
    bucket.push(entry);
    entriesByRequestId.set(requestId, bucket);
  }
  let changed = 0;
  let runtimeChanged = 0;
  let blockedByNewerAttempt = false;
  let staleAttemptTask = null;
  const attemptStartEvents = new Set([
    "sent",
    "upload-sent",
    "plan-recovery-sent",
    "confirm-sent",
    "partial-image-recovery-sent",
    "image-recovery-sent",
    "images-detected",
    "copy-requested",
    "copy-recovery-sent",
    "nudge-plan-sent"
  ]);
  const runtimeForReconciliation = options.accountId
    ? readGptWindowRuntime(options.accountId)
    : null;
  const allowStaleRunningTaskReconciliation = options.reconcileRunning === true
    && runtimeForReconciliation
    && ["retry-wait", "failed", "probing"].includes(String(runtimeForReconciliation.status || ""))
    && !gptWindowWorkerPromises.has(String(options.accountId || ""));
  for (const task of pending) {
    const taskAccountId = String(task.accountId || options.accountId || activeGptAccountId || "").trim();
    // A renderer restart can mint a recovery requestId even though the GPT
    // conversation and its archive evidence belong to the same material. Use
    // material identity only for an already-submitted task; a fresh task must
    // never inherit an older package from the same folder.
    const materialEntries = task._submittedToGpt === true
      ? entries.filter((entry) => (
        (!String(entry?.account || entry?.accountId || "").trim()
          || String(entry?.account || entry?.accountId || "").trim() === taskAccountId)
        && gptMaterialLogEntryMatchesTask(task, entry)
      ))
      : [];
    const directEntries = entriesByRequestId.get(String(task.requestId || "").trim()) || [];
    // A stale worker can still report this request as running for a short
    // time after the archive route has durably completed it.  The archive
    // event is the final idempotent boundary: reconcile that exact request
    // immediately instead of letting the old recovery promise reopen the
    // conversation and block the next material/account.
    const directArchiveEvidence = directEntries.some((entry) => entry?.event === "archived");
    if (task._status === "running" && !allowStaleRunningTaskReconciliation && !directArchiveEvidence) continue;
    const requestIds = new Set();
    let cursor = task;
    for (let depth = 0; cursor && depth < 24; depth += 1) {
      const requestId = String(cursor.requestId || "").trim();
      if (!requestId || requestIds.has(requestId)) break;
      requestIds.add(requestId);
      const parentId = String(cursor.retryOf || "").trim();
      cursor = parentId
        ? targetQueue.find((candidate) => String(candidate?.requestId || "") === parentId)
        : null;
    }
    const taskEntries = [...new Set([
      ...[...requestIds].flatMap((id) => entriesByRequestId.get(id) || []),
      ...materialEntries
    ])];
    const latestCurrentAttemptAt = [...new Set([...directEntries, ...materialEntries])].reduce((latest, entry) => {
      if (!attemptStartEvents.has(String(entry?.event || ""))) return latest;
      const time = Date.parse(String(entry?.timestamp || ""));
      return Number.isFinite(time) ? Math.max(latest, time) : latest;
    }, 0);
    const latestArchivedAt = taskEntries.reduce((latest, entry) => {
      if (entry?.event !== "archived") return latest;
      const time = Date.parse(String(entry?.timestamp || ""));
      return Number.isFinite(time) ? Math.max(latest, time) : latest;
    }, 0);
    // A retry is a new workflow boundary even when it points at an older
    // request through retryOf. Never let the older request's archive proof
    // complete the newer attempt; that is how a partially generated retry
    // appeared as "作品已闭环" after restart.
    const hasRetryBoundary = Boolean(String(task.retryOf || "").trim());
    const falsePartialRecoveryAfterArchive = isFalsePartialImageRecoveryAfterDurableArchive(
      taskEntries,
      latestArchivedAt,
      {
        expectedImageCount: task.workflow?.plannedImageCount,
        plannedImageCount: task.expectedImages
      }
    );
    const newerAttemptThanArchive = latestCurrentAttemptAt > 0
      && ((latestArchivedAt > 0 && latestCurrentAttemptAt > latestArchivedAt)
        // The parent may have fallen out of the bounded queue snapshot. A
        // retry id plus a durable completed marker is still enough to prove
        // that the current direct attempt must be checked independently.
        || (hasRetryBoundary && task._completedFromLog && latestArchivedAt === 0))
      && !falsePartialRecoveryAfterArchive;
    if (newerAttemptThanArchive) {
      if (task._completedFromLog || task._status === "completed") {
        task._status = "paused";
        task._stage = "等待归档";
        task._percent = 64;
        task._error = "当前重试晚于历史归档，尚未完成当前作品归档";
        task._errorCode = "STALE_ARCHIVE_CHAIN";
        task._completedFromLog = false;
        task._completedAt = "";
        task._result = {
          ...(task._result || {}),
          downloadedImages: 0,
          copyTextLength: 0,
          packagePath: ""
        };
        blockedByNewerAttempt = true;
        staleAttemptTask = task;
        changed += 1;
      }
      continue;
    }
    const textSaved = taskEntries.find((entry) => entry.event === "text-saved");
    const imagesDownloaded = taskEntries.find((entry) => entry.event === "images-downloaded");
    const archived = taskEntries.find((entry) => entry.event === "archived");
    // A task marked _completedFromLog already passed the three-evidence gate
    // in an earlier poll; retain its durable result even if the bounded log
    // window has since rotated that request out.
    const completedResult = task._completedFromLog ? (task._result || {}) : null;
    if ((!textSaved || !imagesDownloaded || !archived) && !completedResult) continue;
    const copyLength = Number(textSaved?.meta?.copyLength || completedResult?.copyTextLength || 0);
    const imageCount = Math.max(
      Number(imagesDownloaded?.meta?.count || 0),
      Array.isArray(imagesDownloaded?.downloadedFiles) ? imagesDownloaded.downloadedFiles.length : 0,
      Number(archived?.meta?.imageCount || 0),
      Number(completedResult?.downloadedImages || 0)
    );
    const plannedCount = Math.max(0, Number(task.workflow?.plannedImageCount || task.expectedImages || 0));
    const durableArchivePackagePath = String(archived?.packagePath || completedResult?.packagePath || "").trim();
    const durableArchiveBoundary = Boolean(
      archived
      && durableArchivePackagePath
      && copyLength >= 300
      && imageCount > 0
    );
    // The archive event is the final idempotent boundary.  A stale plan count
    // must not reopen or block an already packaged work (for example a valid
    // 9-image set whose recovered plan estimate still says 10).
    if (copyLength < 300 || !imageCount || (!durableArchiveBoundary && plannedCount > 0 && imageCount < plannedCount)) continue;
    if (task._status !== "completed" || task._stage !== "作品已闭环（后台完成）") {
      task._status = "completed";
      task._stage = "作品已闭环（后台完成）";
      task._percent = 100;
      task._error = "";
      task._errorCode = "";
      task._completedFromLog = true;
      task._completedAt = String(archived?.timestamp || task._completedAt || new Date().toISOString());
      task._result = {
        ...(task._result || {}),
        downloadedImages: imageCount,
        copyTextLength: copyLength,
        packagePath: String(archived?.packagePath || task._result?.packagePath || "")
      };
      changed += 1;
    }
    const reconciledAccountId = String(task.accountId || activeGptAccountId || "");
    const anotherActiveSubmittedTask = targetQueue.some((candidate) => {
      if (!candidate || candidate === task) return false;
      if (String(candidate.accountId || options.accountId || activeGptAccountId || "") !== reconciledAccountId) return false;
      if (candidate._submittedToGpt !== true) return false;
      return !["completed", "archived", "skipped"].includes(String(candidate._status || ""));
    });
    const windowState = reconciledAccountId ? gptWindowRuntime?.[reconciledAccountId] : null;
    // A durable restart checkpoint can be newer than an older archived queue
    // row. Never let the older row clear the account window while another
    // submitted task still needs copy/download/archive recovery.
    if (anotherActiveSubmittedTask) continue;
    if (windowState && (!windowState.currentTaskId || String(windowState.currentTaskId) === String(task.requestId))) {
      markGptWindowSetCompleted(reconciledAccountId, task.requestId);
      if (windowState.status !== "completed"
        || windowState.currentTaskId
        || windowState.currentStage !== "作品已闭环（后台完成）"
        || Number(windowState.currentPercent) !== 100
        || Number(windowState.generatedImages || 0) !== imageCount
        || windowState.lastError) {
        windowState.status = "completed";
        windowState.currentTaskId = "";
        windowState.currentStage = "作品已闭环（后台完成）";
        windowState.currentPercent = 100;
        windowState.generatedImages = imageCount;
        windowState.expectedImages = Math.max(Number(windowState.expectedImages || 0), imageCount);
        windowState.lastError = "";
        windowState.updatedAt = Date.now();
        runtimeChanged += 1;
      }
    }
  }
  if (!changed && !runtimeChanged) return 0;
  let targetQueueIndex = legacyQueue
    ? gptTestQueueIndex
    : Math.max(0, Number(options.workerState?.queueIndex || 0));
  while (targetQueueIndex < targetQueue.length
    && ["completed", "skipped"].includes(targetQueue[targetQueueIndex]?._status)) {
    targetQueueIndex += 1;
  }
  if (legacyQueue) {
    gptTestQueueIndex = targetQueueIndex;
  } else if (options.workerState) {
    options.workerState.queueIndex = targetQueueIndex;
  }
  if (blockedByNewerAttempt && staleAttemptTask) {
    gptLastFailedTask = staleAttemptTask;
    gptLastFailedStage = String(staleAttemptTask._stage || "等待归档");
    gptLastFailedPercent = Number(staleAttemptTask._percent || 64);
  } else {
    gptLastFailedTask = null;
    gptLastFailedStage = "";
    gptLastFailedPercent = 0;
  }
  // A user pause/stop remains authoritative.  A continuous automatic run may
  // continue to the next task after the log proves this task is complete;
  // one-shot modes remain paused so their explicit batch boundary is kept.
  const currentAccountId = String(
    options.accountId
      || staleAttemptTask?.accountId
      || targetQueue[targetQueueIndex - 1]?.accountId
      || activeGptAccountId
  );
  const userHeld = legacyQueue
    ? gptWindowIsUserPaused(currentAccountId) || gptWindowIsUserStopped(currentAccountId)
    : Boolean(options.workerState?.pausedByUser || options.workerState?.stoppedByUser);
  if (legacyQueue) {
    gptQueuePaused = blockedByNewerAttempt || userHeld || !isContinuousGptMode();
    persistGptQueue();
  } else if (options.workerState) {
    options.workerState.queuePaused = blockedByNewerAttempt || userHeld || options.workerState.queuePaused;
    if (blockedByNewerAttempt && staleAttemptTask) {
      options.workerState.lastFailedTask = staleAttemptTask;
      options.workerState.lastFailedStage = String(staleAttemptTask._stage || "等待归档");
      options.workerState.lastFailedPercent = Number(staleAttemptTask._percent || 64);
    }
    persistGptWindowWorkerState(currentAccountId, options.workerState);
  }
  if (changed) {
    const message = blockedByNewerAttempt
      ? "已阻止旧归档记录覆盖当前重试；当前作品停在等待归档"
      : `后台已完成 ${changed} 套作品，点击继续开始下一套`;
    if (legacyQueue) updateGptTestQueueStatus(message);
    else updateGptWindowUi(currentAccountId, () => updateGptTestQueueStatus(message));
  }
  return changed + runtimeChanged;
}

// A per-window worker can finish the real browser workflow after its renderer
// promise timed out. The legacy queue reconciliation above runs on the
// visible renderer, but independent account workers must be reconciled even
// when another browser tab is active. This is read-only: it consumes only
// the durable conversation log and never sends a prompt or uploads again.
async function reconcileIndependentGptWindowFromConversationLog(accountId) {
  const key = String(accountId || "");
  if (!key || gptWindowWorkerPromises.has(key) || !gptWindowAutoStartAllowed(key)) return 0;
  const state = gptWindowWorkerState(key);
  if (!Array.isArray(state.queue) || !state.queue.length) return 0;
  const runtime = readGptWindowRuntime(key);
  const recoverableStatus = ["retry-wait", "failed", "probing"].includes(String(runtime.status || ""));
  if (!recoverableStatus && !state.queue.some((task) => task?._completedFromLog)) return 0;
  const changed = await reconcileCompletedGptTasksFromConversationLog(state.queue, {
    accountId: key,
    workerState: state,
    reconcileRunning: recoverableStatus
  }).catch(() => 0);
  if (!changed) return 0;
  persistGptWindowWorkerState(key, state);
  persistGptQueue();
  if (gptWindowAutoStartAllowed(key)) scheduleContinuousGptProduction(1500);
  return changed;
}

// Restart recovery must run before continuous material selection.  A worker
// queue is renderer-local, while the GPT conversation/checkpoint is durable;
// after an Electron restart the local queue can be empty even though the
// browser is still parked on a submitted plan, image batch, or copy boundary.
// Reclaim that exact conversation first so the scheduler cannot upload a new
// material into the old conversation.  This is read-only until the normal
// worker resumes the adopted checkpoint.
async function restoreIndependentGptCheckpointAtStartup(accountId) {
  const key = String(accountId || "").trim();
  if (!key || !gptWindowAutoStartAllowed(key) || gptWindowWorkerPromises.has(key)) return null;
  const account = gptAccounts.find((item) => String(item?.id || "") === key);
  if (!account || account.hidden || account.disabled) return null;
  const state = gptWindowWorkerState(key);
  const runtime = readGptWindowRuntime(key);
  if (state.pausedByUser || state.stoppedByUser || runtime.pausedByUser || runtime.stoppedByUser) return null;
  const startupTaskIds = [
    state.queue?.[state.queueIndex || 0]?.requestId,
    runtime.currentTaskId
  ].map((requestId) => String(requestId || "").trim()).filter(Boolean);
  // A task that already exhausted its bounded recovery budget is intentionally
  // isolated. Only the task still owned by the durable cursor/runtime may gate
  // startup inspection. `lastFailedTask` is historical once the cursor has
  // advanced; letting that stale mirror participate here can suppress a newer
  // real plan already visible in the same /c/... conversation forever.
  if (startupTaskIds.some((requestId) => isAutomaticGptTaskQuarantined(key, requestId)
    && !isRetryableLegacyImageBoundaryQuarantine(key, requestId))) return null;
  if (runtime.status === "waiting-quota" && Number(runtime.nextProbeAt || 0) > Date.now()) {
    // Quota only blocks a new image request.  The normal quota reconciliation
    // still probes a completed-copy boundary; do not force a new task here.
    return null;
  }
  let inspection = await boundedGptBrowserCall(
    window.gptWorkbench?.inspectStatus?.(key),
    GPT_INSPECT_CALL_TIMEOUT_MS
  ).catch(() => null);
  if (inspection?.authenticationRequired === true || inspection?.generating === true) return null;
  const startupCursorTask = state.queue?.[Math.max(0, Number(state.queueIndex || 0))] || null;
  const pendingFreshCursor = startupCursorTask?.taskType === "material"
    && (startupCursorTask.workflowVariant === "fresh-session-fixed-template"
      || startupCursorTask.sessionPolicy === "fresh-session"
      || startupCursorTask.navigation === "new-chat"
      || startupCursorTask._freshConversationBootstrap === true)
    && !canonicalGptConversationUrl(
      startupCursorTask.conversationUrl
        || startupCursorTask.browserConversationUrl
        || startupCursorTask.chatUrl
    );
  if (pendingFreshCursor && isEmptyFreshGptLiveBoundary(inspection)) {
    // The account is genuinely parked on an empty ChatGPT composer.  This is
    // the expected boundary for an unsubmitted fresh-session task, not proof
    // that the account's most recent historical checkpoint owns the page.
    // A pre-submit crash may have written `_submittedToGpt` before the remote
    // turn existed, so normalize that marker in place and keep the same queue
    // cursor/material lock instead of adopting another material from history.
    if (startupCursorTask._submittedToGpt === true) {
      await reconcileFreshGptTaskAgainstLiveBoundary(startupCursorTask, key).catch(() => false);
    }
    startupCursorTask._submittedToGpt = false;
    startupCursorTask._dispatchingToGpt = false;
    startupCursorTask.conversationUrl = "";
    startupCursorTask.browserConversationUrl = "";
    startupCursorTask.navigation = "new-chat";
    startupCursorTask._freshConversationBootstrap = true;
    startupCursorTask._status = "queued";
    startupCursorTask._error = "";
    startupCursorTask._errorCode = "";
    persistGptWindowWorkerState(key, state);
    return null;
  }
  let stage = String(inspection?.stage || "");
  let adopted = null;
  if (recoverableGptConversationStage(stage)) {
    adopted = await adoptRecoverableGptConversationCheckpoint(key, state, inspection).catch(() => null);
  } else if (stage === "completed-copy-pending-package") {
    adopted = await adoptCompletedGptConversationCheckpoint(key, state, inspection).catch(() => null);
  }
  if (!adopted) {
    // The native probe can time out while the embedded browser is still
    // reconnecting. Use the exact durable conversation URL plus the saved
    // checkpoint as a read-only recovery view; this never authorizes a fresh
    // upload and lets the normal worker resume the original request.
    const [history, conversationLog] = await Promise.all([
      apiWithTimeout("/api/gpt-production/history", undefined, 5_000).catch(() => null),
      apiWithTimeout("/api/gpt-production/conversation-log?limit=500", undefined, 5_000).catch(() => null)
    ]);
    const liveUrl = canonicalGptConversationUrl(
      knownGptConversationUrl(key, readGptWindowRuntime(key))
    );
    const accountByRequest = new Map();
    (Array.isArray(conversationLog?.entries) ? conversationLog.entries : []).forEach((entry) => {
      const requestId = String(entry?.requestId || "").trim();
      const entryAccount = String(entry?.account || entry?.accountId || "").trim();
      if (!requestId || !entryAccount) return;
      const owners = accountByRequest.get(requestId) || new Set();
      owners.add(entryAccount);
      accountByRequest.set(requestId, owners);
    });
    const candidates = (Array.isArray(history?.items) ? history.items : [])
      .filter((item) => {
        if (!item || String(item.packagePath || "").trim()) return false;
        const requestId = String(item.requestId || "").trim();
        const retryableLegacyBoundary = isRetryableLegacyImageBoundaryQuarantine(key, requestId);
        if (!retryableLegacyBoundary
          && (["作品归档完成", "completed", "archived", "skipped", "自动隔离，待复核"].includes(String(item.stage || ""))
            || String(item.status || "") === "skipped"
            || String(item.errorCode || "") === "AUTO_RECOVERY_QUARANTINED")) return false;
        const accountMatches = (() => {
          const recordedAccount = String(item.accountWindowId || item.accountId || "").trim();
          if (recordedAccount) return recordedAccount === key;
          return accountByRequest.get(requestId)?.has(key) === true;
        })();
        if (!accountMatches) return false;
        const itemConversationUrl = canonicalGptConversationUrl(String(item.conversationUrl || ""));
        // Same-account recency alone is never enough to replace the current
        // queue cursor. Recovery must own the exact durable request or the
        // exact real /c/... conversation currently visible in this account.
        return startupTaskIds.includes(requestId)
          || Boolean(liveUrl && itemConversationUrl === liveUrl);
      })
      .sort((left, right) => {
        const leftCurrent = startupTaskIds.includes(String(left.requestId || "")) ? 1 : 0;
        const rightCurrent = startupTaskIds.includes(String(right.requestId || "")) ? 1 : 0;
        const leftLive = canonicalGptConversationUrl(String(left.conversationUrl || "")) === liveUrl ? 1 : 0;
        const rightLive = canonicalGptConversationUrl(String(right.conversationUrl || "")) === liveUrl ? 1 : 0;
        return rightCurrent - leftCurrent
          || (Date.parse(String(right.updatedAt || "")) || 0) - (Date.parse(String(left.updatedAt || "")) || 0)
          || rightLive - leftLive;
      });
    const checkpointCandidate = candidates[0];
    if (checkpointCandidate) {
      const checkpointResponse = await apiWithTimeout(
        "/api/gpt-production/checkpoint?requestId=" + encodeURIComponent(String(checkpointCandidate.requestId || "")),
        undefined,
        5_000
      ).catch(() => null);
      const checkpoint = checkpointResponse?.checkpoint || {};
      const recoveryConversationUrl = canonicalGptConversationUrl(
        checkpoint.conversationUrl || checkpointCandidate.conversationUrl || liveUrl
      );
      // chatgpt.com/ is a composer boundary, never a submitted conversation.
      if (!recoveryConversationUrl) return null;
      const materialFolder = String(
        checkpoint.sourceMaterialPath
          || checkpointCandidate.sourceMaterialPath
          || ""
      ).split(/[\\/]+/).filter(Boolean).pop() || "";
      const checkpointStage = String(checkpoint.stage || checkpointCandidate.stage || "");
      const fallbackStage = /copy|文案/i.test(checkpointStage)
        ? "waiting-copy"
        : /image|图片|生图/i.test(checkpointStage)
          ? "waiting-images"
          : /plan|计划/i.test(checkpointStage)
            ? "waiting-plan"
            : "waiting-plan";
      inspection = {
        ...(inspection || {}),
        stage: fallbackStage,
        conversationUrl: recoveryConversationUrl,
        patrolLedgerKey: recoveryConversationUrl,
        materialText: materialFolder,
        expectedImageCount: Number(checkpoint.plannedImageCount || checkpointCandidate.plannedImageCount || 0),
        latestImageCount: Number(checkpoint.generatedImageActualCount || checkpointCandidate.downloadedImageCount || 0),
        latestImageUrls: Array.isArray(checkpoint.generatedImageUrls) ? checkpoint.generatedImageUrls : [],
        copyText: String(checkpoint.copyText || ""),
        latestAssistantText: String(checkpoint.copyText || ""),
        checkpointTextSubmitted: checkpoint.textSubmitted === true,
        canInjectNext: false,
        generating: false,
        authenticationRequired: false,
        patrolState: { ...(inspection?.patrolState || {}), safeToAct: true }
      };
      stage = fallbackStage;
      adopted = await adoptRecoverableGptConversationCheckpoint(key, state, inspection).catch(() => null);
    }
  }
  if (!adopted?.adopted) return null;
  state.autoRunning = false;
  state.autoPaused = false;
  state.queuePaused = false;
  state.armed = true;
  persistGptWindowWorkerState(key, state);
  writeGptWindowRuntime(key, {
    status: "probing",
    currentTaskId: String(adopted.requestId || adopted.ownerTask?.requestId || ""),
    currentStage: "重启后已恢复原 GPT 对话检查点，准备继续",
    currentPercent: Number(adopted.ownerTask?._percent || 24),
    nextRetryAt: null,
    lastError: ""
  });
  return adopted;
}

function isContinuousGptProductionArmed() {
  if (!isContinuousGptMode()) return false;
  if (localStorage.getItem(GPT_CONTINUOUS_RUN_STORAGE_KEY) === "true") return true;
  // The single-account automatic mode is intentionally unattended by
  // default. A renderer restart can lose the legacy global armed flag while
  // the per-window settings and checkpoints still say to keep producing.
  // Treat any eligible automatic window as the durable arming source; explicit
  // pause/stop and manual/disabled windows remain excluded by the per-window
  // scheduler and recovery gates.
  return gptAccounts.some((account) => {
    if (account.hidden || account.disabled) return false;
    const settings = gptWindowSettings(account.id);
    const runtime = readGptWindowRuntime(account.id);
    return independentGptWindowMode(settings.mode)
      && settings.continuousAutoStart !== false
      && !runtime.pausedByUser
      && !runtime.stoppedByUser;
  });
}

function setContinuousGptProductionArmed(armed) {
  if (armed) localStorage.setItem(GPT_CONTINUOUS_RUN_STORAGE_KEY, "true");
  else localStorage.removeItem(GPT_CONTINUOUS_RUN_STORAGE_KEY);
  scheduleGptControlSync();
}

function currentGptQueueIntegrityBlock() {
  const task = gptTestQueue[gptTestQueueIndex];
  if (!task || task._status === "completed") return null;
  const code = String(task._errorCode || "");
  if (!["COMPOSER_ATTACHMENTS_PENDING", "COMPOSER_DRAFT_PENDING", "COMPOSER_DRAFT_NOT_SET", "MIXED_POST_ATTACHMENTS", "MATERIAL_ROOT_MISSING", "COMPOSER_ATTACHMENT_CONFLICT", "LOCAL_BRIDGE_FETCH_FAILED", "ATTACHMENT_UPLOAD_NOT_READY", "UPLOAD_LIMIT_SIGNAL", "WINDOW_STAGE_PENDING", "GPT_INSPECTION_UNAVAILABLE", "WEB_RESPONSE_IN_FLIGHT", "IMAGE_COUNT_UNCERTAIN", "IMAGE_DRAFT_REJECTED", "PLAN_PARSE_FAILED", "PLAN_NOT_READY", "PLAN_NOT_COMPLETE", "GENERATION_LIMIT_SIGNAL", "SCRIPT_GENERATED_OUTPUT", "COPY_REQUIRED", "WORKFLOW_STEP_TIMEOUT", "WORKFLOW_TASK_TIMEOUT"].includes(code)) return null;
  return task;
}

function currentGptQueueIntegrityMessage() {
  const task = gptTestQueue[gptTestQueueIndex];
  const taskMessage = String(task?._error || "").trim();
  if (taskMessage && /当前对话仍停在|已阻止上传下一套|未闭环作品|下载归档|输入框附件需要先清理|无法确认当前 GPT 对话状态/i.test(taskMessage)) {
    return taskMessage;
  }
  const blocked = currentGptQueueIntegrityBlock();
  if (!blocked) return "";
  return String(blocked._error || "当前作品仍未完成安全归档，请先恢复当前作品").trim();
}

async function recoverContinuousPlanFailure(task, result = {}, accountId = "account-1") {
  const errorCode = String(result?.errorCode || task?._errorCode || "");
  if (!["PLAN_NOT_READY", "PLAN_NOT_COMPLETE"].includes(errorCode)) return false;
  if (!isContinuousGptMode() || !isContinuousGptProductionArmed()) return false;
  if (gptWindowIsUserStopped(accountId) || gptWindowIsUserPaused(accountId)) return false;

  const previousRequestId = String(task.requestId || "");
  const freshRetryCount = Math.max(0, Number(task._planFreshRetryCount || 0)) + 1;
  task._planFreshRetryCount = freshRetryCount;
  task.requestId = `gpt-plan-recovery-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
  task.retryOf = previousRequestId;
  task.retryFromStage = "";
  task.retryFromPercent = 0;
  task.forceUpload = true;
  task._submittedToGpt = false;
  task._status = "queued";
  task._stage = "等待重新上传";
  task._percent = 0;
  task._error = "";
  task._errorCode = "";
  delete task.workflow;

  if (freshRetryCount <= 2) {
    persistGptQueue();
    updateGptTestQueueStatus(`当前素材没有收到完整计划；正在清理网页并重新上传（${freshRetryCount}/2），不会跳到下一套。`);
    await refreshGptAfterProduction(accountId, "plan-response-fresh-retry").catch(() => {});
    await new Promise((resolve) => setTimeout(resolve, 10_000));
    return true;
  }

  task._planFreshRetryCount = 0;
  task._planRecoveryDeferrals = Math.max(0, Number(task._planRecoveryDeferrals || 0)) + 1;
  const currentIndex = gptTestQueue.indexOf(task);
  if (currentIndex >= 0) {
    const [deferredTask] = gptTestQueue.splice(currentIndex, 1);
    const deferDistance = Math.min(20, 3 + Number(task._planRecoveryDeferrals || 0));
    const deferIndex = Math.min(gptTestQueue.length, currentIndex + deferDistance);
    gptTestQueue.splice(deferIndex, 0, deferredTask);
  }
  persistGptQueue();
  updateGptTestQueueStatus("当前素材连续无完整计划，已保留并顺延重试；现在继续下一套，不暂停整条生产线。");
  await refreshGptAfterProduction(accountId, "plan-response-deferred").catch(() => {});
  await new Promise((resolve) => setTimeout(resolve, 10_000));
  return true;
}

// Transport/readiness failures get a bounded retry budget. Other workflow
// failures are still recoverable: the automatic policy retries the checkpoint
// a few times, then defers or quarantines only that task so the account window
// keeps moving. Quota and authentication signals remain separate human/system
// boundaries and never masquerade as ordinary infinite retries.
function isTransientGptWindowFailure(errorOrResult = {}) {
  const code = String(errorOrResult?.errorCode || errorOrResult?.code || "");
  const reason = String(errorOrResult?.reason || "");
  const message = String(errorOrResult?.message || errorOrResult?.detail || errorOrResult?.error || errorOrResult || "");
  if (!code && !message) return false;
  if ([
    "LOCAL_BRIDGE_FETCH_FAILED",
    "ATTACHMENT_UPLOAD_NOT_READY",
    "WINDOW_STAGE_PENDING",
    "WEB_RESPONSE_IN_FLIGHT",
    "GPT_PAGE_NOT_READY",
    "GPT_PAGE_LOAD_TIMEOUT",
    "EXTENSION_NOT_READY",
    "COMPOSER_NOT_READY",
    "GPT_INSPECTION_UNAVAILABLE",
    "GPT_REQUEST_DISPATCH_FAILED",
    "GPT_REQUEST_IN_FLIGHT",
    "IMAGE_GENERATION_UNAVAILABLE",
    "GPT_PAGE_RELOADED",
    "GPT_TASK_RESULT_TIMEOUT",
    "GPT_NAVIGATION_FAILED",
    "GPT_AUTOMATIC_RECOVERY_ABORTED",
    "GPT_ORIGINAL_CONVERSATION_BOUNDARY_PENDING",
    "GPT_WORKFLOW_POST_SUBMIT_STALLED",
    "IMAGE_RECOVERY_BOUNDARY_MISSING",
    "IMAGE_COUNT_UNCERTAIN",
    "WORKFLOW_STEP_TIMEOUT",
    "WORKFLOW_TASK_TIMEOUT",
    // These are safe-to-retry conversation-boundary failures. They do not
    // authorize a new image request; the worker resumes the same checkpoint
    // and its finite recovery budget eventually defers/quarantines the task.
    "ARCHIVED_BOUNDARY_RELEASE_PENDING",
    "CONVERSATION_BOUNDARY_PENDING",
    "archive-recovery-failed",
    "conversation-owner-mismatch",
    "copy-boundary-material-mismatch"
  ].includes(code) || [
    "archived-boundary-release-pending",
    "archive-recovery-failed",
    "conversation-owner-mismatch",
    "copy-boundary-material-mismatch"
  ].includes(reason)) return true;
  if (/(?:网页尚未就绪|网页状态没有完成确认|无法确认当前 GPT 对话状态|先刷新当前 GPT 窗口|本地工作台连接失败|连接失败|网络错误|Failed to fetch|fetch failed|暂时不可用|正在准备 GPT 网页|页面仍在加载|响应仍在生成|工作台桥接|扩展尚未就绪|GPT 网页刷新失败|附件助手未确认接收请求|GPT 附件助手响应超时|当前作品缺少生图回复边界证据|当前作品图片边界无法确认|图片数量无法确认|归档边界.*释放|归档恢复失败|对话归属.*不匹配|copy-boundary-material-mismatch)/i.test(message)) return true;
  return false;
}

// A durable checkpoint can occasionally lose its live conversation owner after
// a renderer/app restart even though the page is no longer generating. This is
// different from a real quota, login, CAPTCHA, or user-hold boundary: keep the
// source material and failure evidence, isolate only this work, and let the
// continuous window move on instead of freezing the whole account queue.
function isAutoIsolatableGptWorkflowFailure(errorOrResult = {}) {
  const code = String(errorOrResult?.errorCode || errorOrResult?.code || "");
  if (["IMAGE_COUNT_UNCERTAIN"].includes(code) || code === "IMAGE_GENERATION_UNAVAILABLE") return true;
  const message = String(errorOrResult?.error || errorOrResult?.detail || "");
  return /当前作品图片边界无法确认|图片数量无法确认/.test(message)
    && !/当前作品缺少生图回复边界证据/.test(message);
}

async function probeStuckGptWindowBoundary(account, state) {
  const key = String(account?.id || "").trim();
  if (!key || !state?.autoRunning || !gptWindowWorkerPromises.has(key)) return false;
  if (gptWindowStuckBoundaryProbePromises.has(key)) return gptWindowStuckBoundaryProbePromises.get(key);
  const task = Array.isArray(state.queue) ? state.queue[Number(state.queueIndex || 0)] : null;
  if (!task || ["completed", "skipped"].includes(String(task._status || ""))) return false;
  const now = Date.now();
  const lastProbeAt = Number(gptWindowStuckBoundaryProbeAt.get(key) || 0);
  if (now - lastProbeAt < 15_000) return false;
  const promise = (async () => {
    const runtime = readGptWindowRuntime(key);
    const inspection = await boundedGptBrowserCall(
      window.gptWorkbench?.inspectStatus?.(key),
      GPT_INSPECT_CALL_TIMEOUT_MS
    ).catch(() => null);
    if (!inspection) return false;
    const taskMatches = gptConversationMaterialMatch({
      ...task,
      sourceMaterialPath: task.sourceMaterialPath || task.materialPath,
      materialName: task.materialName || task.name
    }, inspection);
    const shouldInterrupt = window.GptWindowWorkerState?.shouldInterruptStuckWorker?.({
      workerRunning: state.autoRunning === true,
      liveWorker: gptWindowWorkerPromises.has(key),
      taskDispatching: task._dispatchingToGpt === true,
      inspection,
      taskMatches,
      now,
      lastProbeAt,
      lastProgressAt: runtime.lastProgressAt
    });
    if (!shouldInterrupt) return false;
    gptWindowStuckBoundaryProbeAt.set(key, now);
    const requestId = String(readGptWindowRuntime(key)?.currentTaskId || task.requestId || "");
    writeGptWindowRuntime(key, {
      status: "probing",
      currentTaskId: requestId,
      currentStage: inspection.stage === "plan-ready" ? "已识别待确认边界，正在释放旧桥接锁" : "已识别归档边界，正在释放旧桥接锁",
      lastError: ""
    });
    const stopped = await Promise.resolve(
      window.gptWorkbench?.stopCurrentTask?.(key, requestId, {
        userInitiated: false,
        reason: "boundary-recovery"
      })
    ).catch(() => null);
    if (stopped?.ok || stopped?.pendingAborted) {
      updateGptWindowUi(key, () => updateGptTestQueueStatus(
        `${account.name} 已从网页真实边界释放旧执行锁，正在自动对账续接；不重复上传当前素材`
      ));
      return true;
    }
    writeGptWindowRuntime(key, {
      status: "probing",
      currentStage: "网页边界已识别，等待旧桥接退出",
      lastError: String(stopped?.error || stopped?.detail || "旧桥接尚未确认停止")
    });
    return false;
  })();
  gptWindowStuckBoundaryProbePromises.set(key, promise);
  try {
    return await promise;
  } finally {
    gptWindowStuckBoundaryProbePromises.delete(key);
  }
}

function restoreGptQueue() {
  try {
    const saved = JSON.parse(localStorage.getItem(GPT_QUEUE_STORAGE_KEY) || "null");
    if (!saved || !Array.isArray(saved.tasks) || !saved.tasks.length) return;
    const originalPrompts = saved.tasks.map((task) => String(task?.prompt || ""));
    const originalExpectedImages = saved.tasks.map((task) => Number(task?.expectedImages || 0));
    saved.tasks = saved.tasks.map((task) => normalizeQueuedGptTaskPrompt(task));
    const migratedQueue = saved.tasks.some((task, index) => (
      String(task?.prompt || "") !== originalPrompts[index]
      || Number(task?.expectedImages || 0) !== originalExpectedImages[index]
    ));
    if (migratedQueue) {
      localStorage.setItem(GPT_QUEUE_STORAGE_KEY, JSON.stringify(saved));
    }
    // 0.14.5 could stop after the first image while the same assistant
    // response was still adding more images. Rewind only that exact legacy
    // signature so 0.14.6 can recover the already-finished reply instead of
    // uploading the source post or sending `1` again.
    const legacyFalseStopIndex = saved.tasks.findIndex((task, index) => (
      index < Number(saved.index || 0)
      && task?._quotaSkipped === true
      && Number(task?.expectedImages || 0) >= 4
      && /本轮只检测到\s*1\s*张/.test(String(task?._error || ""))
      && /等待图片/.test(String(task?._stage || ""))
    ));
    if (legacyFalseStopIndex >= 0) {
      const task = saved.tasks[legacyFalseStopIndex];
      task._status = "paused";
      task._errorCode = "LEGACY_IMAGE_COUNT_RECHECK";
      task._error = "旧版图片计数可能过早收口；将从当前 GPT 回复重新核对，不重复上传或发送 1";
      task.retryFromStage = "等待图片";
      task.retryFromPercent = Number(task._percent || 64);
      task._quotaSkipped = false;
      delete task._endedAt;
      delete task._result;
      saved.index = legacyFalseStopIndex;
      saved.paused = true;
      localStorage.setItem(GPT_QUEUE_STORAGE_KEY, JSON.stringify(saved));
    }
    gptTestQueue = saved.tasks.map((task) => ({
      ...task,
      autoOptions: task.autoOptions && Array.isArray(task.autoOptions.accounts)
        ? {
            ...task.autoOptions,
            accounts: task.autoOptions.accounts.map((account, index) => ({
              ...account,
              name: /^浏览器\s*\d+$/i.test(String(account?.name || "")) ? `账号窗口 ${index + 1}` : account?.name
            }))
          }
        : task.autoOptions
    }));
    gptTestQueueIndex = Math.max(0, Math.min(saved.tasks.length, Number(saved.index || 0)));
    const hadInterruptedTask = gptTestQueue.some((task) => task._status === "running");
    gptTestQueue.forEach((task) => {
      if (task._status === "running") {
        task._status = "paused";
        task._errorCode ||= "RESTART_INTERRUPTED";
        task._error ||= "工作台重启中断了当前执行；已保留网页和队列，将先检查现有阶段再继续";
      }
    });
    const restoredCurrentTask = gptTestQueue[gptTestQueueIndex];
    const hadPausedCurrentTask = ["paused", "failed"].includes(String(restoredCurrentTask?._status || ""));
    // A persisted pause is an explicit safety boundary. Do not let the
    // continuous scheduler reinterpret it as permission to upload the next
    // post during startup. A renderer that died mid-task is also paused until
    // the operator resumes from its checkpoint, so the web page can never
    // silently race ahead after an update/reload.
    gptQueuePaused = Boolean(saved.paused || hadInterruptedTask || hadPausedCurrentTask);
    if (gptQueuePaused) {
      if (gptMultiRunState?.workerState) {
        const restoredWorkerState = Object.fromEntries(Object.entries(gptMultiRunState.workerState).map(([id, worker]) => [id, {
          ...worker,
          status: worker?.status === "running" && !worker?.currentTask ? "paused" : worker?.status
        }]));
        persistGptMultiRun({ workerState: restoredWorkerState });
      }
      // Rehydrate the retry affordance as well as the queue itself.  After a
      // restart the old code restored the paused task but left
      // gptLastFailedTask null, so the visible “重试当前任务” button had no
      // effect until another failure happened in this renderer session.
      const currentTask = gptTestQueue[gptTestQueueIndex];
      if (currentTask && currentTask._status !== "completed" && currentTask._status !== "skipped") {
        gptLastFailedTask = currentTask;
        gptLastFailedStage = String(currentTask._stage || "");
        gptLastFailedPercent = Number(currentTask._percent || 0);
      }
      showWorkbenchAssistantBubble(`发现上次未完成队列：从第 ${gptTestQueueIndex + 1}/${gptTestQueue.length} 套继续。`, { duration: 0 });
      if (gptMultiRunState?.status === "running") {
        persistGptMultiRun({
          status: "paused-restart",
          pending: gptTestQueue.slice(gptTestQueueIndex).filter((task) => !["completed", "skipped"].includes(task._status)).map((task) => task.requestId)
        });
      }
    }
    // A restored migration must reach the server mirror immediately. Without
    // this write, the browser had the corrected queue while the server still
    // advertised the older over-limit tasks until another user action.
    if (migratedQueue || hadInterruptedTask || hadPausedCurrentTask !== Boolean(saved.paused)) persistGptQueue();
  } catch {
    localStorage.removeItem(GPT_QUEUE_STORAGE_KEY);
  }
}

function refreshGptUiAfterRuntimeRestore() {
  // Dashboard rendering happens before the durable runtime reconciliation.
  // Refresh every status consumer once the server-backed queue has been
  // restored so the production page, settings summary and cat all describe
  // the same checkpoint instead of keeping the earlier empty-queue snapshot.
  renderGptAccountTabs();
  renderGptBrowserManager();
  updateGptTestQueueStatus();
}

function loadGptAccounts() {
  try {
    const stored = JSON.parse(localStorage.getItem(GPT_ACCOUNTS_STORAGE_KEY) || "[]");
    const accounts = Array.isArray(stored)
      ? stored.filter((item) => item && /^[a-z0-9_-]+$/i.test(String(item.id || ""))).slice(0, 8)
      : [];
    if (accounts.length) {
      const isolatedAccounts = filterContentInstanceAccounts(accounts.map((item, index) => ({
        id: String(item.id),
        name: (/^浏览器\s*\d+$/i.test(String(item.name || "")) ? `账号窗口 ${index + 1}` : String(item.name || `账号窗口 ${index + 1}`)).slice(0, 24),
        quotaGroup: String(item.quotaGroup || item.id),
        hidden: Boolean(item.hidden),
        disabled: Boolean(item.disabled),
        lastUrl: String(item.lastUrl || ""),
        lastBrowserUrl: String(item.lastBrowserUrl || item.lastUrl || ""),
        lastConversationUrl: String(item.lastConversationUrl || ""),
        lastInvalidConversationUrl: String(item.lastInvalidConversationUrl || ""),
        lastOpenedAt: String(item.lastOpenedAt || ""),
        createdAt: String(item.createdAt || ""),
        // Per-window production mode: each account window remembers its own
        // mode (manual / automatic / single / rotate).  Undefined falls back
        // to the global gptAutoSettings.mode for backward compatibility.
        mode: item.mode ? normalizeGptProductionMode(item.mode) : undefined,
        workflowVariant: String(item.workflowVariant || "legacy-v1"),
        workflowVariantVersion: String(item.workflowVariantVersion || "1"),
        experimentId: String(item.experimentId || ""),
        assignmentAt: String(item.assignmentAt || ""),
        sessionPolicy: String(item.sessionPolicy || "reuse-conversation"),
        selectedTemplateId: String(item.selectedTemplateId || ""),
        templateConversationUrl: String(item.templateConversationUrl || ""),
        workflowProfileId: String(item.workflowProfileId || "")
      })));
      if (isolatedAccounts.length) return isolatedAccounts;
    }
  } catch {
    // Fall back to the first isolated account.
  }
  const assigned = contentInstanceAccountIds();
  const fallbackIds = assigned ? [...assigned] : ["account-1"];
  return fallbackIds.map((fallbackId) => ({
    id: fallbackId,
    name: `账号窗口 ${fallbackId.replace("account-", "")}`,
    quotaGroup: fallbackId,
    hidden: false
  }));
}

function contentInstanceId() {
  const appInfoId = String(dashboard?.appInfo?.instanceId || "").trim().toUpperCase();
  if (CONTENT_INSTANCE_ACCOUNT_BY_ID[appInfoId]) return appInfoId;
  const runtimeRoot = String(dashboard?.appInfo?.runtimeRoot || "");
  const match = runtimeRoot.match(/[\\/]内容生产App[\\/]instance-([A-D])(?:[\\/]|$)/i);
  return match?.[1]?.toUpperCase()
    || CONTENT_INSTANCE_ID_BY_PORT[String(window.location?.port || "")]
    || "";
}

function contentInstanceAccountIds() {
  const assigned = Array.isArray(dashboard?.appInfo?.assignedAccountIds)
    ? new Set(dashboard.appInfo.assignedAccountIds
      .map((accountId) => String(accountId || "").trim().toLowerCase())
      .filter((accountId) => Object.values(CONTENT_INSTANCE_ACCOUNT_BY_ID).includes(accountId)))
    : new Set();
  if (assigned.size) return assigned;
  const instance = contentInstanceId();
  const accountId = CONTENT_INSTANCE_ACCOUNT_BY_ID[instance];
  return accountId ? new Set([accountId]) : null;
}

function contentInstanceDisplayLabel() {
  const appInfo = dashboard?.appInfo || {};
  const instance = contentInstanceId();
  const instanceLabel = String(appInfo.instanceLabel || (instance ? `实例 ${instance}` : "当前实例")).trim();
  const accountIds = contentInstanceAccountIds();
  return accountIds?.size ? `${instanceLabel} · ${[...accountIds].join("、")}` : instanceLabel;
}

function filterContentInstanceAccounts(accounts = []) {
  const assigned = contentInstanceAccountIds();
  if (!assigned) return accounts;
  return accounts.filter((account) => assigned.has(String(account?.id || "")));
}

function filterContentInstanceRuntime(runtime = {}) {
  const assigned = contentInstanceAccountIds();
  if (!assigned || !runtime || typeof runtime !== "object") return runtime;
  return Object.fromEntries(Object.entries(runtime)
    .filter(([accountId]) => assigned.has(String(accountId || ""))));
}

function saveGptAccounts() {
  localStorage.setItem(GPT_ACCOUNTS_STORAGE_KEY, JSON.stringify(gptAccounts));
}

async function hydrateGptBrowserProfiles() {
  if (!window.gptWorkbench?.profiles) return;
  try {
    // A-D instances share source code but never share the account selector.
    // Old renderer localStorage can contain profiles from the other instance;
    // filter it before the sync loop so it cannot recreate a foreign native
    // profile or overwrite the other instance's account settings.
    gptAccounts = filterContentInstanceAccounts(gptAccounts);
    gptWindowRuntime = filterContentInstanceRuntime(gptWindowRuntime);
    let state = await window.gptWorkbench.profiles();
    const assignedProfiles = filterContentInstanceAccounts(state.profiles || []);
    const known = new Set(assignedProfiles.map((profile) => profile.id));
    for (const local of gptAccounts) {
      if (known.has(local.id)) continue;
      state = await window.gptWorkbench.saveProfile({
        ...local,
        name: local.name || `账号窗口 ${state.profiles.length + 1}`,
        active: false
      });
      known.add(local.id);
    }
    // Migrate the persisted native profile labels as well as the local UI
    // copy.  Earlier builds stored “浏览器 N”; leaving that value in the
    // Electron profile file made the next restart regress the account
    // language even though the current tab already showed “账号窗口 N”.
    const nativeProfiles = filterContentInstanceAccounts(state.profiles || []);
    for (let index = 0; index < nativeProfiles.length; index += 1) {
      const profile = nativeProfiles[index];
      if (!/^浏览器\s*\d+$/i.test(String(profile.name || ""))) continue;
      state = await window.gptWorkbench.saveProfile({
        ...profile,
        name: `账号窗口 ${index + 1}`,
        active: profile.id === state.activeId
      });
    }
    const persistedAccountSettings = dashboard?.workspaceSettings?.pageSettings?.gptAuto?.accounts;
    if (Array.isArray(persistedAccountSettings)) {
      const quotaDefaults = dashboard?.workspaceSettings?.pageSettings?.gptAuto || {};
      const assignedSettings = filterContentInstanceAccounts(persistedAccountSettings);
      const reconciledSettings = TBGptAccountRotation.reconcileAccountQuotaSettings({
        profiles: nativeProfiles,
        settings: assignedSettings,
        defaults: {
          uploadLimit: quotaDefaults.uploadLimit || 80,
          generationLimit: quotaDefaults.generationLimit || 45,
          windowHours: quotaDefaults.windowHours || 3
        }
      });
      let settingsChanged = JSON.stringify(reconciledSettings) !== JSON.stringify(assignedSettings);
      const migrateAccountSafety = localStorage.getItem(GPT_ACCOUNT_GENERATION_SAFETY_MIGRATION_KEY) !== "done";
      const normalizedSettings = reconciledSettings.map((account, index) => {
        if (!account) return account;
        const nameChanged = /^浏览器\s*\d+$/i.test(String(account.name || ""));
        const safetyChanged = migrateAccountSafety && Number(account.generationLimit) === 50;
        if (!nameChanged && !safetyChanged) return account;
        settingsChanged = true;
        return {
          ...account,
          ...(nameChanged ? { name: `账号窗口 ${index + 1}` } : {}),
          ...(safetyChanged ? { generationLimit: 45 } : {})
        };
      });
      // Keep the live renderer settings in sync with profiles discovered after
      // startup. The server-backed dashboard object is not the same object as
      // gptAutoSettings, so without this assignment a newly added account only
      // appeared in its quota panel after a full page reload.
      gptAutoSettings.accounts = normalizedSettings;
      localStorage.setItem(GPT_AUTO_SETTINGS_STORAGE_KEY, JSON.stringify(gptAutoSettings));
      if (settingsChanged && dashboard?.workspaceSettings?.pageSettings?.gptAuto) {
        dashboard.workspaceSettings.pageSettings.gptAuto.accounts = normalizedSettings;
        api("/api/page-settings", {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ gptAuto: { accounts: normalizedSettings } })
        }).catch(() => {});
      }
      if (migrateAccountSafety) localStorage.setItem(GPT_ACCOUNT_GENERATION_SAFETY_MIGRATION_KEY, "done");
    }
    // Preserve per-window mode from localStorage when syncing Electron
    // profiles.  The mode is a UI-only field; the native profile store does
    // not carry it, so we merge it back from the previously saved accounts.
    const previousModes = new Map(gptAccounts.map((item) => [item.id, item.mode]));
    const previousDisabled = new Map(gptAccounts.map((item) => [item.id, Boolean(item.disabled)]));
    for (const profile of nativeProfiles) {
      const id = String(profile.id || "");
      if (Object.prototype.hasOwnProperty.call(profile, "disabled") || !previousDisabled.has(id)) continue;
      state = await window.gptWorkbench.saveProfile({
        ...profile,
        disabled: previousDisabled.get(id),
        active: false
      });
    }
    gptAccounts = nativeProfiles.map((profile, index) => ({
      id: String(profile.id),
      name: (/^浏览器\s*\d+$/i.test(String(profile.name || "")) ? `账号窗口 ${index + 1}` : String(profile.name || `账号窗口 ${index + 1}`)),
      quotaGroup: String(profile.quotaGroup || profile.id),
      hidden: Boolean(profile.hidden),
      disabled: Object.prototype.hasOwnProperty.call(profile, "disabled")
        ? Boolean(profile.disabled)
        : Boolean(previousDisabled.get(String(profile.id))),
      lastUrl: String(profile.lastUrl || ""),
      lastBrowserUrl: String(profile.lastBrowserUrl || profile.lastUrl || ""),
      lastConversationUrl: String(profile.lastConversationUrl || ""),
      lastInvalidConversationUrl: String(profile.lastInvalidConversationUrl || ""),
      lastOpenedAt: String(profile.lastOpenedAt || ""),
      createdAt: String(profile.createdAt || ""),
      mode: previousModes.has(String(profile.id)) ? previousModes.get(String(profile.id)) : undefined,
      workflowVariant: String(profile.workflowVariant || "legacy-v1"),
      workflowVariantVersion: String(profile.workflowVariantVersion || "1"),
      experimentId: String(profile.experimentId || ""),
      assignmentAt: String(profile.assignmentAt || ""),
      sessionPolicy: String(profile.sessionPolicy || (profile.workflowVariant === "fresh-session-fixed-template" ? "fresh-session" : "reuse-conversation")),
      selectedTemplateId: String(profile.selectedTemplateId || ""),
      templateConversationUrl: String(profile.templateConversationUrl || ""),
      workflowProfileId: String(profile.workflowProfileId || "")
    }));
    activeGptAccountId = gptAccounts.some((profile) => profile.id === state.activeId && !profile.hidden)
      ? state.activeId
      : gptAccounts.find((profile) => !profile.hidden)?.id || gptAccounts[0]?.id || "account-1";
    // The active browser profile owns its production mode. Restore that mode
    // during startup hydration as well as on manual tab switches; otherwise
    // the UI can reopen in the last global mode and immediately snap back
    // after the first account interaction.
    const restoredAccount = gptAccounts.find((profile) => profile.id === activeGptAccountId);
    const restoredMode = restoredAccount?.mode ? normalizeGptProductionMode(restoredAccount.mode) : String();
    if (restoredMode && restoredMode !== normalizeGptProductionMode(gptAutoSettings.mode)) {
      gptAutoSettings.mode = restoredMode;
      applyGptModeProfile(restoredMode);
      localStorage.setItem(GPT_AUTO_SETTINGS_STORAGE_KEY, JSON.stringify(gptAutoSettings));
      renderGptAutoSettings();
    }
    saveGptAccounts();
    renderGptAccountTabs();
    renderGptBrowserManager();
    // The first dashboard render can happen before native browser profiles
    // finish hydrating, so it may briefly attach the fallback account window.
    // Once the persisted activeId/order is authoritative, reattach the native
    // view to that account instead of leaving the page showing A while the tab
    // state says B. Await an in-flight first paint so the two native views do
    // not race for the same compositor slot.
    if ($("#gptProductionTestView")?.classList.contains("active")) {
      if (gptShowInFlight) await gptShowInFlight.catch(() => {});
      gptLastShowSignature = "";
      await showEmbeddedGptView().catch(() => {});
    }
  } catch (error) {
    console.warn("账号窗口档案读取失败，暂用本地标签", error);
  }
}

function loadGptAutoSettings() {
  const defaultDownloadRoot = "D:\\Download";
  const defaultProductRoot = "D:\\AICode\\项目推进\\projects\\江湖有旅人\\主项目\\成品库（GPT+本地脚本制作）";
  const normalizeProductionPath = (value, fallback) => {
    const path = String(value || "").trim();
    return /(?:^|[\\/])(?:_测试验收|验收)(?:[\\/]|$)/i.test(path) ? fallback : (path || fallback);
  };
  const defaults = {
    mode: "single",
    autoConfirm: true,
    autoCopy: true,
    autoPackage: true,
    pauseOnFailure: false,
    autoArchive: true,
    quotaReminderEnabled: true,
    minDelaySeconds: 25,
    maxDelaySeconds: 55,
    taskTimeoutMinutes: 20,
    workflowAttentionMinutes: 20,
    accountTaskLimit: 8,
    parallelWorkers: 3,
    maximumWorkers: 5,
    // Empty means all visible browser profiles. Set this to a list to run a
    // deliberate two-account/three-account production without touching a
    // blank or untrained profile.
    multiAccountIds: [],
    uploadLimit: 80,
    generationLimit: 45,
    windowHours: 3,
    confirmText: "1",
    copyPrompt: GPT_PUBLISH_COPY_PROMPT,
    minimumImageCount: 4,
    idleUnloadMinutes: 30,
    downloadRoot: defaultDownloadRoot,
    productRoot: defaultProductRoot,
    promptLibraryEnabled: true,
    messageDownloadsEnabled: true,
    scheduledEnabled: false,
    scheduledTime: "09:30",
    scheduledJitterMinutes: 10,
    schedulePlan: "09:30,8",
    launchAtLogin: true,
    continuousAutoStart: true,
    singleQuotaAutoSwitch: false,
    continuousWorkHoursEnabled: true,
    continuousWorkStart: "08:00",
    continuousWorkEnd: "02:00",
    masterPromptRules: "",
    extraPromptRules: ""
  };
  try {
    const loaded = {
      ...defaults,
      ...JSON.parse(localStorage.getItem(GPT_AUTO_SETTINGS_STORAGE_KEY) || "{}"),
      // 0.14.2: a failed material is recorded and skipped. It must never hold
      // the remaining production queue hostage.
      pauseOnFailure: false
    };
    if (Array.isArray(loaded.accounts)) {
      loaded.accounts = loaded.accounts.map((account, index) => ({
        ...account,
        name: /^浏览器\s*\d+$/i.test(String(account?.name || "")) ? `账号窗口 ${index + 1}` : account?.name
      }));
    }
    if (localStorage.getItem(GPT_GENERATION_SAFETY_MIGRATION_KEY) !== "done") {
      if (Number(loaded.generationLimit) === 50) loaded.generationLimit = 45;
      localStorage.setItem(GPT_AUTO_SETTINGS_STORAGE_KEY, JSON.stringify(loaded));
      localStorage.setItem(GPT_GENERATION_SAFETY_MIGRATION_KEY, "done");
    }
    loaded.mode = normalizeGptProductionMode(loaded.mode);
    loaded.downloadRoot = normalizeProductionPath(loaded.downloadRoot, defaultDownloadRoot);
    loaded.productRoot = normalizeProductionPath(loaded.productRoot, defaultProductRoot);
    // Normalize workflowSteps to ensure all critical steps are present.
    // If the stored workflowSteps is empty or missing steps (e.g., from a
    // partially-saved config), fall back to the active profile's steps or
    // the full default workflow.
    const profileKey = normalizeGptProductionMode(loaded.mode);
    const profile = gptModeProfiles?.[profileKey] || gptModeProfiles?.manual;
    const profileSteps = normalizeGptWorkflowSteps(profile?.steps);
    const storedSteps = normalizeGptWorkflowSteps(loaded.workflowSteps);
    // Use stored steps only if they have all critical actions; otherwise use profile steps
    const defaultActions = new Set(defaultGptWorkflowSteps().map((s) => s.action));
    const storedHasAll = [...defaultActions].every((a) => storedSteps.some((s) => s.action === a));
    loaded.workflowSteps = storedHasAll ? storedSteps : profileSteps;
    return loaded;
  } catch {
    return defaults;
  }
}

