        taskError.code = String(result?.errorCode || "");
        taskError.recoveryReason = String(result?.recoveryReason || "");
          const boundaryConflict = ["COMPOSER_ATTACHMENTS_PENDING", "COMPOSER_DRAFT_PENDING", "COMPOSER_DRAFT_NOT_SET", "COMPOSER_ATTACHMENT_CONFLICT", "LOCAL_BRIDGE_FETCH_FAILED", "ATTACHMENT_UPLOAD_NOT_READY", "MIXED_POST_ATTACHMENTS", "MATERIAL_ROOT_MISSING", "IMAGE_COUNT_UNCERTAIN", "IMAGE_DRAFT_REJECTED", "PLAN_PARSE_FAILED", "PLAN_NOT_READY", "PLAN_NOT_COMPLETE", "WINDOW_STAGE_PENDING", "WEB_RESPONSE_IN_FLIGHT", "GENERATION_LIMIT_SIGNAL", "SCRIPT_GENERATED_OUTPUT", "COPY_REQUIRED", "WORKFLOW_STEP_TIMEOUT", "WORKFLOW_TASK_TIMEOUT"].includes(String(result?.errorCode || ""))
