  const inspection = await boundedGptBrowserCall(window.gptWorkbench.inspectStatus(key), GPT_INSPECT_CALL_TIMEOUT_MS).catch(() => null);
  // Startup can reach this point before the embedded GPT extension has
  // attached to the account page. An empty inspection is not proof that the
