      currentTask._percent = 3;
      currentTask._error = "检测到旧自动任务残留输入，已清理并准备上传当前作品";
      currentTask._errorCode = "STALE_COMPOSER_AUTO_RECOVERED";
      workerState.lastFailedTask = null;
      workerState.lastFailedStage = "";
      workerState.lastFailedPercent = 0;
      workerState.queuePaused = false;
      persistGptWindowWorkerState(key, workerState);
      writeGptWindowRuntime(key, {
        status: "probing",
        currentTaskId: currentTask.requestId || "",
        currentStage: "已清理旧输入，准备上传当前作品",
        currentPercent: 3,
        nextRetryAt: null,
        lastError: ""
      });
      updateGptWindowUi(key, () => updateGptTestQueueStatus(
        `${gptAccounts.find((account) => account.id === key)?.name || "当前账号窗口"} 已清理旧自动输入，继续当前队列；不会重复发送旧作品`
      ));
      return {
        ok: true,
        inspection,
        directUpload: true,
        clearedStaleComposer: true,
        ownerTask: currentTask,
        ownerIndex: queue.indexOf(currentTask)
      };
