function beginDeviceNoteEdit(button) {
  const row = button.closest("[data-device-id]");
  const device = dashboard?.distribution?.devices?.find((item) => item.id === row?.dataset.deviceId);
  if (!device || row.querySelector(".device-note-input")) return;
  const input = document.createElement("input");
  input.className = "device-note-input";
  input.value = preferredDeviceLabel(device);
  input.maxLength = 100;
  input.setAttribute("aria-label", "设备名称或编号");
  button.replaceWith(input);
  input.focus();
  input.select();
  let saved = false;
  const finish = async (cancel = false) => {
    if (saved) return;
    saved = true;
    if (!cancel) {
      try {
        await api("/api/devices/note", {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ id: device.id, note: input.value })
        });
        device.note = input.value.trim();
        device.noteIsCustom = true;
        toast("设备名称或编号已保存");
      } catch (error) {
        showSystemNotice("设备名称或编号没有保存", error.message, { tone: "danger" });
      }
    }
    renderDistribution();
  };
  input.addEventListener("keydown", (event) => {
    if (event.key === "Enter") finish();
    if (event.key === "Escape") finish(true);
  });
  input.addEventListener("blur", () => finish());
}

async function approveDeviceForAutomaticDistribution(deviceId, deviceModel = "") {
  const data = dashboard?.distribution || {};
  const device = DistributionUI.decorateDevices(
    data.devices || [],
    deviceCheckState.onlineDevices || [],
    data.approvedDeviceKeys || []
  ).find((item) => item.id === deviceId && item.online);
  if (!device) return showSystemNotice("设备当前未连接", "请在手机上打开接收端后再确认。");
  const confirmed = await openSystemDialog({
    eyebrow: "首次自动分发",
    title: "允许这台设备以后自动补作品？",
    description: "只需确认这一次。以后设备重新连接时，工作台会自动检测分类库存并按阈值补充。",
    details: [
      { label: "设备", value: preferredDeviceLabel(device) },
      { label: "型号", value: deviceModel || device.models?.[0] || device.model || "未报告" }
    ],
    warning: "设备离线、分类库存不明或没有合适作品包时，仍然不会误发。",
    cancelLabel: "暂不允许",
    confirmLabel: "确认，以后自动分发"
  });
  if (!confirmed) return;
  try {
    await api("/api/devices/approve", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        device: device.aliases?.[0] || device.liveName || device.displayName,
        model: deviceModel || device.models?.[0] || device.model || "",
        confirmed: true
      })
    });
    await loadDashboard(true);
    renderDistribution();
    toast("已允许自动分发，正在重新检查手机库存");
    await checkDistributionDevices({ silent: true, refreshInventory: false });
  } catch (error) {
    showSystemNotice("自动分发确认没有保存", error.message, { tone: "danger" });
  }
}

async function sendSelectedDistributionPackage() {
  const data = dashboard?.distribution || {};
  const collection = (data.collections || []).find((item) =>
    item.name === selectedDistributionCollectionName
  );
  const devices = DistributionUI.decorateDevices(
    data.devices || [],
    deviceCheckState.onlineDevices || [],
    data.approvedDeviceKeys || []
  );
  const device = devices.find((item) => item.id === selectedDistributionDeviceId && item.online);
  if (!collection) return showSystemNotice("还没有选择作品包", "请先在列表里选择要发送的作品包。");
  if (!device) return showSystemNotice("目标设备已经离线", "返回设备选择列表，选择一台当前在线设备。");
  const typeLabel = collection.type === "conversion" ? "精准流量" : "泛流量";
  const needsConfirmation = device.firstConfirmationRequired === true;
  const confirmed = !needsConfirmation || await openSystemDialog({
    eyebrow: "发送作品包",
    title: "确认发送到这台设备？",
    description: "确认后会立即开始发送，页面会持续显示百分比、当前阶段和最终结果。",
    details: [
      { label: "作品包", value: collection.name },
      { label: "目标设备", value: preferredDeviceLabel(device) },
      { label: "内容类型", value: typeLabel }
    ],
    warning: "发送完成并由手机确认接收后，作品文件夹会进入“已发送1次（微信公众号可发）”，等待公众号二次复用发布。",
    cancelLabel: "返回重选",
    confirmLabel: "确认发送"
  });
  if (!confirmed) {
    packageDevicePickerCollectionName = collection.name;
    renderDistribution();
    return;
  }
  await startDistributionTransfer({
    action: "device-restock",
    device: device.liveName || device.models?.[0] || device.aliases?.[0] || device.displayName,
    deviceLabel: preferredDeviceLabel(device),
    deviceModel: device.models?.[0] || device.model || "",
    approveDevice: device.firstConfirmationRequired === true,
    type: collection.type,
    collection: collection.name
  });
}

async function checkDistributionDevices(options = {}) {
  if (deviceScanRunning) return;
  deviceScanRunning = true;
  deviceCheckState = { ...deviceCheckState, scanning: true };
  if (dashboard?.distribution) renderDistribution();
  const refreshButton = $("#distributionRefreshBtn");
  if (refreshButton) {
    refreshButton.disabled = true;
    refreshButton.classList.add("is-refreshing");
    refreshButton.setAttribute("aria-label", "正在刷新设备状态");
  }
  if (!options.silent) toast("正在刷新设备与库存");
  try {
    const result = await api("/api/distribution/check", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        inventory: options.refreshInventory !== false,
        force: options.silent !== true
      })
    });
    deviceCheckState = {
      registered: Number.isFinite(result.registered) ? result.registered : DistributionUI.parseDeviceCheckOutput(result.output).registered,
      online: Number.isFinite(result.online) ? result.online : DistributionUI.parseDeviceCheckOutput(result.output).online,
      output: result.output || "",
      onlineDevices: Array.isArray(result.onlineDevices)
        ? result.onlineDevices
        : DistributionUI.parseDeviceStatusOutput(result.statusOutput),
      scanning: false
    };
    deviceScanStarted = true;
    if (options.refreshInventory !== false) await loadDashboard(true);
    renderDistribution();
    if ((result.automationTriggered || []).length) {
      const count = result.automationTriggered.reduce((sum, item) => sum + Number(item.count || 0), 0);
      toast(`已自动建立 ${count} 个作品集分发任务，可查看实时进度`);
      showWorkbenchAssistantBubble(`自动分发已开始：发现 ${result.automationTriggered.length} 台设备需要补充，共 ${count} 个作品集。`, {
        sourceView: "distributionView",
        notificationKey: `auto-distribution-started:${result.automationTriggered.map((item) => item.deviceId).join(",")}:${count}`,
        dedupeMs: 60_000,
        tone: "info"
      });
      ensureTransferPolling();
      await restoreTransferTasks();
    }
    if (!options.silent) {
      toast(deviceCheckState.online == null ? "刷新完成，请查看结果" : `已刷新：当前在线 ${deviceCheckState.online} 台`);
    }
  } catch (error) {
    deviceCheckState = { ...deviceCheckState, scanning: false };
    if (dashboard?.distribution) renderDistribution();
    const retryCount = Number(options.networkRetry || 0);
    const transientNetworkFailure = /网络请求失败（\/api\/distribution\/check）/.test(String(error?.message || ""));
    if (options.silent && transientNetworkFailure && retryCount < 2) {
      // Desktop maintenance can restart the local server for a few seconds.
      // Retry silently so a routine restart does not become a red console
      // warning or leave the device state permanently stale.
      window.setTimeout(() => {
        if (!deviceScanRunning) {
          checkDistributionDevices({ ...options, networkRetry: retryCount + 1 });
        }
      }, 800 * (retryCount + 1));
      return;
    }
    if (!options.silent) showSystemNotice("设备状态刷新失败", error.message, { tone: "danger" });
    else console.warn("设备自动扫描跳过（静默模式）:", error.message || error);
  } finally {
    deviceScanRunning = false;
    if (refreshButton) {
      refreshButton.disabled = false;
      refreshButton.classList.remove("is-refreshing");
      refreshButton.setAttribute("aria-label", "立即刷新设备与库存");
    }
  }
}

async function loadJuguang(force = false) {
  if (juguangData && !force) return renderJuguang();
  juguangData = await api("/api/juguang");
  renderJuguang();
}

function renderJuguang() {
  if (!juguangData) return;
  const counts = juguangData.counts || {};
  $("#juguangMode").textContent = `数据更新：${juguangData.updatedAt ? new Date(juguangData.updatedAt).toLocaleString("zh-CN") : "暂无"}`;
  $("#juguangApiStatus").textContent = juguangData.api?.configured ? "Marketing API 已配置" : "本地快照模式";
  $("#juguangApiMessage").textContent = juguangData.api?.message || "";
  $("#juguangLeadStatus").textContent = `${juguangData.leads?.total || 0} 条线索 · ${juguangData.leads?.attributed || 0} 条可归因`;
  $("#juguangStats").innerHTML = [["关键词", counts.all], ["蓝海词", counts.blueOcean], ["高点击词", counts.highClick], ["同行买词", counts.peerBuying], ["笔记样本", counts.notes]]
    .map(([label, value]) => `<article class="panel glass juguang-stat"><span>${label}</span><strong>${formatNumber(value)}</strong></article>`).join("");
  $("#juguangNextActions").innerHTML = (juguangData.nextActions || []).map((action) => `<li>${escapeHtml(action)}</li>`).join("");
  renderJuguangRecommendations();
}

function renderJuguangRecommendations() {
  if (!juguangData) return;
  const query = ($("#juguangKeywordSearch")?.value || "").trim().toLowerCase();
  const items = (juguangData.recommendations || []).filter((item) => !query || item.keyword.toLowerCase().includes(query) || item.reason.toLowerCase().includes(query));
  $("#juguangRecommendations").innerHTML = items.length ? items.map((item) => `
    <article class="juguang-row">
      <div><strong>${escapeHtml(item.keyword)}</strong><p>${escapeHtml(item.reason || "业务相关候选")}</p></div>
      <div class="juguang-metrics"><span>搜索 ${formatNumber(item.monthlySearch)}</span><span>竞争 ${escapeHtml(item.competition || "-")}</span><span>出价 ¥${Number(item.marketBid || 0).toFixed(2)}</span></div>
      <div><b>${escapeHtml(item.action)}</b><p>${escapeHtml(item.titlePattern)}</p></div>
      <button class="ghost-button juguang-copy" data-keyword="${escapeHtml(item.keyword)}">复制选题</button>
    </article>`).join("") : `<div class="summary-text">当前候选里没有匹配项。可先补采该地域/玩法词。</div>`;
  $$(".juguang-copy").forEach((button) => button.addEventListener("click", () => {
    copyText(`复刻选题：${button.dataset.keyword}。按“人数 + 玩法 + 预算/路线 + 避坑”生成团建笔记，并保留目标关键词。`, "选题指令已复制");
  }));
}

function conversionSopData() {
  return conversionData?.sop?.数据 || conversionData?.sop?.data || {};
}

function conversionRoles() {
  return conversionSopData()?.角色 || conversionSopData()?.roles || {};
}

function readableConversionValue(value, depth = 0) {
  if (value == null || value === "") return "";
  if (typeof value === "string" || typeof value === "number" || typeof value === "boolean") {
    return `<p>${escapeHtml(String(value))}</p>`;
  }
  if (Array.isArray(value)) {
    return `<ul>${value.map((item) => `<li>${typeof item === "object" ? readableConversionValue(item, depth + 1) : escapeHtml(String(item))}</li>`).join("")}</ul>`;
  }
  if (depth > 3) return `<p>${escapeHtml(JSON.stringify(value))}</p>`;
  return Object.entries(value).map(([key, item]) => `
    <section class="conversion-result-section">
      <strong>${escapeHtml(key)}</strong>
      ${readableConversionValue(item, depth + 1)}
    </section>`).join("");
}

function conversionResultEntry(value, aliases = []) {
  if (!value || typeof value !== "object" || Array.isArray(value)) return null;
  const wanted = aliases.map(alias => conversionNorm(alias));
  return Object.entries(value).find(([key]) => wanted.includes(conversionNorm(key))) || null;
}

function conversionResultPlainText(value) {
  if (value == null || value === "") return "";
  if (typeof value === "string" || typeof value === "number" || typeof value === "boolean") return String(value);
  if (Array.isArray(value)) return value.map(conversionResultPlainText).filter(Boolean).join("\n");
  return Object.entries(value).map(([key, item]) => `${key}：${conversionResultPlainText(item)}`).join("\n");
}

function renderConversionActionValue(value) {
  if (Array.isArray(value)) {
    return `<ul class="conversion-result-list">${value.map(item => `<li>${escapeHtml(conversionResultPlainText(item))}</li>`).join("")}</ul>`;
  }
  if (value && typeof value === "object") {
    return `<div class="conversion-result-facts">${Object.entries(value).map(([key, item]) => `
      <div><small>${escapeHtml(key)}</small><span>${escapeHtml(conversionResultPlainText(item))}</span></div>`).join("")}</div>`;
  }
  return `<p>${escapeHtml(conversionResultPlainText(value))}</p>`;
}

function renderConversionActionResult(value, kind = "search") {
  if (!value || typeof value !== "object" || Array.isArray(value)) return readableConversionValue(value);
  const primary = conversionResultEntry(value, kind === "proposal"
    ? ["策划建议", "核心思路", "给策划师的建议", "下一步"]
    : ["首选回复", "建议回复", "推荐回复", "回复", "话术"]);
  const state = conversionResultEntry(value, kind === "proposal"
    ? ["需求拆解", "需求分析"]
    : ["识别意图", "当前阶段", "客户状态分析"]);
  const next = conversionResultEntry(value, ["下一步", "后续动作", "行动建议"]);
  const missing = conversionResultEntry(value, ["还要确认", "缺失信息", "需要确认"]);
  const reminder = conversionResultEntry(value, ["提醒", "风险", "注意"]);
  const matched = kind === "proposal" ? conversionResultEntry(value, ["匹配方案", "推荐方案"]) : null;
  const primaryText = primary ? conversionResultPlainText(primary[1]) : "";
  const hasStructuredContent = primary || state || next || missing || reminder || matched;
  if (!hasStructuredContent) return readableConversionValue(value);
  return `
    <div class="conversion-action-result" data-result-kind="${escapeHtml(kind)}">
      ${primary ? `<article class="conversion-result-primary">
        <div class="conversion-result-primary-head"><span>${kind === "proposal" ? "给策划师的建议" : "建议直接回复"}</span><button class="conversion-btn primary" type="button" data-copy-conversion-result="${escapeHtml(primaryText)}">复制</button></div>
        ${renderConversionActionValue(primary[1])}
      </article>` : ""}
      <div class="conversion-result-action-grid">
        ${state ? `<article class="conversion-result-action-card"><span>${kind === "proposal" ? "需求已拆解" : "客户现在的状态"}</span>${renderConversionActionValue(state[1])}</article>` : ""}
        ${next ? `<article class="conversion-result-action-card next"><span>下一步只做这件事</span>${renderConversionActionValue(next[1])}</article>` : ""}
        ${missing ? `<article class="conversion-result-action-card"><span>还需要确认</span>${renderConversionActionValue(missing[1])}</article>` : ""}
      </div>
      ${matched ? `<section class="conversion-result-matches"><div class="conversion-result-subhead"><strong>推荐方案</strong><small>先看匹配理由，再打开方案源文件核对细节。</small></div>${renderConversionActionValue(matched[1])}</section>` : ""}
      ${reminder ? `<div class="conversion-result-reminder"><b>提醒：</b>${escapeHtml(conversionResultPlainText(reminder[1]))}</div>` : ""}
      <details class="conversion-result-details"><summary>查看完整分析</summary>${readableConversionValue(value)}</details>
    </div>`;
}

function conversionSearchSnapshot() {
  return conversionData?.search?.数据 || conversionData?.search?.data || {};
}

function conversionHistories() {
  const data = conversionSearchSnapshot();
  return Array.isArray(data.候选) ? data.候选 : Array.isArray(data.items) ? data.items : [];
}

function conversionPlans() {
  const data = conversionData?.plans?.数据 || conversionData?.plans?.data || {};
  return Array.isArray(data.方案) ? data.方案 : Array.isArray(data.plans) ? data.plans : [];
}

function conversionIndexSlot(kind) {
  return kind === "proposal" ? "plans" : "search";
}

function conversionIndexDeferred(kind) {
  const slot = conversionIndexSlot(kind);
  return conversionData?.[slot]?.延迟加载 === true;
}

async function loadConversionIndex(kind) {
  const slot = conversionIndexSlot(kind);
  if (!conversionIndexDeferred(kind)) return conversionData?.[slot];
  if (conversionIndexLoads[kind]) return conversionIndexLoads[kind];
  const endpoint = kind === "proposal" ? "/api/conversion/plan-index" : "/api/conversion/search-index";
  conversionIndexLoads[kind] = (async () => {
    try {
      const payload = await api(endpoint);
      if (payload?.成功 === false || payload?.ok === false) throw new Error(payload?.error || "资料加载失败");
      conversionData = { ...conversionData, [slot]: payload };
      conversionIndexErrors[kind] = "";
      return payload;
    } catch (error) {
      conversionIndexErrors[kind] = error.message;
      throw error;
    }
  })();
  return conversionIndexLoads[kind];
}

function conversionNorm(value) {
  return String(value || "").toLowerCase().replace(/\s+/g, "");
}

function conversionHistoryQuestion(item) {
  return item?.问题 || item?.客户问题 || item?.客户原话 || item?.question || item?.标题 || item?.用户 || item?.原文 || "";
}

function conversionHistoryAnswer(item) {
  const value = item?.回复 || item?.回答 || item?.answer || item?.建议回复 || item?.内容 || item?.历史回复 || item?.历史回复原话 || "";
  return Array.isArray(value) ? value.join("\n") : String(value || "");
}

function conversionHistoryText(item) {
  return [
    conversionHistoryQuestion(item),
    conversionHistoryAnswer(item),
    item?.身份,
    item?.角色,
    item?.来源,
    item?.source,
    item?.标签,
    item?.场景
  ].flat().filter(Boolean).join(" ");
}

function matchConversionHistories(query = "", role = conversionRole) {
  const q = conversionNorm(query);
  return conversionHistories()
    .map((item, index) => {
      const text = conversionNorm(conversionHistoryText(item));
      const roleHit = !role || text.includes(conversionNorm(role)) ? 8 : 0;
      const queryHit = q ? (text.includes(q) ? 30 : q.split(/[，,。！？\s]+/).filter(Boolean).reduce((sum, token) => sum + (text.includes(token) ? 6 : 0), 0)) : 10;
      return { item, index, score: roleHit + queryHit };
    })
    .filter(row => !q || row.score > 0)
    .sort((a, b) => b.score - a.score)
    .slice(0, 25)
    .map(row => row.item);
}

function renderConversionHistoryCards(rows = matchConversionHistories("", conversionRole)) {
  if (!rows.length) return '<div class="conversion-empty">没有匹配到历史回答，可以换一句客户原话再搜。</div>';
  return rows.map((item) => {
    const question = conversionHistoryQuestion(item) || "未命名客户问题";
    const answer = conversionHistoryAnswer(item) || "这条历史记录暂无可展示回复。";
    const tags = [item?.身份, item?.角色, item?.分桶, item?.环节, item?.来源, item?.source, item?.场景].filter(Boolean).slice(0, 4);
    const meta = [item?.时间, item?.日期, item?.文件, item?.会话, item?.回复人].flat().filter(Boolean).join(" · ");
    return `
      <article class="conversion-history-card">
        <div class="conversion-history-head">
          <div class="conversion-history-tags">${tags.map(tag => `<span>${escapeHtml(tag)}</span>`).join("")}</div>
          <button class="conversion-btn" type="button" data-copy-history="${escapeHtml(answer)}">复制</button>
        </div>
        <h3>${escapeHtml(question)}</h3>
        <p>${escapeHtml(answer)}</p>
        ${meta ? `<small>${escapeHtml(meta)}</small>` : ""}
      </article>`;
  }).join("");
}

function conversionSyncDate(value) {
  if (!value) return "暂无";
  const date = new Date(value);
  return Number.isNaN(date.getTime()) ? String(value) : date.toLocaleString("zh-CN", { hour12: false });
}

function renderConversionSyncPanel() {
  const sync = conversionData?.sync || {};
  const formal = sync.formal || {};
  const candidate = sync.candidate || {};
  const api = sync.api || {};
  const lastRun = sync.lastRun || {};
  const candidateCount = Number(candidate.messages || 0);
  const stateMap = {
    candidate_pending: ["待审核增量", "warning"],
    formal_updated: ["正式数据已更新", "ok"],
    ready: ["正式基线可用", "ok"],
    unknown: ["等待同步状态", "neutral"]
  };
  const [stateLabel, stateTone] = stateMap[sync.status] || stateMap.unknown;
  const apiLabel = api.available === false ? "API 暂缓" : sync.status ? "API 可用" : "等待检查";
  const direction = sync.confirmedDirection || "前端能直接拉群就少说；客户主动提问时简短回答后拉群，在群里对接。";
  return `
    <section class="conversion-sync-panel" data-sync-status="${escapeHtml(sync.status || "unknown")}">
      <div class="conversion-sync-heading">
        <div>
          <span class="conversion-sync-kicker">数据同步中心 · 资料状态</span>
          <h3>先用正式 SOP，候选聊天不会混进当前推荐</h3>
          <p>一线只按正式资料执行；增量由维护者审核、清洗和重建后才会进入正式推荐。</p>
        </div>
        <span class="conversion-sync-state ${stateTone}">${stateLabel}</span>
      </div>
      <div class="conversion-sync-summary"><strong>业务使用口径</strong><span>正式 SOP ${formatNumber(formal.questionCount || 0)} 条可直接使用</span><em>${candidateCount ? `另有 ${formatNumber(candidateCount)} 条聊天增量待审核` : "当前没有待审核增量"}</em></div>
      <details class="conversion-sync-details">
        <summary>查看同步详情 <small>维护者需要时再展开</small></summary>
        <div class="conversion-sync-metrics">
          <span><small>正式 SOP</small><b>${formatNumber(formal.questionCount || 0)}</b><em>${conversionSyncDate(formal.updatedAt)}</em></span>
          <span><small>待审核消息</small><b>${formatNumber(candidateCount)}</b><em>${candidateCount ? `${formatNumber(candidate.changedSessions || 0)} 个变化会话` : "暂无候选"}</em></span>
          <span><small>最近运行</small><b>${lastRun.checkedAt ? "已记录" : "暂无"}</b><em>${conversionSyncDate(lastRun.checkedAt)}</em></span>
          <span><small>连接状态</small><b>${apiLabel}</b><em>${conversionSyncDate(api.checkedAt)}</em></span>
        </div>
        <div class="conversion-sync-note ${stateTone === "warning" ? "warning" : ""}">
          <b>当前口径：</b>${candidateCount ? `最近 ${formatNumber(candidateCount)} 条增量仍是候选，尚未写入正式 SOP。` : "当前没有待审核增量。"}
          <span>下一步：${escapeHtml(sync.nextStep || "恢复 API 后按游标继续，再审核候选并重建正式 SOP。")}</span>
        </div>
        <div class="conversion-sync-direction"><b>已确认最短路径：</b>${escapeHtml(direction)}</div>
      </details>
    </section>`;
}

function renderConversionChatSourceStats() {
  if (conversionIndexDeferred("search")) {
    const error = conversionIndexErrors.search;
    return `<section class="conversion-source-stats conversion-source-stats-deferred" id="conversionChatSourceStats"><span><small>历史问答</small><b>${error ? "加载失败" : "按需加载"}</b></span><span><small>正式 SOP</small><b>已就绪</b></span><p>${escapeHtml(error || "点击“查历史回答”后读取完整历史索引，首屏不会被大数据包拖慢。")}</p></section>`;
  }
  const status = conversionData?.search?.状态 || conversionData?.search?.status || {};
  const indexed = status.已入库统计 || {};
  const scan = status.扫描统计 || {};
  const indexedSessionCount = indexed.唯一有效JSON会话 ?? indexed.有效会话 ?? scan.会话;
  const indexedMessageCount = indexed.总消息数 ?? indexed.消息总数 ?? indexed.消息 ?? scan.消息;
  const customerGroupCount = indexed.客户转化群 ?? scan.群聊;
  const frontPrivateCount = indexed.前端私聊会话 ?? indexed.前端私聊 ?? scan.私聊;
  const items = [
    ["历史问答条目", indexed.候选 || indexed.问答 || conversionHistories().length],
    ["历史索引会话", indexedSessionCount],
    ["历史索引消息", indexedMessageCount],
    ["历史转化群", customerGroupCount],
    ["历史前端私聊", frontPrivateCount]
  ].filter(([, value]) => value !== undefined && value !== "");
  return `<section class="conversion-source-stats" id="conversionChatSourceStats">${items.map(([name, value]) => `<span><small>${escapeHtml(name)}</small><b>${formatNumber(Number(value) || 0)}</b></span>`).join("")}</section>`;
}

function conversionPlanText(plan) {
  return conversionNorm([
    plan?.标题,
    plan?.城市,
    plan?.省份,
    plan?.时长,
    plan?.状态,
    plan?.格式,
    plan?.摘要,
    plan?.原文件,
    ...(plan?.活动 || []),
    ...(plan?.标签 || [])
  ].filter(Boolean).join(" "));
}

function matchConversionPlans(query = "", filters = []) {
  const q = conversionNorm(query);
  const picked = filters.map(item => conversionNorm(String(item).split(":").pop())).filter(Boolean);
  if (!q && !picked.length) return conversionPlans().slice(0, 12);
  return conversionPlans()
    .map((plan) => {
      const text = conversionPlanText(plan);
      const filterHit = picked.reduce((sum, token) => sum + (text.includes(token) ? 10 : 0), 0);
      const queryHit = q ? (text.includes(q) ? 25 : q.split(/[，,。！？\s]+/).filter(Boolean).reduce((sum, token) => sum + (text.includes(token) ? 5 : 0), 0)) : 0;
      return { plan, score: filterHit + queryHit };
    })
    .filter(row => row.score > 0)
    .sort((a, b) => b.score - a.score)
    .slice(0, 40)
    .map(row => row.plan);
}

function renderConversionPlanCards(rows = []) {
  if (!rows.length) return '<div class="conversion-empty">输入需求或选择筛选条件后，这里会显示本地方案匹配结果。</div>';
  return rows.map((plan) => {
    const tags = [plan?.城市, plan?.时长, plan?.状态, plan?.格式, ...(plan?.活动 || [])].filter(Boolean).slice(0, 10);
    const title = plan?.标题 || "未命名方案";
    const sourcePath = plan?.原文件 || plan?.source || plan?.path || "";
    const copyValue = [`方案：${title}`, plan?.摘要 ? `摘要：${plan.摘要}` : "", tags.length ? `标签：${tags.join("、")}` : ""].filter(Boolean).join("\n");
    return `
      <article class="conversion-plan-card">
        <div>
          <h3>${escapeHtml(title)}</h3>
          <div class="conversion-plan-tags">${tags.map(tag => `<span>${escapeHtml(tag)}</span>`).join("")}</div>
          ${plan?.摘要 ? `<p>${escapeHtml(plan.摘要)}</p>` : ""}
        </div>
        ${sourcePath ? `<small title="${escapeHtml(sourcePath)}">来源：${escapeHtml(sourcePath)}</small>` : ""}
        <div class="conversion-plan-card-actions">
          <button class="conversion-btn" type="button" data-copy-conversion-plan="${escapeHtml(copyValue)}">复制给策划师</button>
          ${sourcePath ? `<button class="conversion-btn primary" type="button" data-open-conversion-plan="${escapeHtml(sourcePath)}">打开方案源文件</button>` : ""}
        </div>
      </article>`;
  }).join("");
}

function renderConversionProposalStats() {
  if (conversionIndexDeferred("proposal")) {
    const error = conversionIndexErrors.proposal;
    return `<section class="conversion-proposal-stats conversion-proposal-stats-deferred"><span><small>当前方案库</small><b>${error ? "加载失败" : "按需加载"}</b></span><p>${escapeHtml(error || "进入方案匹配或点击“匹配方案”后加载完整方案索引。")}</p></section>`;
  }
  const plans = conversionPlans();
  const status = conversionData?.plans?.状态 || conversionData?.plans?.status || {};
  const counts = { PPT: 0, PDF: 0, Word: 0, 其他: 0 };
  plans.forEach(plan => {
    const format = String(plan?.格式 || plan?.原文件 || "").toLowerCase();
    if (format.includes("ppt")) counts.PPT += 1;
    else if (format.includes("pdf")) counts.PDF += 1;
    else if (format.includes("doc") || format.includes("wps")) counts.Word += 1;
    else counts.其他 += 1;
  });
  const total = plans.length || Number(status.索引方案 || 0);
  return `<section class="conversion-proposal-stats"><span><small>当前方案库</small><b>${formatNumber(total)}</b></span>${Object.entries(counts).map(([name, value]) => `<span><small>${name}</small><b>${formatNumber(value)}</b></span>`).join("")}</section>`;
}

