function installPageHelpButtons() {
  const buttonContent = `<svg class="round-action-icon help-icon" viewBox="0 0 24 24" aria-hidden="true"><path d="M9.5 9a2.75 2.75 0 1 1 4.4 2.2c-1.1.8-1.9 1.35-1.9 2.8"/><circle cx="12" cy="17.2" r=".75"/></svg>`;
  Object.entries(PAGE_HELP).forEach(([viewId, help]) => {
    const view = document.getElementById(viewId);
    const heading = view?.querySelector(".page-heading, .production-workbench-heading, .production-api-flow");
    if (!heading) return;
    let button = heading.querySelector("[data-page-help]");
    if (!button) {
      button = document.createElement("button");
      button.type = "button";
      button.className = "page-help-button";
      button.dataset.pageHelp = viewId;
      const actionRow = heading.querySelector(".detail-button-row");
      if (actionRow) actionRow.appendChild(button);
      else heading.appendChild(button);
    }
    document.querySelectorAll(`[data-page-help="${viewId}"]`).forEach((helpButton) => {
      helpButton.innerHTML = buttonContent;
      helpButton.title = `${help.title}：${help.description}`;
      helpButton.setAttribute("aria-label", `${help.title}，点击查看说明`);
      helpButton.dataset.helpModule = "true";
      helpButton.dataset.pageHelp = viewId;
      helpButton.dataset.tooltip = help.title;
      helpButton.dataset.helpBackground = help.description;
      const detailText = (labels, fallback) => (help.details || [])
        .filter(([label]) => labels.some((keyword) => String(label).includes(keyword)))
        .map(([, value]) => value)
        .join(" ") || fallback;
      helpButton.dataset.helpUse = detailText(["用途", "怎么使用", "输入", "怎么用"], `用于查看和操作${help.title}对应的工作区。`);
      helpButton.dataset.helpWhat = detailText(["数据范围", "素材来源", "事实来源", "它是什么"], help.description);
      helpButton.dataset.helpHow = detailText(["怎么使用", "执行流程", "六个阶段", "搜问题"], "先阅读当前页面状态，再按页面提供的主入口操作。");
      helpButton.dataset.helpRunning = detailText(["如何运行", "发送边界", "保存规则", "结果标准"], "页面会读取当前配置和真实状态，完成或失败后留下可核对结果。");
      helpButton.dataset.helpWhy = detailText(["安全边界", "数据边界", "它不会做什么", "为什么"], "把说明放在入口旁，是为了让每次操作都可理解、可恢复、可追踪。");
    });
  });
}

function skillStatusLabel(status) {
  const map = {
    ready: "已接入",
    disabled: "已关闭",
    needs_user: "运行前预检",
    blocked: "暂不可运行",
    candidate_pending: "候选待确认",
    verified: "核验通过",
    not_refreshed: "未刷新",
    unavailable: "服务不可用"
  };
  return map[status] || status || "待检查";
}

function skillRunLabel(task) {
  if (!task) return "尚未运行";
  const map = {
    queued: "排队中",
    running: "运行中",
    completed: "本次完成",
    succeeded: "本次完成",
    preview_ready: "预览完成",
    disabled: "已关闭",
    needs_user: "需要处理",
    blocked: "已拦截",
    failed: "运行失败"
  };
  return map[task.state] || task.state || "待处理";
}

function skillResultLinks(task, skill = null) {
  const result = task?.result || {};
  const links = [];
  const seen = new Set();
  const addPath = (value, label, tooltip) => {
    const target = String(value || "").trim();
    if (!target || seen.has(`path:${target}`)) return;
    seen.add(`path:${target}`);
    links.push(`<button type="button" class="skill-result-link" data-skill-result-open="${escapeHtml(target)}" data-tooltip="${escapeHtml(tooltip || label)}">${escapeHtml(label)}</button>`);
  };
  const addUrl = (value, label, tooltip) => {
    const target = String(value || "").trim();
    if (!target || seen.has(`url:${target}`)) return;
    seen.add(`url:${target}`);
    links.push(`<button type="button" class="skill-result-link" data-skill-result-url="${escapeHtml(target)}" data-tooltip="${escapeHtml(tooltip || label)}">${escapeHtml(label)}</button>`);
  };

  // Static card actions remain available before a run; these are the exits
  // created by this particular task result.
  if (skill?.id !== "wechat-teambuilding-conversion") {
    addPath(result.reportPath, "打开运行报告", "打开本次技能运行报告，不会再次运行");
    addUrl(result.targetUrl, "打开目标表", "打开本次运行使用的目标表，不触发同步");
  }
  addPath(task?.outputDir || result.outputDir, "打开下载目录", "打开本次下载保存目录，不会再次下载");
  addPath(result.targetRoot, "打开素材库", "打开本次素材处理写入的素材库，不会再次整理");
  addPath(result.after?.sourceDirectory, "打开聊天源目录", "打开本次提取使用的聊天源目录，不会再次扫描");
  addPath(result.intakePath, "打开待分析记录", "打开本次模板收录的待分析记录，不会再次收录");
  addPath(result.repositoryPath, result.repositoryLabel ? `打开${result.repositoryLabel}` : "打开模板仓库 HTML", "打开模板仓库结果，不会再次同步");
  addPath(result.libraryRoot, "打开朋友圈仓库", "打开朋友圈技能本次使用的作品库，不会再次采集");
  addPath(result.presencePath, "打开设备状态快照", "打开本次设备扫描写入的状态快照，不会再次扫描");
  addPath(result.automationLogPath, "打开分发日志", "打开自动分发日志，不会再次触发发送");
  if (skill?.id === "jianghu-sop-maintainer" && result.knowledgeSource?.path) {
    addPath(result.knowledgeSource.path, "打开来源材料", "打开维护检查使用的来源材料，不会写回内容");
  }
  return links.join("");
}

function renderSkillResult(task, skill = null) {
  if (!task) return "";
  const result = task.result || {};
  const resultLinks = skillResultLinks(task, skill);
  const preflight = task.preflight;
  const preflightHtml = preflight ? `<small class="skill-preflight-summary">${escapeHtml(preflight.message || "已完成运行前检查")}${Array.isArray(preflight.actions) && preflight.actions.length ? ` · ${escapeHtml(preflight.actions.join("；"))}` : ""}</small>` : "";
  if (task.error) {
    return `<div class="skill-result skill-result-error"><strong>${escapeHtml(skillRunLabel(task))}</strong><span>${escapeHtml(task.error.message || "未完成")}</span>${preflightHtml}${resultLinks ? `<div class="skill-result-links">${resultLinks}</div>` : ""}</div>`;
  }
  const facts = [];
  if (result.kind === "material_ingestion") {
    facts.push(`完整帖子 ${Number(result.completePosts ?? 0)}`);
    facts.push(task.mode === "preview" ? `预计移动 ${Number(result.completePosts ?? 0)}` : `已移动 ${Number(result.moved ?? 0)}`);
    facts.push(`空目录 ${Number(result.emptyPosts ?? result.removedEmptyPosts ?? 0)}`);
    facts.push(`残留待确认 ${Number(result.residualDirs ?? result.preservedResidualDirs ?? 0)}`);
    facts.push(task.mode === "preview" ? "未改动原文件" : "标签与批次已写入");
  } else if (task.mode === "preview" || result.newLeads !== undefined || result.readBack !== undefined) {
    const count = (value) => value === undefined || value === null ? "—" : String(value);
    facts.push(`新增 ${count(result.newLeads)}`);
    facts.push(`重复 ${count(result.duplicates)}`);
    facts.push(`待复核 ${count(result.review)}`);
    facts.push(`写入 ${count(result.written)}`);
    facts.push(`回读 ${result.readBack === undefined ? "待确认" : result.readBack ? "通过" : "未通过"}`);
  } else if (result.status === "candidate_ready") {
    const stats = result.after?.scanStats || {};
    const indexed = result.after?.indexed || {};
    facts.push(`扫描文件 ${Number(stats["有效导出文件"] || stats["文件数"] || 0) || "已完成"}`);
    facts.push(`候选索引 ${Number(indexed["候选数"] || indexed["问答候选"] || 0) || "已刷新"}`);
    facts.push(`正式写入：${result.formalWrite === false ? "未写入" : "需核对"}`);
  } else if (result.mode === "后端维护") {
    facts.push(`正式 SOP ${result.formalSopCount ?? "—"}`);
    facts.push(`方案 ${result.planCount ?? "—"}`);
    facts.push(`服务 ${result.service === "reachable" ? "可达" : "未刷新"}`);
    facts.push(`同步 ${skillStatusLabel(result.syncStatus)}`);
  } else if (result.momentsAction === "collect") {
    facts.push(`新增 ${Number(result.imported || 0)}`);
    facts.push(`去重/忽略 ${Number(result.deduplicated_or_ignored || 0)}`);
    facts.push(`标签 ${Number(result.tag_organization?.asset_json_created_or_updated || 0) || "已检查"}`);
  } else if (result.momentsAction === "organize") {
    facts.push(`标签整理 ${Number(result.asset_json_created_or_updated || result.updated || result.updatedCount || 0) || "已完成"}`);
    facts.push("未移动原素材");
  } else if (result.momentsAction === "prepare") {
    facts.push(result.stage || result.status || "已停在发表前");
    facts.push("等待人工发表");
  } else if (result.deviceTransferAction === "check_and_auto_dispatch") {
    facts.push(`在线设备 ${Number(result.onlineDeviceCount || 0)}`);
    facts.push(`已触发 ${Number(result.automation?.triggered?.length || 0)} 台`);
    facts.push(result.automation?.eventMode || "扫描兜底");
    facts.push(result.automation?.enabled && result.automation?.detectOnConnection ? "自动分发已开启" : "自动分发未开启");
  }
  return `<div class="skill-result"><strong>${escapeHtml(skillRunLabel(task))}</strong><span>${facts.map(escapeHtml).join(" · ") || "已生成运行报告"}</span>${preflightHtml}${result.nextStep ? `<small>${escapeHtml(result.nextStep)}</small>` : ""}${resultLinks ? `<div class="skill-result-links">${resultLinks}</div>` : ""}</div>`;
}

function skillSourceStatus(skill) {
  if (skill?.id === "material-download") return skill.available === false ? "blocked" : "ready";
  return skill?.status?.overallStatus || "ready";
}

function isDocumentationSkill(skill) {
  return Boolean(skill?.documentationOnly || skill?.status?.overallStatus === "docs_only");
}

function knowledgeModuleStateLabel(state) {
  return {
    integrate: "工作台执行",
    reference: "复盘参考",
    maintainer: "技能维护"
  }[state] || "待筛选";
}

function skillKnowledgeSourceHtml(skill) {
  const source = skill?.knowledgeSource;
  if (!source) return "";
  const modules = normalizedSkillKnowledgeModules(source);
  const integrated = modules.filter((module) => module.state === "integrate").length;
  const availableLabel = source.available ? `来源可用 · ${integrated} 项进入工作台` : "来源材料未找到";
  return `<div class="skill-knowledge-source" data-skill-knowledge-source="${escapeHtml(skill.id)}"><div><strong>${escapeHtml(source.title || "全链路知识库来源材料")}</strong><small>${escapeHtml(availableLabel)}</small></div><div class="skill-knowledge-source-actions">${source.available ? `<button type="button" class="secondary-button" data-skill-knowledge-open="${escapeHtml(source.path)}" data-tooltip="打开来源材料；不会触发更新或写回">查看来源</button>` : ""}<button type="button" class="secondary-button" data-skill-knowledge-detail="${escapeHtml(skill.id)}" data-tooltip="查看模块进入流量转化工作台的去向">查看模块去向</button></div></div>`;
}

function skillCardHtml(skill) {
    const status = skillRuns.get(skill.id) || null;
    const isMaterialDownload = skill.id === "material-download";
    const isMaterialIngestion = skill.id === "jianghu-toolbox-material-ingestion";
    const isMomentsSkill = skill.id === "wechat-moments-library";
    const sourceStatus = skillSourceStatus(skill);
    const running = status && ["queued", "running"].includes(status.state);
    const isLeadSkill = skill.id === "wechat-teambuilding-conversion";
    const isTemplateSkill = skill.id === "template-repository-maintainer";
    const skillMeta = skillContextMeta(skill);
    const configuredDownloadDir = isMaterialDownload ? (pageSettings().skills?.materialDownloadOutputDir || skill.defaultOutputDir || "Downloads") : "";
    const settingsActionLabel = "设置";
    const displayTitle = isTemplateSkill ? "模板仓库添加整理" : skill.title;
    const openTargets = isLeadSkill && skill.openTargets ? skill.openTargets : {};
    const previewReady = (isLeadSkill || isMaterialIngestion) && status?.state === "preview_ready";
    const documentationOnly = isDocumentationSkill(skill);
    const momentsSkillPolicy = MOMENTS_SKILL_POLICIES.has(selectedMomentsSkillPolicy)
      ? selectedMomentsSkillPolicy
      : (MOMENTS_SKILL_POLICIES.has(pageSettings().moments?.selectionRule)
        ? pageSettings().moments.selectionRule
        : "anniversary");
    const momentsPolicyButton = (policy, label, title) => `<button type="button" class="secondary-button skill-card-policy-action moments-skill-policy-option${momentsSkillPolicy === policy ? " is-selected" : ""}" data-moments-skill-policy="${policy}" aria-pressed="${momentsSkillPolicy === policy ? "true" : "false"}" title="${title}">${momentsSkillPolicy === policy ? "✓ " : ""}${label}</button>`;
    // 模板仓库属于“模板”分类；即使旧服务缓存仍返回历史默认分类，也不要把它显示成“流量转化”。
    const category = isTemplateSkill ? "模板" : (skill.category || (isMaterialDownload || isMaterialIngestion ? "素材处理" : isLeadSkill ? "流量转化" : "已接入技能"));
    const background = skill.background || "把可重复的业务动作收进可验证的技能入口。";
    const usage = skill.usage || "点击运行按钮，按照页面状态完成预检、执行和结果核对。";
    const input = skill.input || "工作台当前页面的选择、配置和授权状态。";
    const invocation = skill.invocation || "由工作台按钮或对应工作流触发；运行后轮询任务状态并显示真实结果。";
    const operation = skill.operation || (isLeadSkill ? "预检 → 增量读取 → 预览 → 人工确认 → 写入回读。" : "读取输入 → 执行适配器 → 回读结果 → 记录状态。");
  const output = skill.output || "任务状态、结果摘要、失败原因和下一步。";
  const linkedSkills = Array.isArray(skill.linkedSkills) ? skill.linkedSkills : [];
    const policy = normalizedSkillSafety(skill);
    const helpHow = [invocation, Array.isArray(skill.flow) && skill.flow.length ? `流程：${skill.flow.join(" → ")}` : ""].filter(Boolean).join(" ");
    const helpRunning = [operation, `结果：${output}`].filter(Boolean).join(" ");
    const issueItems = Array.isArray(skill.status?.issues) ? skill.status.issues : [];
    const settings = skill.settings || {};
    const templateInputGuidance = "支持模板名称、文字描述、来源备注、小红书/GPT/网页链接、本地文件夹或文件路径，也可直接拖入图片、文件夹，或 Ctrl+V 粘贴图片；混合输入后点击“收录”，系统会自动识别、登记来源、打标签并提示缺口。";
    const helpUse = isTemplateSkill ? "把模板链接、图片、本地文件夹或文字描述收进跨项目可复用模板仓库，并保留来源、标签、预览和缺口。" : usage;
    const templateDescription = skill.description || skill.title;
    const helpWhat = isTemplateSkill ? `${templateDescription}${String(templateDescription).endsWith("。") ? "" : "。"}${templateInputGuidance}` : templateDescription;
    const helpHowForSkill = isTemplateSkill ? "把材料粘贴到输入框，或拖入图片/文件夹；也可以一次混合输入链接、路径和描述，然后点击“收录”。系统会下载公开笔记、保存原始素材、同步项目与全局索引，并把未确认字段留在待补状态。" : helpHow;
    const helpAttributes = `data-help-module="true" data-help-id="skill:${escapeHtml(skill.id)}" data-tooltip="${escapeHtml(`${displayTitle}：${helpUse}`)}" data-help-background="${escapeHtml(background)}" data-help-use="${escapeHtml(helpUse)}" data-help-what="${escapeHtml(helpWhat)}" data-help-how="${escapeHtml(helpHowForSkill)}" data-help-running="${escapeHtml(helpRunning)}" data-help-why="${escapeHtml(policy)}"`;
    const statusLabel = documentationOnly ? "说明入口" : sourceStatus === "ready" ? "可执行" : skillStatusLabel(sourceStatus);
    const quickTool = isMaterialDownload
      ? `<div class="skill-quick-entry" data-skill-quick-entry="material-download"><input type="text" data-skill-material-input="${escapeHtml(skill.id)}" aria-label="素材下载内容" placeholder="粘贴公开链接或文案…" /><div class="skill-quick-actions"><button class="primary-button skill-card-execute-action" type="button" data-skill-download-run="${escapeHtml(skill.id)}">下载</button><button type="button" class="secondary-button skill-card-result-action" data-skill-download-open="${escapeHtml(skill.id)}" data-tooltip="打开素材下载设置指定的目录，不会启动下载">打开下载目录</button></div></div>`
      : isTemplateSkill
        ? `<div class="skill-quick-entry" data-skill-quick-entry="template-repository" data-template-quick-drop="true"><input type="text" data-skill-template-input="${escapeHtml(skill.id)}" aria-label="模板名称、文字描述、来源链接或本地路径" placeholder="输入名称、描述、链接或本地路径；也可拖入图片 / Ctrl+V…" data-tooltip="模板输入支持文字、链接、路径、图片和文件夹；详细规则请悬停技能卡 3 秒查看" /><div class="skill-quick-actions"><button type="button" class="secondary-button skill-card-result-action" data-template-repository-open="${escapeHtml(skill.id)}">打开 HTML</button><button class="primary-button skill-card-execute-action" type="button" data-template-repository-run="${escapeHtml(skill.id)}">收录</button></div></div>`
        : "";
    const runFlowSteps = isMaterialDownload
      ? ["粘贴素材", "识别平台", `保存到 ${configuredDownloadDir}`]
      : (Array.isArray(skill.flow) ? skill.flow.filter(Boolean) : []);
    const runFlow = status && runFlowSteps.length
      ? `<section class="skill-run-flow" data-skill-run-flow="${escapeHtml(skill.id)}" aria-live="polite"><div class="skill-run-flow-head"><strong>如何运行</strong><span>${escapeHtml(skillRunLabel(status))}</span></div><div class="skill-run-flow-track">${runFlowSteps.map((step, index) => `${index ? '<span class="skill-run-flow-arrow" aria-hidden="true">→</span>' : ""}<span class="skill-run-flow-step"><b>${String(index + 1).padStart(2, "0")}</b>${escapeHtml(step)}</span>`).join("")}</div></section>`
      : "";
    return `
      <article class="skill-card${running ? " is-running" : ""}${documentationOnly ? " is-support" : ""}" data-skill-layer="${documentationOnly ? "support" : "executable"}" data-skill-card="${escapeHtml(skill.id)}" data-skill-path-configurable="${settings.configurable && Array.isArray(settings.pathFields) && settings.pathFields.length ? "true" : "false"}" tabindex="0" aria-label="${escapeHtml(`${displayTitle}：${skill.description}`)}" ${helpAttributes}>
        <div class="skill-card-head">
          <div><p class="label">${escapeHtml(category)}</p><h3>${escapeHtml(displayTitle)}</h3></div>
          <div class="skill-card-status-stack"><span class="skill-status-pill ${sourceStatus === "ready" ? "is-ready" : documentationOnly ? "is-docs" : "is-warning"}">${escapeHtml(statusLabel)}</span></div>
        </div>
        <p class="skill-card-description">${escapeHtml(skill.description)}</p>
        <div class="skill-card-details" aria-label="技能介绍和安全边界">
          <strong>介绍</strong><p>${escapeHtml([background, usage, input, invocation].filter(Boolean).join(" "))}</p>
          <strong>安全边界</strong><p>${escapeHtml(policy)}</p>
        </div>
        <p class="skill-safety"><strong>边界</strong>${escapeHtml(normalizedSkillSafety(skill) || skill.qualification || policy)}</p>
        ${issueItems.length ? `<div class="skill-issues"><strong>当前门禁</strong><ul>${issueItems.map((issue) => `<li>${escapeHtml(issue.label || issue.code || "需要处理")}</li>`).join("")}</ul></div>` : ""}
        ${quickTool}
        ${runFlow}
        ${skillKnowledgeSourceHtml(skill)}
        <div class="skill-card-actions${isMomentsSkill ? " moments-skill-actions" : ""}">
           ${isMomentsSkill
           ? `<button class="secondary-button skill-card-entry-action" type="button" data-moments-skill-action="collect" title="通过 WeFlow 采集历史朋友圈，按设置选择 10 条或全部，逐条落盘并去重；完成后自动整理标签">采集</button><button class="secondary-button skill-card-entry-action" type="button" data-moments-skill-action="organize" title="扫描朋友圈作品，为每条补齐可编辑的年份、月份、季节、地点、活动和自动标签">整理标签</button><button class="secondary-button skill-card-result-action" type="button" data-moments-skill-action="open" title="打开朋友圈仓库，浏览素材、文案和标签">朋友圈仓库</button><button class="primary-button skill-card-execute-action" type="button" data-moments-skill-action="prepare" title="按技能设置的日期规则选一条素材，填入微信并停在最终发表前，不会自动点击发表">触发发送</button><span class="moments-skill-policy-label">选材并准备</span>${momentsPolicyButton("last-year-day", "去年今天", "固定选取上一年今天的素材，直接触发准备，不切换侧栏")}${momentsPolicyButton("historical-day", "往年今天", "在历史年份的今天中随机选取一年，直接触发准备，不切换侧栏")}${momentsPolicyButton("last-year-month", "去年本月", "选取上一年同月的素材，直接触发准备，不切换侧栏")}${momentsPolicyButton("anniversary", "智能回退", "先找去年今天，没有时再找去年本月随机，仍没有时再找历史同月随机，历史用完再用今年未发布素材；直接触发准备，不切换侧栏")}`
            : isMaterialDownload || isTemplateSkill
            ? ""
            : documentationOnly
              ? `<span class="skill-docs-only-hint">当前仅提供说明与联动契约</span>`
              : `<button class="primary-button skill-card-execute-action" type="button" data-skill-run="${escapeHtml(skill.id)}" data-tooltip="${escapeHtml(`${skill.title}：${operation}`)}"${running || skill.status?.canRun === false ? " disabled" : ""}>${running ? "运行中…" : escapeHtml(skill.runLabel || "运行技能")}</button>${previewReady ? `<button class="secondary-button skill-card-commit-action" type="button" data-skill-commit="${escapeHtml(skill.id)}" data-tooltip="确认上一次预览后执行写入动作">${isMaterialIngestion ? "确认预览并整理素材" : "确认预览并更新表"}</button>` : ""}`}
           ${isLeadSkill && openTargets.targetUrl ? `<button type="button" class="secondary-button skill-card-result-action skill-result-link" data-skill-result-url="${escapeHtml(openTargets.targetUrl)}" data-tooltip="打开已配置的飞书客资统计表，不触发同步">打开飞书表格</button>` : ""}
           ${isLeadSkill && openTargets.reportPath ? `<button type="button" class="secondary-button skill-card-result-action skill-result-link" data-skill-result-open="${escapeHtml(openTargets.reportPath)}" data-tooltip="打开历史运行报告目录，不触发同步">查看历史报告</button>` : ""}
           <span class="skill-card-utilities"><button type="button" class="secondary-button skill-card-settings-action" data-skill-settings="${escapeHtml(skill.id)}" data-tooltip="在当前技能中心弹出${escapeHtml(skillMeta.settingsLabel || `${displayTitle}设置`)}">${settingsActionLabel}</button><button type="button" class="secondary-button skill-card-help-action" data-skill-open="${escapeHtml(skill.sourcePath || "")}" data-tooltip="在当前界面查看 ${escapeHtml(skill.title)} 的技能说明">查看说明</button></span>
        </div>
        ${linkedSkills.length ? `<div class="skill-connector-row" aria-label="联动技能">${linkedSkills.map((item) => `<span class="skill-connector">→ ${escapeHtml(item)}</span>`).join("")}</div>` : ""}
        ${status ? `<div class="skill-run-status"><span class="skill-run-state">${escapeHtml(skillRunLabel(status))}${status.progress ? ` · ${status.progress}%` : ""}</span>${renderSkillResult(status, skill)}</div>` : ""}
      </article>`;
}

function updateSkillsCenterStatus() {
  const executableSkills = skillsCatalog.filter((skill) => !isDocumentationSkill(skill));
  const readySkills = executableSkills.filter((skill) => skillSourceStatus(skill) === "ready");
  const needsUserSkills = executableSkills.filter((skill) => ["needs_user", "candidate_pending", "blocked"].includes(skillSourceStatus(skill)));
  const status = $("#skillsCatalogStatus");
  if (status) status.textContent = `${readySkills.length} 项可执行${needsUserSkills.length ? ` · ${needsUserSkills.length} 项需处理` : ""}`;
}

function renderSkillsCenter() {
  const executableGrid = $("#skillsGrid");
  if (!executableGrid) return;
  if (!skillsCatalog.length) {
    executableGrid.innerHTML = `<div class="skills-loading">正在读取可执行技能…</div>`;
    return;
  }
  const executableSkills = skillsCatalog.filter((skill) => !isDocumentationSkill(skill));
  executableGrid.innerHTML = executableSkills.length ? executableSkills.map(skillCardHtml).join("") : `<div class="skills-empty-state">当前没有可执行技能。</div>`;
  updateSkillsCenterStatus();
  $$('[data-skill-run]').forEach((button) => button.addEventListener("click", () => runSkill(button.dataset.skillRun, "preview")));
  $$('[data-skill-commit]').forEach((button) => button.addEventListener("click", () => runSkill(button.dataset.skillCommit, "commit")));
  $$('[data-moments-skill-action]').forEach((button) => button.addEventListener("click", () => runMomentsSkillAction(button.dataset.momentsSkillAction, button)));
  $$('[data-moments-skill-policy]').forEach((button) => button.addEventListener("click", () => {
    const policy = button.dataset.momentsSkillPolicy || "anniversary";
    selectedMomentsSkillPolicy = MOMENTS_SKILL_POLICIES.has(policy) ? policy : "anniversary";
    $$('[data-moments-skill-policy]').forEach((option) => {
      const selected = option.dataset.momentsSkillPolicy === selectedMomentsSkillPolicy;
      option.classList.toggle("is-selected", selected);
      option.setAttribute("aria-pressed", selected ? "true" : "false");
      option.textContent = `${selected ? "✓ " : ""}${option.dataset.momentsSkillPolicy === "last-year-day" ? "去年今天" : option.dataset.momentsSkillPolicy === "historical-day" ? "往年今天" : option.dataset.momentsSkillPolicy === "last-year-month" ? "去年本月" : "智能回退"}`;
    });
    return runMomentsSkillAction("prepare", button, { policy: selectedMomentsSkillPolicy });
  }));
  $$('[data-skill-download-run]').forEach((button) => button.addEventListener("click", () => runMaterialDownloadSkillCard(button.dataset.skillDownloadRun)));
  $$('[data-skill-download-open]').forEach((button) => button.addEventListener("click", () => openMaterialDownloadDirectory(button.dataset.skillDownloadOpen)));
  $$('[data-template-repository-run]').forEach((button) => button.addEventListener("click", () => runTemplateRepositorySkillCard(button.dataset.templateRepositoryRun)));
  $$('[data-template-repository-open]').forEach((button) => button.addEventListener("click", () => openTemplateRepository()));
  $$('[data-skill-settings]').forEach((button) => button.addEventListener("click", () => openSkillContextPanel({ kind: "skill-card", skillId: button.dataset.skillSettings }, "settings")));
  installTemplateRepositoryQuickInputs();
  $$('[data-skill-open]').forEach((button) => button.addEventListener("click", () => {
    const card = button.closest("[data-skill-card]");
    openSkillContextPanel({
      kind: "skill-card",
      skillId: card?.dataset.skillCard || "",
      sourcePath: button.dataset.skillOpen || ""
    }, "source");
  }));
  $$('[data-skill-knowledge-open]').forEach((button) => button.addEventListener("click", async () => {
    const targetPath = button.dataset.skillKnowledgeOpen || "";
    button.disabled = true;
    try {
      await openPath(targetPath);
      toast("已打开全链路 HTML 报告");
    } catch (error) {
      toast(`HTML 报告打开失败：${error.message}`, "error");
    } finally {
      button.disabled = false;
    }
  }));
  $$('[data-skill-knowledge-detail]').forEach((button) => button.addEventListener("click", () => {
    const skill = skillsCatalog.find((item) => item.id === button.dataset.skillKnowledgeDetail);
    if (!skill) return;
    openSkillContextPanel({ skillId: skill.id, sourcePath: skill.sourcePath }, "source");
  }));
  $$('[data-skill-result-open]').forEach((button) => button.addEventListener("click", async () => {
    try {
      await openPath(button.dataset.skillResultOpen);
      toast("已打开运行报告");
    } catch (error) {
      toast(`运行报告打开失败：${error.message}`, "error");
    }
  }));
  $$('[data-skill-result-url]').forEach((button) => button.addEventListener("click", async () => {
    try {
      await openExternal(button.dataset.skillResultUrl);
      toast("已打开目标表");
    } catch (error) {
      toast(`目标表打开失败：${error.message}`, "error");
    }
  }));
}

async function requestMomentsCollectDetails() {
  const moments = pageSettings().moments || {};
  const friend = await openSystemDialog({
    eyebrow: "朋友圈采集",
    title: "填写目标朋友圈账号",
    description: "填写微信号或微信昵称。采集会通过本机 WeFlow API 执行，按下一步选择 10 条或全部，并按条落盘。",
    input: {
      label: "微信号或微信昵称",
      value: moments.collectionAccount || "",
      maxLength: 160
    },
    confirmLabel: "下一步"
  });
  if (!friend) return null;

  const wxid = await openSystemDialog({
    eyebrow: "朋友圈采集",
    title: "补充 WeFlow UID（可选）",
    description: "微信号可以直接作为定位值；如果填写的是昵称，建议补充 WeFlow UID，避免同名账号采集错误。UID 不会写入 Git 或共享配置。",
    details: [{ label: "目标账号", value: friend }],
    input: {
      label: "WeFlow UID（可选）",
      value: moments.collectionWxid || "",
      maxLength: 160
    },
    confirmLabel: "下一步"
  });
  if (wxid === false) return null;

  const collectionLimit = await openSystemDialog({
    eyebrow: "朋友圈采集",
    title: "选择采集数量",
    description: "数量只影响本次采集；选择“全部”会按 WeFlow 分页读取该账号历史内容，耗时和媒体下载量会明显增加。",
    details: [{ label: "目标账号", value: friend }],
    select: {
      label: "本次采集",
      value: moments.collectionLimit === "all" ? "all" : "10",
      options: [{ value: "10", label: "10 条" }, { value: "all", label: "全部" }]
    },
    confirmLabel: "下一步"
  });
  if (collectionLimit === false) return null;

  if (moments.requireWechatReady !== false) {
    const ready = await openSystemDialog({
      eyebrow: "朋友圈采集前提",
      title: "确认微信 / WeFlow 已加载目标朋友圈",
      description: "请先在微信里打开目标好友的朋友圈，让微信和 WeFlow 完成加载，再继续采集。这里是人工确认，不会替你自动浏览或伪造已加载状态。",
      details: [
        { label: "账号", value: friend },
        { label: "数量", value: collectionLimit === "all" ? "全部" : "10 条" }
      ],
      warning: "如果 WeFlow 尚未看到目标账号，采集会失败并保留日志，不会自动换账号。",
      confirmLabel: "我已加载，继续采集"
    });
    if (!ready) return null;
  }

  const confirmed = await openSystemDialog({
    eyebrow: "朋友圈采集",
    title: "确认开始采集",
    description: `将通过本机 WeFlow API 读取该账号的朋友圈，本次${collectionLimit === "all" ? "采集全部历史内容" : "采集 10 条"}；每条立即保存，已有内容会去重，不会改写文案。`,
    details: [
      { label: "账号", value: friend },
      { label: "定位值", value: wxid || friend },
      { label: "数量", value: collectionLimit === "all" ? "全部" : "10 条" },
      { label: "保存位置", value: "D:\\朋友圈weflow" }
    ],
    warning: "采集失败会立即停止并保留日志，不会自动换下一个账号。",
    confirmLabel: "开始采集"
  });
  return confirmed ? { friend, wxid: String(wxid || friend).trim(), fullHistory: collectionLimit === "all", limit: collectionLimit === "all" ? 100 : 10 } : null;
}

async function runMomentsSkillAction(action, button, options = {}) {
  if (button) button.disabled = true;
  try {
    if (action === "open") {
      activateTab("moments");
      toast("已打开朋友圈仓库");
      return;
    }
    if (action === "organize") {
      const result = await api("/api/moments/organize", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: "{}"
      });
      await window.MomentsPublisherPanel?.loadLibrary?.({ preserveSelection: true });
      skillRuns.set("wechat-moments-library", {
        id: `moments-organize-${Date.now()}`,
        state: result.ok === false ? "failed" : "completed",
        mode: "organize",
        result: { ...(result.result || {}), momentsAction: "organize", libraryRoot: result.libraryRoot },
        error: result.ok === false ? { message: result.message || "朋友圈标签整理失败" } : null
      });
      renderSkillsCenter();
      toast(result.message || "朋友圈标签已整理");
      return;
    }
    if (action === "prepare") {
      const panel = window.MomentsPublisherPanel;
      await panel?.loadLibrary?.({ preserveSelection: false });
      if (options.policy) panel?.setSelectionPolicy?.(options.policy, { resetManualFilters: true });
      const selectionState = panel?.getSelectionState?.() || {};
      if (selectionState.todayLocked) {
        const lockedError = new Error(selectionState.lockMessage || "当前已有一条朋友圈正在填充微信，请等待本次准备结束");
        lockedError.code = "MOMENTS_DAY_LOCKED";
        throw lockedError;
      }
      const item = panel?.selectFirstReady?.();
      if (!item) {
        const emptyError = new Error(selectionState.emptyMessage || "当前日期策略下没有可准备的朋友圈素材");
        emptyError.code = "MOMENTS_NO_MATCH";
        throw emptyError;
      }
      // The card button and the Skill Center now share prepareSelected(), so
      // confirmation, retry rules, API payload and human-publish boundary
      // cannot drift apart.
      const prepared = await panel?.prepareSelected?.({ notify: false });
      if (prepared?.result) {
        skillRuns.set("wechat-moments-library", {
          id: `moments-prepare-${Date.now()}`,
          state: "completed",
          mode: "prepare",
          result: { ...(prepared.result || {}), momentsAction: "prepare", libraryRoot: prepared.libraryRoot },
          error: null
        });
        renderSkillsCenter();
      }
      return;
    }
    if (action === "collect") {
      const target = await requestMomentsCollectDetails();
      if (!target) return;
      const result = await api("/api/moments/collect", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ friend: target.friend, wxid: target.wxid, source: "weflow", limit: target.limit, fullHistory: target.fullHistory })
      });
      await window.MomentsPublisherPanel?.loadLibrary?.({ preserveSelection: true });
      const imported = Number(result.result?.imported || 0);
      const deduplicated = Number(result.result?.deduplicated_or_ignored || 0);
      const organized = Number(result.result?.tag_organization?.asset_json_created_or_updated || 0);
      skillRuns.set("wechat-moments-library", {
        id: `moments-collect-${Date.now()}`,
        state: result.ok === false ? "failed" : "completed",
        mode: "collect",
        result: { ...(result.result || {}), momentsAction: "collect", libraryRoot: result.libraryRoot },
        error: result.ok === false ? { message: result.message || "朋友圈采集失败" } : null
      });
      renderSkillsCenter();
      toast(`朋友圈采集完成：新增 ${imported} 条，去重/忽略 ${deduplicated} 条${organized ? `，已整理标签 ${organized} 条` : "，标签已检查"}`);
    }
  } catch (error) {
    if (action === "prepare") {
      skillRuns.set("wechat-moments-library", {
        id: `moments-prepare-${Date.now()}`,
        state: error.code === "MOMENTS_HUMAN_CONFIRM_REQUIRED" ? "needs_user" : "failed",
        mode: "prepare",
        result: { momentsAction: "prepare" },
        error: { message: error.userFacingMessage || error.message || "朋友圈准备失败" }
      });
      renderSkillsCenter();
    }
    if (action === "prepare" && error.code === "MOMENTS_DAY_LOCKED") {
      showSystemNotice("朋友圈今天已锁定", error.message, { tone: "warning" });
    } else if (action === "prepare" && error.code === "MOMENTS_NO_MATCH") {
      showSystemNotice("朋友圈没有匹配素材", error.message, { tone: "warning" });
    } else if (action === "prepare" && error.code === "MOMENTS_HUMAN_CONFIRM_REQUIRED") {
      showSystemNotice("朋友圈等待人工确认", error.message, { tone: "warning" });
    } else {
      showSystemNotice("朋友圈技能执行失败", error.message, { tone: "danger" });
    }
  } finally {
    if (button) button.disabled = false;
  }
}

async function loadSkillsCatalog() {
  if (skillsLoadPromise) return skillsLoadPromise;
  skillsLoadPromise = (async () => {
    const statusEl = $("#skillsCatalogStatus");
    if (statusEl) statusEl.textContent = "正在读取技能目录…";
    try {
      const payload = await api("/api/skills");
      skillsCatalog = Array.isArray(payload.skills) ? payload.skills : [];
      if (statusEl) statusEl.textContent = `${skillsCatalog.length} 个技能已接入`;
      const materialSkill = skillsCatalog.find((skill) => skill.id === "material-download");
      const materialState = $("#materialDownloadRunState");
      const materialBadge = $("#materialDownloadSkillBadge");
      const materialDir = $("#materialDownloadDefaultDir");
      if (materialDir && materialSkill?.defaultOutputDir) materialDir.textContent = materialSkill.defaultOutputDir;
      if (materialState && materialSkill) materialState.textContent = materialSkill.available ? "谨慎频率 · 引擎已连接" : "引擎不可用";
      if (materialBadge && materialSkill) {
        materialBadge.textContent = materialSkill.available ? "已连接" : "需检查";
        materialBadge.className = `state-badge ${materialSkill.available ? "good" : "warn"}`;
      }
      renderSkillsCenter();
      renderPageSettingsValues();
    } catch (error) {
      if (statusEl) statusEl.textContent = "技能目录读取失败";
      const grid = $("#skillsGrid");
      if (grid) grid.innerHTML = `<div class="skills-loading skills-loading-error">${escapeHtml(error.message)}</div>`;
    }
  })();
  try {
    return await skillsLoadPromise;
  } finally {
    skillsLoadPromise = null;
  }
}

async function runSkill(skillId, mode = "preview") {
  if (!skillId || ["queued", "running"].includes(skillRuns.get(skillId)?.state)) return;
  if (skillId === "template-repository-maintainer") {
    return runTemplateRepositorySkillCard(skillId);
  }
  const previous = skillRuns.get(skillId);
  const optimistic = { id: `local-start-${Date.now()}`, skillId, mode, state: "queued", progress: 0, steps: [], result: null, error: null };
  skillRuns.set(skillId, optimistic);
  renderSkillsCenter();
  toast(`${skillsCatalog.find((skill) => skill.id === skillId)?.title || "技能"}正在启动…`);
  try {
    const task = await api(`/api/skills/${encodeURIComponent(skillId)}/run`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        mode,
        confirm: mode === "commit",
        ...(mode === "commit" && previous?.state === "preview_ready" ? { previewTaskId: previous.id } : {})
      })
    });
    skillRuns.set(skillId, task);
    renderSkillsCenter();
    let current = task;
    while (current && ["queued", "running"].includes(current.state)) {
      await new Promise((resolve) => window.setTimeout(resolve, 800));
      // The task was already submitted above; only retry the read-back request.
      // Retrying POST here could start a duplicate WeFlow/Feishu operation.
      const list = await apiWithRetry(`/api/skills/${encodeURIComponent(skillId)}/tasks`);
      current = Array.isArray(list) ? list.find((item) => item.id === task.id) || current : current;
      skillRuns.set(skillId, current);
      renderSkillsCenter();
    }
    toast(current?.state === "completed" ? "技能运行完成" : `技能${skillRunLabel(current)}`, current?.state === "failed" ? "error" : undefined);
  } catch (error) {
    const failed = { id: `local-${Date.now()}`, state: "failed", progress: 0, error: { message: error.message } };
    skillRuns.set(skillId, failed);
    renderSkillsCenter();
    toast(`技能运行失败：${error.message}`, "error");
  }
}

function templateRepositoryFilePath(file) {
  try {
    return window.desktopFiles?.getPath?.(file) || file?.path || "";
  } catch {
    return file?.path || "";
  }
}

function readTemplateRepositoryFile(file) {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = () => resolve(String(reader.result || ""));
    reader.onerror = () => reject(reader.error || new Error("图片读取失败"));
    reader.readAsDataURL(file);
  });
}

function renderTemplateRepositoryFiles() {
  const list = $("#templateRepositoryFileList");
  if (!list) return;
  if (!templateRepositoryInputFiles.length) {
    list.innerHTML = "";
    return;
  }
  list.innerHTML = templateRepositoryInputFiles.map((file, index) => `
    <span class="template-repository-file-chip ${file.unsupported ? "is-warning" : ""}">
      <span>${escapeHtml(file.name || `文件 ${index + 1}`)}</span>
      <small>${file.path ? "本地路径" : file.dataUrl ? "已读入图片" : "需桌面权限"}</small>
      <button type="button" data-template-file-remove="${index}" aria-label="移除 ${escapeHtml(file.name || "文件")}">×</button>
    </span>`).join("");
  $$('[data-template-file-remove]').forEach((button) => button.addEventListener("click", () => {
    templateRepositoryInputFiles.splice(Number(button.dataset.templateFileRemove), 1);
    renderTemplateRepositoryFiles();
  }));
}

async function addTemplateRepositoryFiles(fileList) {
  const files = Array.from(fileList || []).slice(0, Math.max(0, 8 - templateRepositoryInputFiles.length));
  if (!files.length) {
    toast("最多同时处理 8 个文件", "error");
    return;
  }
  for (const file of files) {
    const name = String(file?.name || file?.webkitRelativePath || "未命名文件").slice(0, 120);
    const pathValue = templateRepositoryFilePath(file);
    const isImage = String(file?.type || "").toLowerCase().startsWith("image/");
    let dataUrl = "";
    if (isImage && !pathValue) {
      try { dataUrl = await readTemplateRepositoryFile(file); } catch { dataUrl = ""; }
    }
    templateRepositoryInputFiles.push({ name, path: pathValue, dataUrl, unsupported: !pathValue && !dataUrl });
  }
  renderTemplateRepositoryFiles();
  const state = $("#templateRepositoryRunState");
  if (state) state.textContent = `${templateRepositoryInputFiles.length} 个输入已接收 · 可继续补充链接或备注`;
}

async function addTemplateRepositoryQuickFiles(fileList) {
  const files = Array.from(fileList || []).slice(0, Math.max(0, 8 - templateRepositoryQuickInputFiles.length));
  if (!files.length) {
    toast("最多同时处理 8 个模板文件", "error");
    return;
  }
  for (const file of files) {
    const name = String(file?.name || file?.webkitRelativePath || "未命名文件").slice(0, 120);
    const pathValue = templateRepositoryFilePath(file);
    const isImage = String(file?.type || "").toLowerCase().startsWith("image/");
    let dataUrl = "";
    if (isImage && !pathValue) {
      try { dataUrl = await readTemplateRepositoryFile(file); } catch { dataUrl = ""; }
    }
    templateRepositoryQuickInputFiles.push({ name, path: pathValue, dataUrl, unsupported: !pathValue && !dataUrl });
  }
  toast(`已接收 ${files.length} 个模板文件，可继续补充文字或链接`);
}

function installTemplateRepositoryQuickInputs() {
  $$('[data-template-quick-drop="true"] input[data-skill-template-input]').forEach((input) => {
    if (input.dataset.bound === "true") return;
    input.dataset.bound = "true";
    const entry = input.closest('[data-template-quick-drop="true"]');
    if (!entry) return;
    input.addEventListener("paste", async (event) => {
      const item = Array.from(event.clipboardData?.items || []).find((candidate) => String(candidate.type || "").startsWith("image/"));
      if (!item) return;
      const file = item.getAsFile?.();
      if (!file) return;
      event.preventDefault();
      await addTemplateRepositoryQuickFiles([file]);
    });
    ["dragenter", "dragover"].forEach((type) => entry.addEventListener(type, (event) => {
      if (!event.dataTransfer?.files?.length) return;
      event.preventDefault();
      entry.classList.add("is-dragging");
    }));
    ["dragleave", "drop"].forEach((type) => entry.addEventListener(type, (event) => {
      if (!event.dataTransfer?.files?.length) return;
      event.preventDefault();
      entry.classList.remove("is-dragging");
    }));
    entry.addEventListener("drop", async (event) => {
      if (!event.dataTransfer?.files?.length) return;
      await addTemplateRepositoryQuickFiles(event.dataTransfer.files);
    });
  });
}

function renderTemplateRepositoryResult(task) {
  const state = $("#templateRepositoryRunState");
  const resultEl = $("#templateRepositoryResult");
  const button = $("#templateRepositoryRunBtn");
  if (!resultEl) return;
  if (!task) {
    if (button) button.disabled = false;
    if (state) state.textContent = "自动识别输入 · 同步来源与全局模板仓库";
    resultEl.innerHTML = `<div class="skill-result-empty">执行后显示采集、同步、预览和缺口。</div>`;
    return;
  }
  const taskState = String(task?.state || "queued");
  if (button) button.disabled = ["queued", "running"].includes(taskState);
  if (state) state.textContent = taskState === "completed"
    ? "模板仓库任务完成"
    : taskState === "failed" || taskState === "blocked"
      ? "模板仓库任务未完成"
      : "正在执行模板仓库技能…";
  if (["queued", "running"].includes(taskState)) {
    resultEl.innerHTML = `<div class="skill-result"><strong>正在执行模板仓库</strong><span>采集、待分析登记和来源/全局同步会按步骤推进。</span><small>请不要对同一批链接重复执行；失败时原始素材不会被覆盖。</small></div>`;
    return;
  }
  if (task?.error) {
    resultEl.innerHTML = `<div class="skill-result is-error"><strong>${escapeHtml(skillRunLabel(task))}</strong><span>${escapeHtml(task.error.message || "模板仓库任务未完成")}</span></div>`;
    return;
  }
  const result = task?.result || {};
  const downloaded = result.downloaded || {};
  const sync = result.sync || {};
  const syncLabel = sync.ok === true ? "来源项目与全局仓库已同步" : sync.ok === false ? "同步未全部完成" : "未执行同步";
  const accepted = Array.isArray(result.acceptedPaths) ? result.acceptedPaths.length : 0;
  const rejected = Array.isArray(result.rejectedPaths) ? result.rejectedPaths.length : 0;
  const facts = [
    `状态：${result.status || taskState}`,
    `下载成功 ${Number(downloaded.success || 0)} / 失败 ${Number(downloaded.failed || 0)}`,
    `本地路径 ${accepted} · 待确认 ${rejected}`,
    syncLabel
  ];
  resultEl.innerHTML = `<div class="skill-result ${result.status === "candidate_ready" ? "is-success" : "is-error"}"><strong>模板仓库已记录</strong><span>${facts.map(escapeHtml).join(" · ")}</span>${result.intakePath ? `<small>待分析收件箱：${escapeHtml(result.intakePath)}</small>` : ""}${result.nextStep ? `<small>${escapeHtml(result.nextStep)}</small>` : ""}</div>`;
}

async function openTemplateRepository() {
  const button = $("#templateRepositoryOpenBtn");
  if (button) button.disabled = true;
  try {
    const payload = await api("/api/skills/template-repository-maintainer/repository");
    const repository = payload?.repository || {};
    if (!repository.available || !repository.path) {
      throw new Error("模板仓库 HTML 尚未生成");
    }
    await openPath(repository.path);
    toast(`已打开${repository.label || "模板仓库"}`);
  } catch (error) {
    toast(`打开模板仓库失败：${error.message}`, "error");
  } finally {
    if (button) button.disabled = false;
  }
}

async function runTemplateRepositorySkill() {
  if (skillRuns.get("template-repository-maintainer")?.state === "running") return;
  const input = $("#templateRepositoryInput");
  const text = String(input?.value || "").trim();
  const paths = templateRepositoryInputFiles.map((file) => file.path).filter(Boolean);
  const files = templateRepositoryInputFiles.filter((file) => file.dataUrl).map(({ name, dataUrl }) => ({ name, dataUrl }));
  if (!text && !paths.length && !files.length) {
    input?.focus();
    toast("请粘贴公开链接、拖入本地文件/文件夹，或粘贴图片", "error");
    return;
  }
  const button = $("#templateRepositoryRunBtn");
  if (button) button.disabled = true;
  try {
    const started = await api("/api/skills/template-repository-maintainer/run", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ text, paths, files })
    });
    let current = started;
    skillRuns.set("template-repository-maintainer", current);
    renderTemplateRepositoryResult(current);
    renderSkillsCenter();
    while (current && ["queued", "running"].includes(current.state)) {
      await new Promise((resolve) => window.setTimeout(resolve, 900));
      const list = await api("/api/skills/template-repository-maintainer/tasks");
      current = Array.isArray(list) ? list.find((item) => item.id === started.id) || current : current;
      skillRuns.set("template-repository-maintainer", current);
      renderTemplateRepositoryResult(current);
      renderSkillsCenter();
    }
    toast(current?.state === "completed" ? "模板仓库更新完成" : "模板仓库未完全完成，请查看结果和缺口", current?.state === "completed" ? undefined : "error");
  } catch (error) {
    const failed = { id: `local-${Date.now()}`, state: "failed", progress: 0, error: { message: error.message } };
    skillRuns.set("template-repository-maintainer", failed);
    renderTemplateRepositoryResult(failed);
    renderSkillsCenter();
    toast(`模板仓库启动失败：${error.message}`, "error");
  } finally {
    if (button) button.disabled = false;
  }
}

function installTemplateRepositoryRunner() {
  const input = $("#templateRepositoryInput");
  const dropzone = $("#templateRepositoryDropzone");
  const fileInput = $("#templateRepositoryFileInput");
  if (!input || !dropzone || !fileInput || dropzone.dataset.bound === "true") return;
  dropzone.dataset.bound = "true";
  input.addEventListener("paste", async (event) => {
    const item = Array.from(event.clipboardData?.items || []).find((candidate) => String(candidate.type || "").startsWith("image/"));
    if (!item) return;
    const file = item.getAsFile?.();
    if (!file) return;
    event.preventDefault();
    await addTemplateRepositoryFiles([file]);
    toast("已接收剪贴板图片");
  });
  ["dragenter", "dragover"].forEach((type) => dropzone.addEventListener(type, (event) => {
    event.preventDefault();
    dropzone.classList.add("is-dragging");
  }));
  ["dragleave", "drop"].forEach((type) => dropzone.addEventListener(type, (event) => {
    event.preventDefault();
    dropzone.classList.remove("is-dragging");
  }));
  dropzone.addEventListener("drop", (event) => addTemplateRepositoryFiles(event.dataTransfer?.files));
  dropzone.addEventListener("click", (event) => {
    if (event.target.closest("button")) return;
    fileInput.click();
  });
  dropzone.addEventListener("keydown", (event) => {
    if (event.key === "Enter" || event.key === " ") { event.preventDefault(); fileInput.click(); }
  });
  $("#templateRepositoryPickBtn")?.addEventListener("click", () => fileInput.click());
  fileInput.addEventListener("change", async () => {
    await addTemplateRepositoryFiles(fileInput.files);
    fileInput.value = "";
  });
  $("#templateRepositoryRunBtn")?.addEventListener("click", () => runTemplateRepositorySkill());
  $("#templateRepositoryOpenBtn")?.addEventListener("click", () => openTemplateRepository());
  $("#templateRepositoryClearBtn")?.addEventListener("click", () => {
    input.value = "";
    templateRepositoryInputFiles.splice(0, templateRepositoryInputFiles.length);
    renderTemplateRepositoryFiles();
    renderTemplateRepositoryResult(null);
    const state = $("#templateRepositoryRunState");
    if (state) state.textContent = "自动识别输入 · 同步来源与全局模板仓库";
  });
}

function renderMaterialDownloadResult(job) {
  const state = $("#materialDownloadRunState");
  const resultEl = $("#materialDownloadResult");
  const button = $("#materialDownloadRunBtn");
  if (!resultEl) return;
  const jobState = String(job?.state || "queued");
  if (state) state.textContent = jobState === "succeeded"
    ? "下载完成"
    : jobState === "failed"
      ? "下载失败"
      : "正在下载…";
  if (button) button.disabled = ["queued", "running"].includes(jobState);
  if (["queued", "running"].includes(jobState)) {
    resultEl.innerHTML = `<div class="skill-result"><strong>正在执行素材下载</strong><span>已提交 ${Number(job?.inputCount || 0) || "多条"} 个链接，下载器会按谨慎频率逐条处理。</span><small>可以继续工作台其他页面，但请不要对同一批素材重复执行。</small></div>`;
    return;
  }
  const payload = job?.result || {};
  const items = Array.isArray(payload.items) ? payload.items : [];
  const summary = `成功 ${Number(payload.success || 0)} · 失败 ${Number(payload.failed || 0)} · 共 ${Number(payload.total || items.length || 0)}`;
  const rows = items.slice(0, 12).map((item) => `<li><span>${item.success ? "✓" : "!"}</span><strong>${escapeHtml(item.title || item.note_id || item.url || "未命名素材")}</strong><small>${item.success ? escapeHtml(item.save_dir || "已保存") : escapeHtml(item.error || "下载失败")}</small></li>`).join("");
  resultEl.innerHTML = `<div class="skill-result ${jobState === "succeeded" ? "is-success" : "is-error"}"><strong>${jobState === "succeeded" ? "素材下载完成" : "素材下载未完全成功"}</strong><span>${escapeHtml(summary)}</span>${job?.outputDir ? `<small>保存目录：${escapeHtml(job.outputDir)}</small><button type="button" class="secondary-button" id="openMaterialDownloadOutputBtn">打开下载目录</button>` : ""}${rows ? `<ul class="skill-result-list">${rows}</ul>` : ""}${job?.error?.message ? `<small class="skill-result-error">${escapeHtml(job.error.message)}</small>` : ""}</div>`;
  $("#openMaterialDownloadOutputBtn")?.addEventListener("click", () => openPath(job.outputDir).catch((error) => toast(`下载目录打开失败：${error.message}`, "error")));
}

async function openMaterialDownloadDirectory(skillId) {
  const skill = skillsCatalog.find((item) => item.id === skillId);
  const target = pageSettings().skills?.materialDownloadOutputDir || skill?.defaultOutputDir || "";
  if (!target) {
    toast("素材下载目录尚未配置", "error");
    return;
  }
  const button = document.querySelector(`[data-skill-download-open="${CSS.escape(skillId)}"]`);
  if (button) button.disabled = true;
  try {
    await openPath(target);
    toast("已打开素材下载目录");
  } catch (error) {
    toast(`下载目录打开失败：${error.message}`, "error");
  } finally {
    if (button) button.disabled = false;
  }
}

async function runMaterialDownloadSkillCard(skillId) {
  const input = document.querySelector(`[data-skill-material-input="${CSS.escape(skillId)}"]`);
  const button = document.querySelector(`[data-skill-download-run="${CSS.escape(skillId)}"]`);
  const text = String(input?.value || "").trim();
  if (!text) {
    input?.focus();
    toast("请先粘贴素材分享文案或链接", "error");
    return;
  }
  if (button) button.disabled = true;
  try {
    const outputDir = pageSettings().skills?.materialDownloadOutputDir || "";
    const started = await api("/api/skills/material-download/run", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ text, outputDir })
    });
    let current = started.job || started;
    skillRuns.set(skillId, { id: current.id, state: current.state, progress: current.progress, outputDir: current.outputDir || outputDir, result: current.result, error: current.error });
    renderSkillsCenter();
    while (current && ["queued", "running"].includes(current.state)) {
      await new Promise((resolve) => window.setTimeout(resolve, 1000));
      const payload = await api(`/api/skills/material-download/tasks/${encodeURIComponent(current.id)}`);
      current = payload.job || current;
      skillRuns.set(skillId, { id: current.id, state: current.state, progress: current.progress, outputDir: current.outputDir || outputDir, result: current.result, error: current.error });
      renderSkillsCenter();
    }
    toast(current?.state === "succeeded" ? "素材下载完成" : "素材下载未完全成功，请查看结果卡片", current?.state === "succeeded" ? undefined : "error");
  } catch (error) {
    skillRuns.set(skillId, { id: `local-${Date.now()}`, state: "failed", progress: 0, error: { message: error.message } });
    renderSkillsCenter();
    toast(`素材下载启动失败：${error.message}`, "error");
  }
}

async function runTemplateRepositorySkillCard(skillId) {
  const input = document.querySelector(`[data-skill-template-input="${CSS.escape(skillId)}"]`);
  const button = document.querySelector(`[data-template-repository-run="${CSS.escape(skillId)}"]`);
  const text = String(input?.value || "").trim();
  const paths = templateRepositoryQuickInputFiles.map((file) => file.path).filter(Boolean);
  const files = templateRepositoryQuickInputFiles.filter((file) => file.dataUrl).map(({ name, dataUrl }) => ({ name, dataUrl }));
  if (!text && !paths.length && !files.length) {
    input?.focus();
    toast("请先输入模板名称、描述、链接或本地路径，或拖入图片", "error");
    return;
  }
  if (button) button.disabled = true;
  try {
    const started = await api("/api/skills/template-repository-maintainer/run", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ text, paths, files })
    });
    templateRepositoryQuickInputFiles.splice(0, templateRepositoryQuickInputFiles.length);
    let current = started.task || started;
    skillRuns.set(skillId, current);
    renderSkillsCenter();
    while (current && ["queued", "running"].includes(current.state)) {
      await new Promise((resolve) => window.setTimeout(resolve, 900));
      const list = await api("/api/skills/template-repository-maintainer/tasks");
      current = Array.isArray(list) ? list.find((item) => item.id === current.id) || current : current;
      skillRuns.set(skillId, current);
      renderSkillsCenter();
    }
    toast(current?.state === "completed" ? "模板已收录" : "模板收录未完全完成，请查看结果和缺口", current?.state === "completed" ? undefined : "error");
  } catch (error) {
    const failed = { id: `local-${Date.now()}`, state: "failed", progress: 0, error: { message: error.message } };
    skillRuns.set(skillId, failed);
    renderSkillsCenter();
    toast(`模板收录启动失败：${error.message}`, "error");
  }
}

async function runMaterialDownloadSkill() {
  const input = $("#materialDownloadInput");
  const text = String(input?.value || "").trim();
  if (!text) {
    input?.focus();
    toast("请先粘贴素材分享文案或链接", "error");
    return;
  }
  const button = $("#materialDownloadRunBtn");
  if (button) button.disabled = true;
  try {
    const started = await api("/api/skills/material-download/run", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ text })
    });
    let current = started.job || started;
    renderMaterialDownloadResult(current);
    while (current && ["queued", "running"].includes(current.state)) {
      await new Promise((resolve) => window.setTimeout(resolve, 1000));
      const payload = await api(`/api/skills/material-download/tasks/${encodeURIComponent(current.id)}`);
      current = payload.job || current;
      renderMaterialDownloadResult(current);
    }
    if (current?.state === "succeeded") toast("素材下载完成");
    else toast("素材下载未完全成功，请查看结果卡片", "error");
  } catch (error) {
    renderMaterialDownloadResult({ state: "failed", result: { success: 0, failed: 1 }, error: { message: error.message } });
    toast(`素材下载启动失败：${error.message}`, "error");
  } finally {
    if (button) button.disabled = false;
  }
}

function restoreSelection() {
  const state = getSavedState();
  activateTab(window.MaterialWorkspace.resolveInitialTab(state.activeTab));
}

const WORKFLOW_RAIL_ORDER_STORAGE_KEY = "teambuilding-workflow-rail-order-v1";

function setupWorkflowRailSorting() {
  const rail = $("#workflowRail");
  if (!rail || rail.dataset.sortReady === "true") return;
  rail.dataset.sortReady = "true";
  const tabs = () => [...rail.querySelectorAll(":scope > .rail-tab[data-tab]")];
  const defaultOrder = tabs().map((tab) => tab.dataset.tab);
  let savedOrder = [];
  try {
    const parsed = JSON.parse(localStorage.getItem(WORKFLOW_RAIL_ORDER_STORAGE_KEY) || "[]");
    if (Array.isArray(parsed)) savedOrder = parsed.filter((id) => defaultOrder.includes(id));
  } catch (_) { savedOrder = []; }
  const order = [...savedOrder, ...defaultOrder.filter((id) => !savedOrder.includes(id))];
  order.forEach((id) => {
    const tab = rail.querySelector(`:scope > .rail-tab[data-tab="${CSS.escape(id)}"]`);
    if (tab) rail.insertBefore(tab, rail.querySelector(":scope > .rail-service"));
  });
  let dragged = null;
  tabs().forEach((tab) => {
    tab.draggable = true;
    tab.dataset.sortable = "true";
    tab.title = `${tab.title || tab.textContent.trim()} · 可拖动排序`;
    tab.addEventListener("dragstart", (event) => {
      dragged = tab;
      tab.classList.add("is-rail-dragging");
      event.dataTransfer.effectAllowed = "move";
      event.dataTransfer.setData("text/plain", tab.dataset.tab);
    });
    tab.addEventListener("dragover", (event) => {
      if (!dragged || dragged === tab) return;
      event.preventDefault();
      event.dataTransfer.dropEffect = "move";
      tab.classList.add("is-rail-drop-target");
    });
    tab.addEventListener("dragleave", () => tab.classList.remove("is-rail-drop-target"));
    tab.addEventListener("drop", (event) => {
      event.preventDefault();
      tab.classList.remove("is-rail-drop-target");
      if (!dragged || dragged === tab) return;
      const rect = tab.getBoundingClientRect();
      const insertBefore = event.clientY < rect.top + rect.height / 2;
      rail.insertBefore(dragged, insertBefore ? tab : tab.nextSibling);
      const nextOrder = tabs().map((item) => item.dataset.tab);
      localStorage.setItem(WORKFLOW_RAIL_ORDER_STORAGE_KEY, JSON.stringify(nextOrder));
      toast("左侧模块顺序已保存");
    });
    tab.addEventListener("dragend", () => {
      tabs().forEach((item) => item.classList.remove("is-rail-dragging", "is-rail-drop-target"));
      dragged = null;
    });
  });
}

function renderSettingsHome() {
  const modeKey = activeGptModeKey();
  const mode = GPT_MODE_DEFINITIONS[modeKey];
  const visibleAccounts = gptAccounts.filter((account) => !account.hidden);
  const enabledAccounts = visibleAccounts.filter((account) => !account.disabled);
  const activeAccount = gptAccounts.find((account) => account.id === activeGptAccountId);
  const currentMode = $("#settingsCurrentMode");
  const accountSummary = $("#settingsAccountSummary");
  const quotaSummary = $("#settingsQuotaSummary");
  const runSummary = $("#settingsRunSummary");
  const productionStatus = resolveCurrentProductionStatus();
  if (currentMode) currentMode.textContent = mode?.label || "人工控制";
  if (accountSummary) {
    accountSummary.textContent = `${enabledAccounts.length}/${visibleAccounts.length} 个已启用${activeAccount?.name ? ` · 当前 ${activeAccount.name}` : ""}`;
  }
  if (quotaSummary) {
    quotaSummary.textContent = `${Number(gptAutoSettings.generationLimit || 45)} 张 / ${Number(gptAutoSettings.windowHours || 3)} 小时 · 当前作品先收尾`;
  }
  if (runSummary) {
    runSummary.textContent = `${productionStatus.label} · ${productionStatus.message}`;
  }
}

function activateTab(name) {
  name = window.MaterialWorkspace.resolveInitialTab(name);
  if (name === "skills" && !isSkillCenterEnabled()) {
    toast("技能中心入口已停用，请先在中心设置中重新启用");
    openSkillsCenterSettingsPanel();
    return;
  }
  if (name === "moments" && !isMomentsFeatureEnabled()) {
    toast("朋友圈采集整理与发布已关闭，请从技能中心的朋友圈设置重新启用");
    name = "settings";
  }
  $$(".tab").forEach((tab) => {
    const active = tab.dataset.tab === name;
    tab.classList.toggle("active", active);
    if (active) tab.setAttribute("aria-current", "page");
    else tab.removeAttribute("aria-current");
  });
  $$(".view").forEach((view) => view.classList.remove("active"));
  $(`#${name}View`)?.classList.add("active");
  if (name === "materialLibrary") {
    hideWechatWebView();
    renderMaterialLibraryView();
    if (dashboard?.dashboardLite === true) {
      // The first paint is intentionally light.  The material-only shell
      // follows it with the full local index so the browser is immediately
      // useful without making the initial navigation wait for other modules.
      loadDashboard(false).then(() => {
        if (dashboard?.dashboardLite === true) return loadDashboard(false);
        return null;
      }).then(() => {
        if ($("#materialLibraryView")?.classList.contains("active")) renderMaterialLibraryView();
      }).catch((error) => {
        console.error("素材库读取失败", error);
        if ($("#materialLibraryStatus")) $("#materialLibraryStatus").textContent = "素材索引读取失败，请点击刷新重试";
      });
    }
  } else if (name === "gptProductionTest") {
    hideWechatWebView();
    renderGptProductionTest();
    if (dashboard?.dashboardLite === true) {
      // Content production needs the real material tree and template catalog;
      // the lightweight first paint only contains category counts.  Without
      // this follow-up, both libraries appear empty until another navigation.
      loadDashboard(false).then(() => {
        if (dashboard?.dashboardLite === true) return loadDashboard(false);
        return null;
      }).then(() => {
        if ($("#gptProductionTestView")?.classList.contains("active")) {
          renderGptProductionTest();
          renderGptTestMaterials();
          renderGptTestTemplates();
        }
      }).catch((error) => {
        console.error("内容制作素材/模板读取失败", error);
        if ($("#gptProductionTestView")?.classList.contains("active")) {
          showWorkbenchAssistantBubble("素材库或模板库读取失败，请点击内容制作重试；本地文件未被修改。", { duration: 5200, tone: "warning" });
        }
      });
    }
  } else if (window.gptWorkbench?.available) {
    window.gptWorkbench.hide().catch(() => {});
  }
  if (name === "works") {
    renderCollections();
    productsRendered = true;
    if (dashboard?.dashboardLite === true) {
      // A direct jump from the lightweight first paint previously rendered an
      // empty warehouse forever.  Request the full snapshot, and if that
      // request coalesced with the initial lite load, immediately follow it
      // with the real work-package scan.
      loadDashboard(false).then(() => {
        if (dashboard?.dashboardLite === true) return loadDashboard(false);
        return null;
      }).then(() => {
        if ($("#worksView")?.classList.contains("active")) renderCollections();
      }).catch((error) => {
        console.error("作品仓库读取失败", error);
        if ($("#worksView")?.classList.contains("active")) {
          const list = $("#worksList") || $("#collectionList");
          if (list) list.innerHTML = `<div class="empty-state"><strong>作品仓库读取失败</strong><p>请点击侧边栏的“作品仓库”重试；本地作品文件未被修改。</p></div>`;
        }
      });
    }
  }
  if (name === "distribution") {
    if (activeDistributionPanel === "official") activeDistributionPanel = "devices";
    renderDistribution();
    if (dashboard?.dashboardLite === true) {
      loadDashboard(false).then(() => {
        // If navigation happened while the initial lite request was still in
        // flight, the coalesced response is still lite. Chain the real scan
        // instead of leaving the publishing library in a permanent loading
        // state.
        if (dashboard?.dashboardLite === true) return loadDashboard(false);
        return null;
      }).then(() => {
        if ($("#distributionView")?.classList.contains("active")) {
          renderDistribution();
          showDistributionPanel(activeDistributionPanel);
        }
      }).catch(() => {});
    }
    showDistributionPanel(activeDistributionPanel);
    if (!deviceScanStarted) {
      checkDistributionDevices({ silent: true, refreshInventory: false });
    }
  } else if (name === "publishing") {
    activeDistributionPanel = "official";
    renderDistribution();
    if (dashboard?.dashboardLite === true) {
      loadDashboard(false).then(() => {
        // See the distribution branch above: an early click can coalesce with
        // the lite first-paint request, so explicitly follow it with a full
        // distribution scan when necessary.
        if (dashboard?.dashboardLite === true) return loadDashboard(false);
        return null;
      }).then(() => {
        if ($("#publishingView")?.classList.contains("active")) {
          const selectedPlatform = $("[data-publishing-platform].active")?.dataset.publishingPlatform || "wechat";
          renderDistribution();
          const currentPlatform = $("[data-publishing-platform].active")?.dataset.publishingPlatform || "wechat";
          if (currentPlatform !== selectedPlatform) return;
          $("#distributionOfficial")?.classList.add("active");
          setPublishingPlatform(selectedPlatform);
        }
      }).catch(() => {});
    }
    $("#distributionOfficial")?.classList.add("active");
    // The full library scan can finish after the user has already selected a
    // platform. Read the current tab at the last possible moment so the
    // background initialization never jumps back to WeChat unexpectedly.
    setPublishingPlatform(activePublishingPlatformId());
    refreshPlatformPublishingCatalog().catch(() => {});
    if (wechatWebEditorOpen) window.setTimeout(() => showWechatWebView().catch(() => {}), 60);
  } else {
    hideWechatWebView();
  }
  if (name === "conversion") {
    // 首次进入即渲染内置 SOP；完整历史/方案资料在后台同步，不阻塞页面可用性。
    if (!conversionData) {
      conversionData = createBuiltinConversionSnapshot();
      renderConversionHub();
    }
    loadConversionHub().catch(() => {});
  }
  if (name === "skills") {
    loadSkillsCatalog().catch(() => {});
  }
  if (name === "workflow" && !logsRendered) {
    renderLogs();
    logsRendered = true;
  }
  if (name === "juguang" && !juguangRendered) {
    loadJuguang().catch((error) => {
      console.error(error);
      toast("聚光数据读取失败");
    });
    juguangRendered = true;
  }
  if (name === "settings") {
    applyTheme(localStorage.getItem("tb-dashboard-theme") || "neo");
    renderPageSettingsValues();
    renderSettingsHome();
    loadDedupStatus().catch((error) => {
      if ($("#dedupSummary")) $("#dedupSummary").textContent = `防重复账本读取失败：${error.message}`;
    });
  }
  if (name === "skills") {
    renderSkillsCenter();
    loadSkillsCatalog().catch(() => {});
    window.dispatchEvent(new CustomEvent("tb-skills-activated"));
  }
  showAssistantTipForActiveView();
  saveLocalState({ activeTab: name });
}

