      if (!paths.length) return;
      const confirmed = await openSystemDialog({
        eyebrow: "发送外部文件",
        title: `发送 ${paths.length} 项到当前设备？`,
        description: "工作台只引用资源管理器中的原路径；不会移动、改名、删除或修改原文件。",
        details: paths.slice(0, 8).map((item, index) => ({ label: `项目 ${index + 1}`, value: item })),
        cancelLabel: "取消",
        confirmLabel: "立即发送"
      });
      if (!confirmed) return;
