    if (!validation.ok) return; // silent — let the user finish typing
    gptModeProfiles[key] = { ...(gptModeProfiles[key] || {}), steps: validation.steps, useCurrentSession: $("#gptModeStartBehavior")?.value !== "inject" };
    saveGptModeProfiles();
