  $("#publishingAdapterPanel")?.addEventListener("click", async (event) => {
    const checkButton = event.target.closest("[data-check-platform]");
    const toolsButton = event.target.closest("[data-list-platform-tools]");
    const copyConfigButton = event.target.closest("[data-copy-platform-config]");
    const refreshPlatformButton = event.target.closest("[data-refresh-platform-publishing]");
    const retryButton = event.target.closest("[data-retry-platform-publish]");
    const manualOpenButton = event.target.closest("[data-manual-open]");
    const manualCopyButton = event.target.closest("[data-manual-copy]");
    const copyPackageButton = event.target.closest("[data-copy-platform-package]");
    const manualPrepareButton = event.target.closest("[data-prepare-manual-platform]");
    const prepareButton = event.target.closest("[data-prepare-platform]");
    const confirmButton = event.target.closest("[data-confirm-platform]");
    const button = checkButton || toolsButton || copyConfigButton || refreshPlatformButton || retryButton || manualOpenButton || manualCopyButton || copyPackageButton || manualPrepareButton || prepareButton || confirmButton;
    if (!button) return;
    if (refreshPlatformButton) {
      const activePlatform = $("[data-publishing-platform].active")?.dataset.publishingPlatform || "wechat";
      refreshPlatformButton.disabled = true;
      refreshPlatformButton.textContent = "正在刷新…";
      try {
        await loadPlatformPublishingPanel(activePlatform, { force: true });
      } finally {
        refreshPlatformButton.disabled = false;
      }
      return;
    }
    if (copyConfigButton) {
      const platformInfo = platformPublishingCatalog.find((item) => item.id === copyConfigButton.dataset.copyPlatformConfig);
      if (!platformInfo) return;
      try {
        await copyText(platformPublishingConfigExample(platformInfo), "配置模板已复制");
      } catch (error) {
        showSystemNotice("配置模板复制失败", error.message, { tone: "warning" });
      }
      return;
    }
    if (manualOpenButton) {
      const openButton = manualOpenButton;
      const platformId = openButton.closest(".publishing-compose")?.querySelector("[data-prepare-platform]")?.dataset.preparePlatform || $("[data-publishing-platform].active")?.dataset.publishingPlatform || "";
      const platformInfo = platformPublishingCatalog.find((item) => item.id === platformId);
      const platformName = platformInfo?.name || "当前平台";
      try {
        await openExternal(openButton.dataset.manualUrl || platformInfo?.handoffUrl || "#");
        toast(`已打开${platformName}官方页面；请在页面完成上传和发布确认`);
      } catch (error) {
        showSystemNotice(`${platformName}官方页面打开失败`, error.message, { tone: "warning" });
      }
      return;
    }
    if (manualCopyButton) {
      const copyButton = manualCopyButton;
      const compose = copyButton.closest(".publishing-compose");
      const platformId = compose?.querySelector("[data-prepare-platform]")?.dataset.preparePlatform || $("[data-publishing-platform].active")?.dataset.publishingPlatform || "";
      const platformName = platformPublishingCatalog.find((item) => item.id === platformId)?.name || "当前平台";
      try {
        await copyText(readManualHandoffText(compose, platformName), `${platformName}发布内容已复制`);
      } catch (error) {
        showSystemNotice(`${platformName}内容复制失败`, error.message, { tone: "warning" });
      }
      return;
    }
    if (copyPackageButton) {
      try {
        await copyText(readPlatformHandoffText(copyPackageButton.closest(".publishing-compose")), "发布包内容已复制");
      } catch (error) {
        showSystemNotice("发布包复制失败", error.message, { tone: "warning" });
      }
      return;
    }
    if (manualPrepareButton) {
      const manualButton = manualPrepareButton;
      const platformId = manualButton.dataset.preparePlatform || "";
      const platformName = platformPublishingCatalog.find((item) => item.id === platformId)?.name || "当前平台";
      if (publishingSelectedWork?.id && !publishingWorkEligibility(publishingSelectedWork, platformId).eligible) {
        showSystemNotice(`${platformName}已使用这篇成品`, "本平台不会再次自动复用；请换一篇未使用的成品。", { tone: "warning" });
        return;
      }
      manualButton.disabled = true;
      manualButton.textContent = "正在校验…";
      try {
        const payload = readPlatformPublishingForm(manualButton);
        const result = await api("/api/platform-publishing/prepare", {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify(payload)
        });
        platformPublishingPrepared = { payload, result };
        renderManualHandoffPreflight(manualButton.closest(".publishing-compose"), result);
        toast(`${platformName}发布包已准备，请复制并在官方页面完成发布`);
      } catch (error) {
        showSystemNotice(`${platformName}发布包校验失败`, error.message, { tone: "warning" });
      } finally {
        manualButton.disabled = false;
        manualButton.textContent = "准备发布包";
      }
      return;
    }
    if (retryButton) {
      platformPublishingPrepared = null;
      const preflight = retryButton.closest("[data-publishing-preflight]");
      if (preflight) {
        preflight.hidden = true;
        preflight.innerHTML = "";
      }
      toast("已退回发布前校验；请重新准备并核对，避免重复发布");
      return;
    }
    if (prepareButton) {
      const platformId = prepareButton.dataset.preparePlatform || activePublishingPlatformId();
      const platformName = publishingPlatformName(platformId);
      if (publishingSelectedWork?.id && !publishingWorkEligibility(publishingSelectedWork, platformId).eligible) {
        showSystemNotice(`${platformName}已使用这篇成品`, "本平台不会再次自动复用；请换一篇未使用的成品。", { tone: "warning" });
        return;
      }
      button.disabled = true;
      button.textContent = "正在校验…";
      try {
        const payload = readPlatformPublishingForm(button);
        const result = await api("/api/platform-publishing/prepare", {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify(payload)
        });
        platformPublishingPrepared = { payload, result };
        renderPlatformPublishingPreflight(result);
        toast("发布包已准备，请核对后再确认");
      } catch (error) {
        showSystemNotice("发布包校验失败", error.message, { tone: "warning" });
      } finally {
        button.disabled = false;
        button.textContent = "准备发布";
      }
      return;
    }
    if (confirmButton) {
      if (!platformPublishingPrepared?.payload) {
        showSystemNotice("发布确认失效", "请重新点击“准备发布”并核对内容。", { tone: "warning" });
        return;
      }
      button.disabled = true;
      button.textContent = "正在提交…";
      const statusNode = button.closest("[data-publishing-preflight]")?.querySelector("[data-publishing-task-status]");
      try {
        const result = await api("/api/platform-publishing/publish", {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ ...platformPublishingPrepared.payload, confirmed: true })
        });
        renderPlatformPublishingTaskStatus(statusNode, result);
        pollPlatformPublishingTask(result.id, statusNode);
      } catch (error) {
        if (statusNode) statusNode.textContent = `发布提交失败：${error.message}`;
        showSystemNotice("平台发布失败", error.message, { tone: "warning" });
      } finally {
        button.textContent = "已提交";
      }
      return;
    }
    const isToolsRequest = Boolean(toolsButton);
    const isAiToEarnRest = button.dataset.adapterMode === "aitoearn-rest";
    button.disabled = true;
    button.textContent = isToolsRequest ? "正在发现…" : isAiToEarnRest ? "正在检查…" : "正在检查…";
    try {
      const result = await api(isToolsRequest ? "/api/platform-publishing/tools" : "/api/platform-publishing/check", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ platform: button.dataset.checkPlatform || button.dataset.listPlatformTools })
      });
      if (isToolsRequest) {
        const names = (result.tools || []).map((tool) => tool.name).filter(Boolean);
        toast(names.length ? `已发现 ${names.join("、")}` : "MCP 已连接，但没有返回工具");
      } else {
        if (isAiToEarnRest) renderAiToEarnPlatformMetadata($("#publishingAdapterPanel"), result.result?.platforms || []);
        toast(result.result?.message || "适配器连接检查完成");
      }
    } catch (error) {
      showSystemNotice(isToolsRequest ? "MCP 工具发现失败" : "适配器检查失败", error.message, { tone: "warning" });
    } finally {
      button.disabled = false;
      button.textContent = isToolsRequest ? "发现 MCP 工具" : isAiToEarnRest ? "检查 AiToEarn 接口" : "检查适配器登录状态";
    }
  });
