// === Diagnostic & Auto-Recovery System ===
// Expose diagnostic function on window for external debugging
window.tbGptDiagnostic = async function(accountId = activeGptAccountId) {
  if (!window.gptWorkbench?.diagnostic) {
    return { ok: false, error: "diagnostic method not available in this version" };
  }
  try {
    const result = await window.gptWorkbench.diagnostic(accountId);
    console.log("[TB Diagnostic]", JSON.stringify(result, null, 2));
    return result;
  } catch (error) {
    return { ok: false, error: error.message, accountId };
  }
};

// Readiness recovery is bounded per browser window.  It records the same
// durable timing fields as a workflow step, then leaves the window in a
// recoverable state when the budget is exhausted instead of scheduling a
// timer forever.
const GPT_PRODUCTION_RETRY_DELAY = 30_000;
function logGptReadinessRecoveryEvent(accountId, event, state = {}, detail = "", recoveryType = "production-readiness") {
  const key = String(accountId || activeGptAccountId || "account-1");
  // Independent browser workers do not share the visible legacy queue.  The
  // old global lookup made account-2 recovery telemetry carry account-4's
  // requestId/material, which polluted health audits and made a healthy lane
  // look like it was recovering another account's task.
  const worker = gptWindowWorkerState(key);
  const task = worker?.lastFailedTask
    || worker?.queue?.[Math.max(0, Number(worker.queueIndex || 0))]
    || (key === String(activeGptAccountId || "") ? gptTestQueue[gptTestQueueIndex] : null);
  api("/api/gpt-production/conversation-log", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({
      event,
      requestId: String(task?.requestId || ""),
      account: key,
      conversationUrl: String(task?.conversationUrl || task?.conversation || ""),
      materialName: String(task?.materialName || task?.name || ""),
      step: "prepare-readiness",
      status: String(state.status || "waiting"),
      startedAt: state.startedAt ? new Date(state.startedAt).toISOString() : "",
      endedAt: state.endedAt ? new Date(state.endedAt).toISOString() : "",
      elapsedMs: state.startedAt ? Math.max(0, Number(state.endedAt || Date.now()) - Number(state.startedAt)) : 0,
      deadlineAt: state.deadlineAt ? new Date(state.deadlineAt).toISOString() : "",
      waitLimitMs: state.deadlineAt && state.startedAt ? Math.max(0, Number(state.deadlineAt) - Number(state.startedAt)) : 0,
      attempt: Math.max(0, Number(state.attempts || 0)),
      meta: {
        detail: String(detail || ""),
        recoveryType,
        maxAttempts: recoveryType === "window-reconnect"
          ? GPT_WINDOW_RECOVERY_MAX_ATTEMPTS
          : GPT_PRODUCTION_READINESS_RECOVERY_MAX_ATTEMPTS,
        budgetMs: recoveryType === "window-reconnect"
          ? GPT_WINDOW_RECOVERY_BUDGET_MS
          : GPT_PRODUCTION_READINESS_RECOVERY_BUDGET_MS
      }
    })
  }).catch(() => { /* telemetry failure must not affect the recovery decision */ });
}

function clearGptProductionReadinessRecovery(accountId) {
  const key = String(accountId || activeGptAccountId || "account-1");
  const timer = gptProductionRetryTimers.get(key);
  if (timer) clearTimeout(timer);
  gptProductionRetryTimers.delete(key);
  gptProductionRetryStates.delete(key);
  return key;
}

function exhaustGptProductionReadinessRecovery(accountId, state, detail = "GPT 页面在有限恢复预算内仍未就绪") {
  const key = clearGptProductionReadinessRecovery(accountId);
  const endedAt = Date.now();
  const currentTask = gptTestQueue[gptTestQueueIndex];
  if (currentTask && String(currentTask.accountId || key) === key) {
    currentTask._status = "retry-wait";
    currentTask._errorCode = "GPT_READINESS_RECOVERY_EXHAUSTED";
    currentTask._error = String(detail);
    currentTask._readinessRecoveryStartedAt = Number(state?.startedAt || endedAt);
    currentTask._readinessRecoveryDeadlineAt = Number(state?.deadlineAt || endedAt);
    currentTask._readinessRecoveryAttempts = Number(state?.attempts || 0);
  }
  writeGptWindowRuntime(key, {
    status: "retry-wait",
    currentStage: "生产助手就绪恢复已到时限，保留检查点",
    nextRetryAt: null,
    lastError: String(detail),
    readinessRecoveryStartedAt: Number(state?.startedAt || endedAt),
    readinessRecoveryDeadlineAt: Number(state?.deadlineAt || endedAt),
    readinessRecoveryAttempts: Number(state?.attempts || 0),
    readinessRecoveryExhaustedAt: endedAt
  });
  persistGptQueue();
  logGptReadinessRecoveryEvent(key, "readiness-recovery-exhausted", {
    ...state,
    endedAt,
    status: "timeout"
  }, detail);
  showWorkbenchAssistantBubble(`${gptAccounts.find((item) => item.id === key)?.name || key} 的 GPT 就绪检查已到时限；已保留检查点并隔离本窗口，不影响其他账号。`, { duration: 0, tone: "warning" });
  return { ok: false, exhausted: true, accountId: key, error: String(detail) };
}

function scheduleGptProductionRetry(accountId, attempt = 1) {
  const key = String(accountId || activeGptAccountId || "account-1");
  if (gptProductionRetryTimers.has(key)) return { ok: true, scheduled: false, accountId: key };
  const now = Date.now();
  const existing = gptProductionRetryStates.get(key) || {};
  const state = {
    startedAt: Number(existing.startedAt || now),
    deadlineAt: Number(existing.deadlineAt || (now + GPT_PRODUCTION_READINESS_RECOVERY_BUDGET_MS)),
    attempts: Math.max(Number(existing.attempts || 0), Number(attempt || 1)),
    status: "waiting"
  };
  if (now >= state.deadlineAt || state.attempts > GPT_PRODUCTION_READINESS_RECOVERY_MAX_ATTEMPTS) {
    return exhaustGptProductionReadinessRecovery(key, state, "GPT 页面在有限恢复预算内仍未就绪");
  }
  gptProductionRetryStates.set(key, state);
  const accountName = gptAccounts.find((item) => item.id === key)?.name || key;
  showWorkbenchAssistantBubble(
    `${accountName} 尚未就绪，${GPT_PRODUCTION_RETRY_DELAY / 1000} 秒后自动重试（第 ${state.attempts}/${GPT_PRODUCTION_READINESS_RECOVERY_MAX_ATTEMPTS} 次；截止 ${new Date(state.deadlineAt).toLocaleTimeString("zh-CN", { hour12: false })}）...`,
    { duration: GPT_PRODUCTION_RETRY_DELAY, tone: "info" }
  );
  writeGptWindowRuntime(key, {
    status: "retry-wait",
    currentStage: "等待生产助手就绪",
    nextRetryAt: now + GPT_PRODUCTION_RETRY_DELAY,
    lastError: "生产助手尚未就绪",
    readinessRecoveryStartedAt: state.startedAt,
    readinessRecoveryDeadlineAt: state.deadlineAt,
    readinessRecoveryAttempts: state.attempts,
    readinessRecoveryExhaustedAt: null
  });
  logGptReadinessRecoveryEvent(key, "readiness-retry-scheduled", state, "生产助手尚未就绪");
  const timer = setTimeout(async () => {
    gptProductionRetryTimers.delete(key);
    const preflight = await window.gptWorkbench.status(accountId).catch(() => null);
    if (preflight?.productionReady) {
      const finished = { ...gptProductionRetryStates.get(key), endedAt: Date.now(), status: "completed" };
      clearGptProductionReadinessRecovery(key);
      showWorkbenchAssistantBubble(`${accountName} 已就绪，自动恢复生产。`, { duration: 3000, tone: "success" });
      logGptReadinessRecoveryEvent(key, "readiness-recovered", finished, "生产助手已就绪");
      writeGptWindowRuntime(key, {
        status: "running",
        currentStage: "生产助手已就绪，恢复当前检查点",
        nextRetryAt: null,
        lastError: "",
        readinessRecoveryStartedAt: null,
        readinessRecoveryDeadlineAt: null,
        readinessRecoveryAttempts: finished.attempts || 0,
        readinessRecoveryExhaustedAt: null
      });
      gptQueuePaused = false;
      persistGptQueue();
      sendNextGptTestTask({ accountId: key, userInitiated: false, continuousResume: true, allowWindowSwitch: true }).catch(() => {});
    } else {
      const current = gptProductionRetryStates.get(key) || state;
      scheduleGptProductionRetry(key, Number(current.attempts || state.attempts) + 1);
    }
  }, GPT_PRODUCTION_RETRY_DELAY);
  gptProductionRetryTimers.set(key, timer);
  return { ok: true, scheduled: true, accountId: key, deadlineAt: state.deadlineAt, attempts: state.attempts };
}

// Queue auto-recovery lives in an isolated controller so readiness checks can
// be tested without loading the entire renderer. The controller deliberately
// awaits a second status check before it resumes a persisted queue.
async function resumeImageUncertaintyCheckpoint({ task, accountId }) {
  const currentTask = gptTestQueue[gptTestQueueIndex];
  if (!task || currentTask !== task) return false;
  if (String(task._errorCode || "") !== "IMAGE_COUNT_UNCERTAIN") return false;
  if (task._submittedToGpt !== true || gptAutoRunning) return false;
  if (gptWindowIsUserStopped(accountId) || gptWindowIsUserPaused(accountId)) return false;

  const previousRequestId = String(task.requestId || "");
  task.requestId = `gpt-image-recovery-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
  task.retryOf = previousRequestId;
  task.retryFromStage = String(task._stage || "等待图片");
  task.retryFromPercent = Math.max(48, Number(task._percent || 48));
  task.forceUpload = false;
  task._submittedToGpt = true;
  task._status = "queued";
  task._stage = "图片已生成，恢复文案与归档";
  task._error = "";
  task._errorCode = "";
  task._imageUncertainRecoveryCount = Math.max(0, Number(task._imageUncertainRecoveryCount || 0)) + 1;
  gptLastFailedTask = null;
  gptLastFailedStage = "";
  gptLastFailedPercent = 0;
  gptAutoPaused = false;
  // Keep this true until the rotation runner enters. It is the durable signal
  // that the existing queue must be reused instead of rebuilt from materials.
  gptQueuePaused = true;
  writeGptWindowRuntime(accountId, {
    status: "running",
    currentTaskId: task.requestId,
    currentStage: task._stage,
    currentPercent: task.retryFromPercent
  });
  persistGptQueue();
  const recoveryImageCount = Math.max(1, Number(task.workflow?.plannedImageCount || task.expectedImages || 1));
  showWorkbenchAssistantBubble(`检测到当前作品的 ${recoveryImageCount} 张图片已经生成完成；正在从原检查点继续文案、下载和归档，不会重复上传素材。`, {
    duration: 6000,
    tone: "success"
  });
  await sendNextGptTestTask({
    accountId,
    userInitiated: false,
    continuousResume: true,
    allowWindowSwitch: true
  });
  return true;
}

async function resumeRestartInterruptedCheckpoint({ task, accountId }) {
  const currentTask = gptTestQueue[gptTestQueueIndex];
  if (!task || currentTask !== task) return false;
  if (String(task._errorCode || "") !== "RESTART_INTERRUPTED") return false;
  if (task._submittedToGpt !== true || gptAutoRunning) return false;
  if (gptWindowIsUserStopped(accountId) || gptWindowIsUserPaused(accountId)) return false;

  const previousRequestId = String(task.requestId || "");
  task.requestId = `gpt-restart-recovery-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
  task.retryOf = previousRequestId;
  task.retryFromStage = String(task._stage || "等待图片");
  task.retryFromPercent = Math.max(48, Number(task._percent || 48));
  task.forceUpload = false;
  task._submittedToGpt = true;
  task._status = "queued";
  task._stage = "网页已完成，恢复文案与归档";
  task._error = "";
  task._errorCode = "";
  gptLastFailedTask = null;
  gptLastFailedStage = "";
  gptLastFailedPercent = 0;
  gptAutoPaused = false;
  gptQueuePaused = true;
  setContinuousGptProductionArmed(true);
  writeGptWindowRuntime(accountId, {
    status: "running",
    pausedByUser: false,
    currentTaskId: task.requestId,
    currentStage: task._stage,
    currentPercent: task.retryFromPercent
  });
  persistGptQueue();
  showWorkbenchAssistantBubble("检测到重启前的图片已在 GPT 网页完成；正在从原检查点继续文案、下载和归档，不会重复上传素材。", {
    duration: 6000,
    tone: "success"
  });
  await sendNextGptTestTask({
    accountId,
    userInitiated: false,
    continuousResume: true,
    allowWindowSwitch: true
  });
  return true;
}

const gptRuntimeRecoveryController = window.TBGptRuntimeRecovery?.createController({
  getActiveAccountId: () => activeGptAccountId,
  getState: () => {
    const currentTask = gptTestQueue[gptTestQueueIndex];
    const recoveryAccountId = String(currentTask?.accountId || activeGptAccountId);
    return {
      queuePaused: gptQueuePaused,
      autoRunning: gptAutoRunning,
      autoPaused: gptAutoPaused,
      continuousMode: isContinuousGptMode(),
      continuousArmed: isContinuousGptProductionArmed(),
          retryPending: gptProductionRetryTimers.size > 0,
      windowStopped: gptWindowIsUserStopped(recoveryAccountId),
      windowPaused: gptWindowIsUserPaused(recoveryAccountId),
      currentTask: gptTestQueue[gptTestQueueIndex]
    };
  },
  status: (accountId) => window.gptWorkbench?.status?.(accountId),
  inspect: (accountId) => window.gptWorkbench?.inspectStatus?.(accountId),
  resumeImageUncertainty: async ({ task, accountId }) => resumeImageUncertaintyCheckpoint({ task, accountId }),
  resumeRestartCheckpoint: async ({ task, accountId }) => resumeRestartInterruptedCheckpoint({ task, accountId }),
  setQueuePaused: (value) => { gptQueuePaused = Boolean(value); },
      resetRetryCount: () => { gptProductionRetryStates.clear(); },
  persistQueue: () => persistGptQueue(),
  showBubble: (message, options) => showWorkbenchAssistantBubble(message, options),
  sendNext: (options) => sendNextGptTestTask(options)
});
window.setInterval(() => {
  gptRuntimeRecoveryController?.checkPausedQueue().catch(() => {});
}, 120_000);
window.setTimeout(() => {
  gptRuntimeRecoveryController?.checkPausedQueue().catch(() => {});
}, 5_000);

// Auto-start continuous production queue on startup
window.setTimeout(() => {
  try {
    const testTab = document.querySelector('.rail-tab-test, button[data-tab="gptProductionTest"]');
    if (testTab) testTab.click();
    if (typeof continueGptQueueFromUser === 'function') {
      continueGptQueueFromUser({ userInitiated: false }).catch(() => {});
    }
  } catch (e) {}
}, 4000);
